INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C1','kor',6,1,'u4',1,'관용 표현의 뜻 — 오래 쓰이면서 통째로 굳어져 낱말 하나하나의 뜻을 더한 것과는 다른 새로운 뜻을 지닌 말로, 「입을 모으다」는 실제로 입을 모은 것이 아니라 여럿이 같은 말을 한다는 뜻이다',ARRAY['6국04-03 문법']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C2','kor',6,1,'u4',1,'관용 표현 가려내기 — 낱말 뜻을 그대로 더했을 때 말이 통하면(가방을 열다 · 창문을 닦다) 관용 표현이 아니고, 뜻이 엉뚱하게 달라지면(눈코 뜰 새 없다) 관용 표현이다',ARRAY['6국04-03 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C3','kor',6,1,'u4',1,'관용어와 속담 — 관용어는 두 개 이상의 낱말이 합쳐져 새로운 뜻을 이루고 오래 쓰여 굳어진 말이고, 속담은 예로부터 전해 오며 조상의 삶에서 얻은 지혜나 교훈을 담은 말이며, 둘을 묶어 관용 표현이라 한다 — 굳어진 말이라는 점은 같고 교훈을 담고 전해 오는가에서 갈린다',ARRAY['6국04-03 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C4','kor',6,1,'u4',1,'관용 표현을 쓰면 좋은 점 — 길게 설명할 말을 짧은 한마디로 전해 효과적이고, 듣는 사람이 장면을 떠올리게 되어 이야기가 생생해지며, 예부터 전해 오는 말 속에 조상의 생활과 생각, 곧 우리 문화가 담겨 있다',ARRAY['6국04-03 문법']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C5','kor',6,1,'u4',1,'굳어진 모양 그대로 — 관용 표현은 통째로 굳은 말이라 낱말을 바꾸거나 풀어 늘이면(눈을 뜨고 코도 뜰 새가 없었다) 뜻을 잃으므로 모양 그대로 익혀 둔다',ARRAY['6국04-03 문법']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C6','kor',6,1,'u4',1,'많이 넣을수록 좋은 것이 아니다 — 관용 표현을 쓰는 것이 언제나 효과적인 것은 아니며, 상황과 어긋난 표현이 섞이면 오히려 뜻이 흐려지므로 먼저 볼 것은 표현의 개수가 아니라 지금 이 상황에 어울리는가이다',ARRAY['6국04-03 문법']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C7','kor',6,1,'u4',1,'상황에 알맞게 쓰기 — 표현의 뜻과 말하려는 상황이 맞물릴 때만 힘이 생기므로, 표현의 뜻을 풀어 넣어 보아 말이 어색해지면(생일 축하 자리에서 「진땀을 뺐겠구나」) 알맞지 않게 쓴 것이다',ARRAY['6국04-03 문법']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C8','kor',6,1,'u4',2,'관용어 뜻 짐작하기 — 대화 속 관용어는 앞뒤 상황을 보면 뜻을 짐작할 수 있으며, 정확한 뜻을 몰라도 괜찮으니 장면을 떠올려 짐작하는 것부터 시작하고 짐작한 뒤에 사전에서 확인하면 오래 남는다',ARRAY['6국04-03 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C9','kor',6,1,'u4',2,'뜻과 쓸 상황을 함께 — 귀가 밝다(소식이나 정보를 남보다 빨리 알아챈다) · 걱정 붙들어 매다(걱정하지 말라고 안심시키다) · 진땀을 빼다(어려운 일을 겪으며 몹시 애를 쓰다)처럼 뜻을 익힐 때에는 어떤 상황에서 쓰는 말인지까지 붙여 두어야 내 말이 된다 — 뜻만 외우면 금방 잊는다',ARRAY['6국04-03 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C10','kor',6,1,'u4',2,'몸을 가리키는 말이 든 관용어 — 입 · 어깨 · 귀처럼 몸의 한 부분이 든 관용어는 눈에 보이는 몸으로 눈에 보이지 않는 마음이나 태도를 나타낸 것이라, 「어깨가 무겁다」는 어깨가 아니라 책임이 커서 마음이 무겁다는 뜻이다',ARRAY['6국04-03 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C11','kor',6,1,'u4',2,'매체 속 관용어 — 학교 방송 뉴스처럼 말로 전하는 매체에도, 학급 알림장처럼 글로 전하는 매체에도 관용어가 놓이며, 매체가 달라도 관용어는 전하려는 뜻을 짧고 또렷하게 만드는 같은 일을 한다',ARRAY['6국04-03 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C12','kor',6,1,'u4',2,'같은 낱말로 묶어 익히기 — 「입」이 든 관용어(입이 무겁다 · 입을 모으다 · 입에 침이 마르다)처럼 같은 낱말로 묶으면 여러 표현을 한꺼번에 익힐 수 있으나, 그 낱말이 들어 있어도 뜻이 낱말 그대로라면(입을 헹구다) 관용어가 아니다',ARRAY['6국04-03 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C13','kor',6,1,'u4',2,'모르는 관용어 찾는 순서 — 앞뒤 상황을 보고 먼저 뜻을 짐작하고 → 국어사전에서 중심이 되는 낱말을 찾고(귀가 밝다 → 귀) → 뜻풀이 아래쪽에 딸린 관용구와 속담을 살피고 → 짐작한 뜻과 맞춰 보며, 사전을 먼저 펴지 않는 것이 중요하다',ARRAY['6국04-03 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C14','kor',6,1,'u4',3,'속담의 뜻과 힘 — 속담은 예로부터 전해 오는 말로 장면 하나로 말해 머리에 오래 남고 · 어떻게 하는 것이 나은지 교훈을 담고 · 여러 사람이 알아 풀어 설명하지 않아도 통하므로 간결하면서도 효과적이다(빈 수레가 요란하다 — 잘 알지 못하는 사람이 오히려 더 떠든다)',ARRAY['6국04-03 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C15','kor',6,1,'u4',3,'속담이 그리는 장면 풀기 — 빈 수레(짐이 없으면 덜컹거려 더 시끄러움) · 첫술(밥을 뜬 첫 숟가락으로는 배가 부를 리 없음 — 무슨 일이든 한 번에 큰 성과를 얻기 어렵다) · 가랑비(가는 비에도 어느새 다 젖음 — 사소한 것이 쌓여 큰 것이 된다)처럼 장면을 풀면 뜻이 따라온다',ARRAY['6국04-03 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C16','kor',6,1,'u4',3,'속담 속 옛말은 낡은 것이 아니다 — 속담에는 오늘날 잘 쓰지 않는 옛말이나 옛 생활 모습(수레 · 서당 · 풍월)이 남아 있는데, 그 낯섦은 버릴 말이라는 표시가 아니라 조상의 생각과 생활이 말에 남은 흔적이므로 무엇을 가리키는 말인지 찾아본다',ARRAY['6국04-03 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C17','kor',6,1,'u4',3,'뜻이 비슷한 속담 — 첫술에 배부르랴와 급할수록 돌아가라, 가랑비에 옷 젖는 줄 모른다와 바늘 도둑이 소도둑 된다처럼 뜻이 비슷한 속담도 기우는 방향이 조금씩 달라(바늘 도둑은 나쁜 일이 커지는 쪽), 바꿔 쓸 수 있는지는 뜻만이 아니라 어떤 상황에 쓰는 말인지까지 견주어 정한다',ARRAY['6국04-03 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C18','kor',6,1,'u4',3,'속담 찾는 방법 — 속담 사전 · 국어사전 · 인터넷 사전 어느 쪽이든 속담에서 중심이 되는 낱말을 앞세워 찾으며(빈 수레가 요란하다 → 수레), 사전을 첫 쪽부터 넘기거나 짐작한 뜻을 그대로 정답으로 삼지 않는다',ARRAY['6국04-03 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C19','kor',6,1,'u4',3,'속담 바꾸어 짓기 — 속담 하나를 골라 오늘의 생활에 맞게 낱말만 바꾸어 새 속담을 짓되, 담긴 교훈은 살리고 어떤 상황에서 쓸 말인지도 함께 적는다',ARRAY['6국04-03 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C20','kor',6,1,'u4',4,'관용 표현을 쓴 의도 읽기 — 관용 표현을 들으면 뜻만이 아니라 말한 사람이 왜 그 표현을 골랐는지 의도까지 읽어야 하며, 「목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게.」는 아쉬운 사람이 먼저 나서는 것이 당연하다고 전하려는 말이다',ARRAY['6국04-03 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C21','kor',6,1,'u4',4,'관용 표현은 마음을 고르는 일 — 「정말 하고 싶었다」 대신 「마음이 굴뚝같았다」를 고르면 그 마음의 크기가 함께 전해지듯, 관용 표현을 고르는 일은 뜻을 고르는 일이 아니라 전하고 싶은 마음을 고르는 일에 가깝다',ARRAY['6국04-03 문법']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C22','kor',6,1,'u4',4,'이야기 속 관용 표현 — 옛이야기 「소금 장수와 나루터」의 발등에 불이 떨어지다(급함) · 급할수록 돌아가라(돌아가는 지혜) · 낯이 뜨겁다(부끄러움)처럼 이야기에서도 관용 표현이 인물의 마음과 이야기가 담은 지혜를 한마디로 전한다',ARRAY['6국04-03 문법']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C23','kor',6,1,'u4',4,'뜻이 비슷한 관용 표현 — 발등에 불이 떨어지다 ↔ 코앞에 닥치다, 낯이 뜨겁다 ↔ 고개를 들지 못하다, 마음이 굴뚝같다 ↔ 목이 빠지게 기다리다처럼 가리키는 마음이 같은 표현을 알아 두면 상황에 더 잘 맞는 것을 고를 수 있다',ARRAY['6국04-03 문법']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C24','kor',6,1,'u4',4,'듣는 사람과 자리 — 표현의 뜻은 하나여도 누구에게 하느냐에 따라 뜻이 뒤집혀, 상을 받은 친구에게 「빈 수레가 요란하다더니」는 깎아내리는 말이 되고 자신을 돌아보며 「내가 빈 수레가 요란했구나」는 돌아보는 말이 되므로, 쓰기 전에 듣는 사람과 지금 이 자리를 함께 본다',ARRAY['6국04-03 문법']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C25','kor',6,1,'u4',4,'할 수 있는 만큼부터 — 관용 표현을 소리 내어 쓰는 일이 부담스러울 수 있으므로 쓰고 싶은 상황을 떠올려 보는 것에서 시작해 떠올리기 → 적어 보기 → 말해 보기 순서로 할 수 있는 만큼 나아가면 되며, 남들 앞에서 말할 자신이 없다고 배우지 못한 것은 아니다',ARRAY['6국04-03 문법']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C26','kor',6,1,'u4',4,'상황 짜고 대사 쓰기 — 쓰고 싶은 표현을 고르고 · 어울리는 상황을 한 줄로 적고 · 누가 누구에게 말하는지 정하고 · 표현의 뜻이 상황과 어긋나지 않는지 마지막으로 살피며, 이 넷째 칸은 건너뛰지 않는다 — 다 지은 뒤 표현을 빼고 읽어 보면 무엇이 달라지는지 보인다',ARRAY['6국04-03 문법']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C27','kor',6,1,'u4',6,'견학 기록문의 뜻 — 견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글로, 정보 전달이 강조되므로 견학한 곳은 어디든 될 수 있지만 그 안에서 새로 안 사실은 참이어야 한다',ARRAY['6국03-03 쓰기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C28','kor',6,1,'u4',6,'여정 · 견문 · 감상 — 여정은 어디를 거쳐 어떻게 다녔는지 다닌 길, 견문은 그곳에서 보고 들은 것 · 새롭게 안 사실, 감상은 그 일을 겪으며 생각하거나 느낀 것이며, 셋이 번갈아 엮여야 견학 기록문이 된다',ARRAY['6국03-03 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C29','kor',6,1,'u4',6,'처음 · 가운데 · 끝 — 처음에는 견학한 까닭 · 함께 간 사람 · 장소(언제 · 누구와 · 어디에 · 왜)를 밝혀 개요를 알리고, 가운데에는 다닌 차례대로 보고 들은 것과 그때 느낀 것을 적고, 끝에는 견학한 내용을 정리하고 깨달은 점을 적는다',ARRAY['6국03-03 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C30','kor',6,1,'u4',6,'안내문도 일기도 아니다 — 감상이 빠지면 사실만 남아 안내문이 되고, 견문이 빠지면 마음만 남아 일기가 되므로, 견학 기록문은 새롭게 안 사실을 중심에 놓되 그것을 알고 마음이 어떻게 움직였는지까지 적는 두 갈래 사이의 글이다',ARRAY['6국03-03 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C31','kor',6,1,'u4',6,'제목과 문단으로 읽기 — 제목만 보고도 어디에 다녀온 글이고 무엇을 새로 알았을지 짐작할 수 있으며, 문단이 처음 · 가운데 · 끝 가운데 어느 자리에 있는지 먼저 보면 문단마다 맡은 몫과 중심 내용이 보인다',ARRAY['6국03-03 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C32','kor',6,1,'u4',8,'견학 기록문을 쓰면 좋은 점 — 보고 들은 것과 그때의 마음이 흐려지지 않고 남으며 · 가 보지 못한 사람에게 그곳을 알릴 수 있고 · 그곳에 가려는 사람에게 도움이 되어, 쓰는 사람에게도 남고 읽는 사람에게도 건너간다',ARRAY['6국03-03 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C33','kor',6,1,'u4',8,'쓸 견학 고르기 — 다녀온 곳을 여러 군데 떠올린 뒤 가장 기억에 남는 곳을 고르고 왜 기억에 남는지 한 줄로 적어 보는데, 기억에 남은 까닭이 곧 이 글의 감상이 되므로 까닭이 떠오르지 않는 곳은 쓰기 어렵다',ARRAY['6국03-03 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C34','kor',6,1,'u4',8,'목적 · 주제 · 읽을 사람 — 왜 쓰는가(목적) · 무엇을 중심에 놓을 것인가(주제) · 누가 읽는가(읽을 사람)를 정하며, 이 가운데 읽을 사람이 글의 모양을 가장 많이 바꾸어 동생이 읽는다면 어려운 낱말은 풀어 쓰고 낯선 것은 한 줄 더 설명한다',ARRAY['6국03-03 쓰기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C35','kor',6,1,'u4',8,'생각그물과 조직표 — 생각그물로 장소 · 함께 간 사람과 까닭 · 여정 · 견문 · 감상의 다섯 갈래를 순서 없이 떠오르는 대로 모은 뒤, 조직표로 처음 · 가운데 · 끝에 나누며, 가운데는 본 것 하나에 느낀 것 하나를 짝지어 가야 사실만 늘어놓은 글이 되지 않는다',ARRAY['6국03-03 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C36','kor',6,1,'u4',8,'관용 표현은 감상 자리에 — 견문은 사실이고 감상은 마음이라 관용 표현이 잘 놓이는 자리는 마음 쪽이며, 사실을 전하는 견문 자리에 얹으면(소화전에 호스를 잇는데 손이 열 개라도 모자란다) 무엇이 사실인지 흐려진다',ARRAY['6국03-03 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C37','kor',6,1,'u4',8,'칸 채우기가 아니다 — 견학 기록문에서 가장 중요한 것은 진솔함이며, 여정 · 견문 · 감상도 관용 표현도 채워야 할 칸이 아니라 담을 그릇이라 가장 크게 마음이 움직인 자리에 하나만 놓아도 되고 담을 것이 없으면 비워 두어도 된다',ARRAY['6국03-03 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C38','kor',6,1,'u4',8,'고쳐 쓰기와 나누기 — 고쳐 쓸 때에는 견학한 까닭이 드러나는가 · 여정 · 견문 · 감상이 전해지는가 · 처음 · 가운데 · 끝의 짜임이 맞는가 · 관용 표현이 상황에 맞게 놓였는가를 살피고(글씨 모양이나 길이는 아님), 나눌 때에는 내가 정한 읽을 사람이 실제로 읽을 수 있는 방법을 고른다',ARRAY['6국03-03 쓰기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C39','kor',6,1,'u4',11,'묶어서 만드는 관용 표현 사전 — 공통으로 들어가는 낱말(동물 — 원숭이도 나무에서 떨어진다 · 서당 개 삼 년이면 풍월을 읊는다 · 고양이 목에 방울 달기 / 몸 — 어깨너머로 배우다 · 목에 힘을 주다 · 등을 떠밀다)이나 같은 마음(놀람 · 부끄러움 · 간절함 · 바쁨)으로 묶으며, 낱말로 묶으면 찾기가 쉽고 마음으로 묶으면 쓰기가 쉽다',ARRAY['6국04-03 문법']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C40','kor',6,1,'u4',11,'사전 한 장의 세 칸 — 사전 한 장에는 관용 표현(굳어진 모양 그대로) · 뜻(사전에서 확인한 뜻을 내 말로 줄여서) · 쓸 수 있는 상황(내가 겪은 일이나 겪을 법한 일)을 담으며, 뜻만 적힌 사전은 한 번 보고 덮게 되지만 내 상황이 적힌 사전은 필요할 때 떠오른다',ARRAY['6국04-03 문법']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C41','kor',6,1,'u4',11,'표현을 고르는 기준 — 아무도 모르는 어려운 표현을 많이 채우는 것이 아니라, 개수도 어려움도 아닌 「내가 쓸 자리가 떠오르는가」로 고르며, 쓸 상황이 떠오르지 않는 표현은 다음으로 미뤄도 된다',ARRAY['6국04-03 문법']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C42','kor',6,1,'u4',11,'상황에 따른 언어 예절 — 쉬는 시간 친구와의 비공식적인 말하기에서는 둘레에 방해가 되지 않게 작은 소리로 · 말차례를 지키며 · 반응을 보이며 듣고, 학급 전체 앞 발표 같은 공식적인 말하기에서는 존댓말로 · 모두 들을 수 있는 크기로 · 바른 자세로 듣는 사람을 보며 · 끝까지 경청하며, 예절을 정하는 기준은 외운 목록이 아니라 「듣는 사람이 편하게 들을 수 있는가」라서 목소리 크기 · 표정 · 자세까지 함께 살핀다 (기초 다지기)',ARRAY['기초 다지기(언어 예절)']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X01','kor',6,'u4',ARRAY['K6-1-u4-C1','K6-1-u4-C2']::text[],'관용 표현을 낱말 하나하나의 뜻을 그대로 더한 말로 여겨 글자 그대로 풀어 읽는다','낱말 뜻의 합과 다른 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X02','kor',6,'u4',ARRAY['K6-1-u4-C2']::text[],'낱말 뜻 그대로 통하는 말(가방을 열다 · 창문을 닦다)도 관용 표현으로 고른다','뜻이 엉뚱하게 달라지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X03','kor',6,'u4',ARRAY['K6-1-u4-C12','K6-1-u4-C39']::text[],'입 · 어깨 · 동물 이름 같은 낱말이 들어 있기만 하면 뜻이 낱말 그대로여도 관용 표현이라고 여긴다','낱말과 뜻을 함께 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X04','kor',6,'u4',ARRAY['K6-1-u4-C3']::text[],'관용어와 속담을 헷갈리거나, 둘을 묶어 관용 표현이라 부른다는 것을 모른다','교훈을 담고 전해 오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X05','kor',6,'u4',ARRAY['K6-1-u4-C1']::text[],'관용 표현을 어려운 한자로 줄인 전문가의 말이나 사전 낱말을 길게 이어 붙인 말로 여긴다','오래 쓰여 굳어진 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X06','kor',6,'u4',ARRAY['K6-1-u4-C5']::text[],'관용 표현의 낱말을 바꾸거나 풀어 늘여 써도 뜻이 그대로라고 여긴다','모양 그대로 익혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X07','kor',6,'u4',ARRAY['K6-1-u4-C6','K6-1-u4-C37']::text[],'관용 표현을 많이 넣을수록 좋은 말이나 글이 된다고 여긴다','개수가 아니라 어울림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X08','kor',6,'u4',ARRAY['K6-1-u4-C7']::text[],'표현의 뜻과 어긋난 상황에 관용 표현을 쓴다(생일 축하에 「진땀을 뺐겠구나」)','뜻을 풀어 넣어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X09','kor',6,'u4',ARRAY['K6-1-u4-C4','K6-1-u4-C21']::text[],'관용 표현을 쓰나 그냥 말하나 전해지는 것이 똑같다고 여겨 좋은 점을 모른다','짧게 · 생생하게 · 문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X10','kor',6,'u4',ARRAY['K6-1-u4-C8','K6-1-u4-C13']::text[],'모르는 관용어를 앞뒤 상황으로 짐작해 보지 않고 곧바로 사전부터 펴거나, 정확히 모르면 아예 넘어간다','짐작 먼저, 사전은 나중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X11','kor',6,'u4',ARRAY['K6-1-u4-C9','K6-1-u4-C40']::text[],'관용 표현의 뜻만 외우고 어떤 상황에서 쓰는 말인지는 붙여 두지 않는다','뜻과 쓸 상황을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X12','kor',6,'u4',ARRAY['K6-1-u4-C10']::text[],'몸이 든 관용어를 실제 몸의 상태로 읽는다(귀가 밝다 = 소리를 잘 듣는다)','몸으로 마음을 나타내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X13','kor',6,'u4',ARRAY['K6-1-u4-C11']::text[],'뉴스나 안내문 같은 매체에서는 관용어를 쓸 수 없거나 하는 일이 달라진다고 여긴다','매체가 달라도 같은 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X14','kor',6,'u4',ARRAY['K6-1-u4-C13','K6-1-u4-C18']::text[],'사전에서 관용 표현이나 속담을 찾을 때 중심이 되는 낱말을 잡지 않고 첫 쪽부터 넘기거나 문장 전체를 찾는다','중심 낱말을 앞세워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X15','kor',6,'u4',ARRAY['K6-1-u4-C14','K6-1-u4-C3']::text[],'그 자리에서 지어낸 말과 예로부터 전해 오며 교훈을 담은 속담을 헷갈린다','예로부터 전해 오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X16','kor',6,'u4',ARRAY['K6-1-u4-C15']::text[],'속담이 그리는 장면을 잘못 풀어 뜻을 거꾸로 알거나 엉뚱하게 안다','장면을 먼저 그려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X17','kor',6,'u4',ARRAY['K6-1-u4-C16']::text[],'속담 속 옛말이나 옛 생활 모습을 낡아서 버릴 말로 여긴다','옛 생활이 남은 흔적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X18','kor',6,'u4',ARRAY['K6-1-u4-C17']::text[],'뜻이 비슷한 속담은 어느 상황에서나 그대로 바꿔 쓸 수 있다고 여긴다','기우는 방향을 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X19','kor',6,'u4',ARRAY['K6-1-u4-C19']::text[],'속담을 바꾸어 지을 때 담긴 교훈까지 바꿔 버리거나 쓸 상황을 적지 않는다','교훈은 살리고 상황도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X20','kor',6,'u4',ARRAY['K6-1-u4-C20']::text[],'관용 표현을 쓴 의도를 꾸짖거나 자랑하려는 것으로 잘못 읽는다','그 말 뒤에 무엇이 붙었나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X21','kor',6,'u4',ARRAY['K6-1-u4-C22','K6-1-u4-C1']::text[],'이야기 속 관용 표현을 실제로 일어난 일(정말 발등에 불이 붙음)로 읽는다','인물의 마음을 나타내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X22','kor',6,'u4',ARRAY['K6-1-u4-C23']::text[],'가리키는 마음이 다른 표현끼리 바꿔 쓸 수 있다고 여긴다','같은 마음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X23','kor',6,'u4',ARRAY['K6-1-u4-C24']::text[],'듣는 사람과 자리를 살피지 않고 관용 표현으로 남을 깎아내리거나 상처를 준다','누구에게 하는 말인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X24','kor',6,'u4',ARRAY['K6-1-u4-C25']::text[],'남들 앞에서 소리 내어 말하지 못하면 관용 표현을 배우지 못한 것이라고 여긴다','떠올리기부터 시작해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X25','kor',6,'u4',ARRAY['K6-1-u4-C26']::text[],'상황을 짤 때 표현의 뜻이 상황과 어긋나지 않는지 살피는 마지막 칸을 건너뛴다','넷째 칸은 꼭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X26','kor',6,'u4',ARRAY['K6-1-u4-C27']::text[],'견학 기록문에서 새로 안 사실을 그럴듯하게 지어내도 된다고 여긴다','새로 안 사실은 참이어야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X27','kor',6,'u4',ARRAY['K6-1-u4-C28']::text[],'여정 · 견문 · 감상을 헷갈린다(새로 안 사실을 감상으로, 느낀 것을 견문으로)','길 · 본 것 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X28','kor',6,'u4',ARRAY['K6-1-u4-C29']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 헷갈린다','개요 · 본 것과 느낌 · 정리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X29','kor',6,'u4',ARRAY['K6-1-u4-C30']::text[],'감상을 빼고 새로 안 사실만 늘어놓아도 견학 기록문이라고 여긴다','사실만 남으면 안내문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X30','kor',6,'u4',ARRAY['K6-1-u4-C30']::text[],'견문을 빼고 「재미있었다 · 신기했다」 같은 느낌만 적어도 견학 기록문이라고 여긴다','마음만 남으면 일기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X31','kor',6,'u4',ARRAY['K6-1-u4-C31']::text[],'문단이 처음 · 가운데 · 끝 가운데 어느 자리에 있는지 보지 않고 중심 내용을 찾거나, 제목에서 짐작할 수 있는 것을 놓친다','자리부터 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X32','kor',6,'u4',ARRAY['K6-1-u4-C32']::text[],'견학 기록문을 쓰면 좋은 점을 글씨 연습이나 외운 낱말 개수 늘리기로 여긴다','남기고 · 전하고 · 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X33','kor',6,'u4',ARRAY['K6-1-u4-C33']::text[],'왜 기억에 남는지 살피지 않고 쓸 견학을 고른다','까닭이 곧 감상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X34','kor',6,'u4',ARRAY['K6-1-u4-C34']::text[],'읽을 사람을 생각하지 않고 누구에게나 같은 낱말 · 같은 설명으로 쓴다','누가 읽나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X35','kor',6,'u4',ARRAY['K6-1-u4-C35']::text[],'가운데에 본 것만 늘어놓고 느낀 것을 짝짓지 않거나, 생각그물 단계에서부터 순서를 맞추느라 재료를 모으지 못한다','본 것 하나에 느낀 것 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X36','kor',6,'u4',ARRAY['K6-1-u4-C36']::text[],'관용 표현을 사실을 전하는 견문 자리에 얹는다','관용 표현은 마음 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X37','kor',6,'u4',ARRAY['K6-1-u4-C37']::text[],'정해진 칸이나 개수를 다 채워야 한다고 여겨 담을 것이 없는 자리에도 억지로 써 넣는다','비워 두어도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X38','kor',6,'u4',ARRAY['K6-1-u4-C38']::text[],'고쳐 쓸 때 글씨 모양이나 글의 길이를 살핀다','갈래가 갖출 것을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X39','kor',6,'u4',ARRAY['K6-1-u4-C38']::text[],'읽을 사람이 실제로 읽을 수 없는 방법으로 글을 나눈다(서랍에 넣어 둠)','정말 읽을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X40','kor',6,'u4',ARRAY['K6-1-u4-C41']::text[],'관용 표현 사전에 아무도 모르는 어려운 표현을 많이 채울수록 좋은 사전이라고 여긴다','내가 쓸 자리가 떠오르나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X41','kor',6,'u4',ARRAY['K6-1-u4-C40']::text[],'사전 한 장에 표현이 만들어진 때나 아는 친구의 수처럼 꺼내 쓰는 데 쓸모없는 것을 담는다','표현 · 뜻 · 쓸 상황') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X42','kor',6,'u4',ARRAY['K6-1-u4-C42']::text[],'공식적인 말하기와 비공식적인 말하기에서 지킬 예절을 같다고 여긴다','자리와 듣는 사람이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X43','kor',6,'u4',ARRAY['K6-1-u4-C42']::text[],'언어 예절을 상황과 상관없이 외울 목록으로 여기거나, 말의 내용만 지키면 목소리 · 표정 · 자세는 상관없다고 여긴다','편하게 들을 수 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X44','kor',6,'u4',ARRAY['K6-1-u4-C39']::text[],'관용 표현을 낱말이나 마음으로 묶지 않고 흩어 두거나, 두 묶는 방법이 무엇에 좋은지 헷갈린다','찾기 쉬움 · 쓰기 쉬움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#1','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C1',1,'mc','auto','「관용 표현」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X05','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C1","difficulty":1,"kind":"mc","stem":"「관용 표현」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말","correct":true},{"t":"사전에 실린 낱말을 뜻 그대로 이어 붙여 길게 늘인 말","mis":"K6-1-u4-X05"},{"t":"어려운 한자를 써서 뜻을 짧게 줄인 전문가의 말","mis":"K6-1-u4-X05"},{"t":"그 자리에서 처음 지어낸 재미있는 말","mis":"K6-1-u4-X15"}],"explanation":["뜻 그대로 이은 말이 아니에요.","전문가의 말도 아니에요.","오래 쓰여 굳어진 새로운 뜻의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#2','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C2',1,'mc','auto','다음 가운데 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":2,"concept":"K6-1-u4-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 관용 표현은 어느 것인가요?","options":[{"t":"눈코 뜰 새 없다","correct":true},{"t":"가방을 열다","mis":"K6-1-u4-X02"},{"t":"창문을 닦다","mis":"K6-1-u4-X02"},{"t":"물을 마시다","mis":"K6-1-u4-X02"}],"explanation":["가방을 연다는 말은 뜻 그대로예요.","창문을 닦는 것도 뜻 그대로예요.","눈코 뜰 새 없다는 「몹시 바쁘다」는 새 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#3','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C3',1,'ox','auto','관용어와 속담을 묶어 관용 표현이라고 해요.',ARRAY['K6-1-u4-X04']::text[],false,'{"seq":3,"concept":"K6-1-u4-C3","difficulty":1,"kind":"ox","stem":"관용어와 속담을 묶어 관용 표현이라고 해요.","answer":"O","reason_options":[{"t":"둘 다 오래 쓰이며 굳어진 말이기 때문에","correct":true},{"t":"속담은 관용 표현에 들지 않기 때문에","mis":"K6-1-u4-X04"}],"mis":"K6-1-u4-X04","explanation":["관용어도 굳어진 말이에요.","속담도 굳어진 말이에요.","둘을 묶어 관용 표현이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#4','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C1',1,'match','auto','관용 표현과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u4-C1","difficulty":1,"kind":"match","stem":"관용 표현과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"입을 모으다","r":"여럿이 같은 말을 하다"},{"l":"어깨가 무겁다","r":"책임이 커서 마음이 무겁다"},{"l":"눈코 뜰 새 없다","r":"몹시 바쁘다"}],"mis":"K6-1-u4-X01","explanation":["정말 입을 모은 것이 아니에요.","어깨에 짐을 올린 것도 아니에요.","낱말 뜻의 합과 다른 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#5','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C4',2,'mc','auto','관용 표현을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X01','K6-1-u4-X05']::text[],false,'{"seq":5,"concept":"K6-1-u4-C4","difficulty":2,"kind":"mc","stem":"관용 표현을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"길게 설명할 말을 짧은 한마디로 전할 수 있다","correct":true},{"t":"표현을 많이 넣을수록 글이 저절로 좋아진다","mis":"K6-1-u4-X07"},{"t":"낱말 뜻 그대로라 누구나 풀이 없이 안다","mis":"K6-1-u4-X01"},{"t":"어려운 말이라 듣는 사람을 놀라게 한다","mis":"K6-1-u4-X05"}],"explanation":["많이 넣는다고 좋아지지 않아요.","낱말 뜻 그대로가 아니에요.","짧은 한마디로 긴 말을 대신해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#6','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C5',2,'mc','auto','「눈코 뜰 새 없다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":6,"concept":"K6-1-u4-C5","difficulty":2,"kind":"mc","stem":"「눈코 뜰 새 없다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「시험 준비로 눈코 뜰 새 없었다.」","correct":true},{"t":"「눈을 뜨고 코도 뜰 새가 없었다.」","mis":"K6-1-u4-X06"},{"t":"「눈과 코를 모두 뜰 새가 없었다.」","mis":"K6-1-u4-X06"},{"t":"「귀코 뜰 새 없었다.」","mis":"K6-1-u4-X06"}],"explanation":["낱말을 풀어 늘이면 뜻이 사라져요.","낱말을 바꿔도 뜻을 잃어요.","굳어진 모양 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#7','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C6',2,'ox','auto','관용 표현을 많이 넣을수록 좋은 글이 돼요.',ARRAY['K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C6","difficulty":2,"kind":"ox","stem":"관용 표현을 많이 넣을수록 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"상황과 어긋난 표현이 섞이면 오히려 뜻이 흐려지기 때문에","correct":true},{"t":"표현이 많으면 그만큼 생생해지기 때문에","mis":"K6-1-u4-X07"}],"mis":"K6-1-u4-X07","explanation":["개수가 먼저가 아니에요.","어긋난 표현은 뜻을 흐려요.","상황에 어울리는 하나가 힘이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#8','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C7',2,'mc','auto','관용 표현을 상황에 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u4-X08']::text[],false,'{"seq":8,"concept":"K6-1-u4-C7","difficulty":2,"kind":"mc","stem":"관용 표현을 상황에 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"「처음 심은 씨앗이 바로 열매를 맺진 않아. 첫술에 배부르랴.」","correct":true},{"t":"생일을 맞은 친구에게 「오늘은 정말 진땀을 뺐겠구나.」","mis":"K6-1-u4-X08"},{"t":"비밀을 다 말해 버린 친구에게 「너는 참 입이 무거워.」","mis":"K6-1-u4-X08"},{"t":"한가한 주말에 「눈코 뜰 새 없이 쉬었다.」","mis":"K6-1-u4-X08"}],"explanation":["생일 축하와 진땀은 어긋나요.","비밀을 말한 친구는 입이 무겁지 않아요.","뜻과 상황이 맞물려야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#9','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C1',2,'mc','auto','다솔이가 말한 「어깨가 무겁겠다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X20']::text[],false,'{"seq":9,"concept":"K6-1-u4-C1","difficulty":2,"kind":"mc","stem":"다솔이가 말한 「어깨가 무겁겠다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"당번을 맡은 책임이 커서 마음이 무겁겠다","correct":true},{"t":"물통을 들어 어깨가 아프겠다","mis":"K6-1-u4-X01"},{"t":"어깨에 짐을 올려 무게가 늘겠다","mis":"K6-1-u4-X01"},{"t":"다들 아라를 믿지 않겠다","mis":"K6-1-u4-X20"}],"explanation":["실제 어깨 이야기가 아니에요.","짐을 올린 것도 아니에요.","믿고 맡긴 만큼 책임이 커요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"텃밭 물주기 당번을 누가 맡을지 정하는데, 다들 나를 하라고 입을 모으더라."},{"who":"다솔","text":"그만큼 믿는다는 뜻이지. 그래도 어깨가 무겁겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#10','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C3',3,'mc','auto','관용어와 속담을 가르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X04','K6-1-u4-X03']::text[],false,'{"seq":10,"concept":"K6-1-u4-C3","difficulty":3,"kind":"mc","stem":"관용어와 속담을 가르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"예로부터 전해 오며 지혜나 교훈을 담고 있는가","correct":true},{"t":"낱말이 두 개 이상 들어 있는가","mis":"K6-1-u4-X04"},{"t":"몸을 가리키는 말이 들어 있는가","mis":"K6-1-u4-X03"},{"t":"글자 수가 많은가","mis":"K6-1-u4-X04"}],"explanation":["관용어도 낱말이 여럿이에요.","몸 낱말은 가르는 기준이 아니에요.","교훈을 담고 전해 오면 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#1','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C2',2,'mc','auto','다음 가운데 관용 표현이 아닌 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 관용 표현이 아닌 것은 어느 것인가요?","options":[{"t":"창문을 닦다","correct":true},{"t":"입이 무겁다","mis":"K6-1-u4-X01"},{"t":"진땀을 빼다","mis":"K6-1-u4-X01"},{"t":"입을 모으다","mis":"K6-1-u4-X01"}],"explanation":["입이 무겁다는 말이 신중하다는 뜻이에요.","진땀을 빼다는 몹시 애를 쓴다는 뜻이에요.","창문을 닦다는 뜻 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#2','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C5',2,'ox','auto','「어깨가 무겁다」를 「두 어깨가 아주 무겁다」로 바꿔 써도 뜻이 같아요.',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":2,"concept":"K6-1-u4-C5","difficulty":2,"kind":"ox","stem":"「어깨가 무겁다」를 「두 어깨가 아주 무겁다」로 바꿔 써도 뜻이 같아요.","answer":"X","reason_options":[{"t":"관용 표현은 통째로 굳은 말이라 낱말을 바꾸거나 늘이면 뜻을 잃기 때문에","correct":true},{"t":"낱말 뜻만 같으면 모양은 바꿔도 되기 때문에","mis":"K6-1-u4-X06"}],"mis":"K6-1-u4-X06","explanation":["낱말을 더하면 모양이 달라져요.","모양이 달라지면 굳은 뜻이 사라져요.","모양 그대로 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#3','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C3',3,'mc','auto','다음 가운데 속담은 어느 것인가요?',ARRAY['K6-1-u4-X04']::text[],false,'{"seq":3,"concept":"K6-1-u4-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 속담은 어느 것인가요?","options":[{"t":"빈 수레가 요란하다","correct":true},{"t":"입이 무겁다","mis":"K6-1-u4-X04"},{"t":"진땀을 빼다","mis":"K6-1-u4-X04"},{"t":"눈코 뜰 새 없다","mis":"K6-1-u4-X04"}],"explanation":["입이 무겁다는 관용어예요.","진땀을 빼다도 관용어예요.","교훈을 담고 전해 오는 말이 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#4','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',3,'error','auto','관용 표현에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":4,"concept":"K6-1-u4-C6","difficulty":3,"kind":"error","stem":"관용 표현에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"누리 — 「관용 표현은 많이 넣을수록 글이 좋아져.」","correct":true,"mis_target":"K6-1-u4-X07"},{"t":"다온 — 「상황에 어울리는 하나를 놓는 게 중요해.」","mis":"K6-1-u4-X07"},{"t":"시우 — 「굳어진 모양 그대로 써야 뜻이 살아.」","mis":"K6-1-u4-X06"}],"explanation":["다온이는 바르게 말했어요.","시우도 바르게 말했어요.","개수보다 어울림이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#5','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C4',3,'mc','auto','「책임이 커서 마음이 무겁다」 대신 「어깨가 무겁다」라고 말하면 좋아지는 점은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X09','K6-1-u4-X05']::text[],false,'{"seq":5,"concept":"K6-1-u4-C4","difficulty":3,"kind":"mc","stem":"「책임이 커서 마음이 무겁다」 대신 「어깨가 무겁다」라고 말하면 좋아지는 점은 어느 것인가요?","options":[{"t":"짧은 한마디로 전하면서 듣는 사람이 장면을 떠올리게 된다","correct":true},{"t":"뜻이 사전과 달라져 더 정확해진다","mis":"K6-1-u4-X01"},{"t":"말이 길어져 더 공손해진다","mis":"K6-1-u4-X09"},{"t":"어려워 보여 똑똑해 보인다","mis":"K6-1-u4-X05"}],"explanation":["뜻이 달라지는 것이 아니에요.","말은 오히려 짧아져요.","짧고 생생하게 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#6','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C7',3,'mc','auto','「진땀을 빼다」를 알맞게 쓸 수 있는 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C7","difficulty":3,"kind":"mc","stem":"「진땀을 빼다」를 알맞게 쓸 수 있는 상황은 어느 것인가요?","options":[{"t":"준비가 부족한 채로 발표를 겨우 마쳤을 때","correct":true},{"t":"친구의 생일을 축하할 때","mis":"K6-1-u4-X08"},{"t":"더운 날 운동장에서 땀을 흘렸을 때","mis":"K6-1-u4-X01"},{"t":"비밀을 잘 지키는 친구를 칭찬할 때","mis":"K6-1-u4-X08"}],"explanation":["축하하는 자리와 어긋나요.","실제로 땀을 흘린 이야기가 아니에요.","몹시 애쓴 상황에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#7','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C1',3,'mc','auto','「입을 모으다」의 뜻이 바르게 살아난 문장은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08']::text[],false,'{"seq":7,"concept":"K6-1-u4-C1","difficulty":3,"kind":"mc","stem":"「입을 모으다」의 뜻이 바르게 살아난 문장은 어느 것인가요?","options":[{"t":"「반 친구들이 입을 모아 다솔이를 칭찬했다.」","correct":true},{"t":"「사진을 찍으려고 입술을 동그랗게 입을 모았다.」","mis":"K6-1-u4-X01"},{"t":"「혼자서 입을 모아 말했다.」","mis":"K6-1-u4-X08"},{"t":"「입을 모으면 입이 작아진다.」","mis":"K6-1-u4-X01"}],"explanation":["입술을 오므린 이야기가 아니에요.","혼자서는 입을 모을 수 없어요.","여럿이 같은 말을 한다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#8','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',4,'mc','auto','아라가 쓴 텃밭 일기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":8,"concept":"K6-1-u4-C6","difficulty":4,"kind":"mc","stem":"아라가 쓴 텃밭 일기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"어울리지 않는 표현은 덜어 내고, 마음이 가장 크게 움직인 자리에 꼭 맞는 하나만 남긴다","correct":true},{"t":"관용 표현을 하나 더 넣어 더 생생하게 만든다","mis":"K6-1-u4-X07"},{"t":"관용 표현을 모두 낱말 뜻대로 풀어 늘인다","mis":"K6-1-u4-X06"},{"t":"표현이 많아 좋은 글이니 그대로 둔다","mis":"K6-1-u4-X07"}],"explanation":["더 넣으면 더 흐려져요.","풀어 늘이면 뜻을 잃어요.","제자리에 하나면 충분해요."],"asset":{"type":"passage","lines":["오늘 텃밭에 물을 주었다. 다들 나를 당번으로 하자고 입을 모았다.","물뿌리개를 드니 눈코 뜰 새 없이 무거웠다.","진땀을 빼며 어깨가 무겁게 물을 주고, 입이 무겁게 집에 왔다."],"title":"아라가 쓴 텃밭 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#9','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C1',4,'essay','teacher','「입을 모으다」와 「가방을 열다」를 견주어, 무엇이 관용 표현이고 왜 그런지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C1","difficulty":4,"kind":"essay","stem":"「입을 모으다」와 「가방을 열다」를 견주어, 무엇이 관용 표현이고 왜 그런지 설명하세요.","answer_guide":{"answer":"예: 「입을 모으다」는 관용 표현이다. 실제로 입을 모은 것이 아니라 여럿이 같은 말을 한다는 새로운 뜻이 있기 때문이다. 「가방을 열다」는 가방을 연다는 낱말 뜻 그대로라서 관용 표현이 아니다.","scoring_points":["「입을 모으다」를 관용 표현으로 골랐는가","낱말 뜻의 합과 다른 새로운 뜻이라는 까닭을 썼는가","「가방을 열다」가 뜻 그대로라는 점을 견주어 썼는가"]},"explanation":["두 말을 뜻 그대로 읽어 봐요.","뜻이 달라지는 쪽을 찾아요.","까닭을 견주어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#10','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',4,'essay','teacher','「관용 표현을 쓰는 것이 언제나 효과적인 것은 아니다」라는 말을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C6","difficulty":4,"kind":"essay","stem":"「관용 표현을 쓰는 것이 언제나 효과적인 것은 아니다」라는 말을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 관용 표현은 상황에 맞을 때만 힘이 생긴다. 생일을 맞은 친구에게 「진땀을 뺐겠구나」라고 하면 뜻이 어긋나 어색해진다. 또 한 글에 관용 표현을 여러 개 넣으면 오히려 뜻이 흐려진다. 그래서 개수보다 지금 상황에 어울리는 표현인지를 먼저 살펴야 한다.","scoring_points":["상황에 맞을 때만 효과가 있다는 점을 썼는가","어긋나게 쓴 예를 들었는가","개수보다 어울림이 먼저라는 점을 썼는가"]},"explanation":["어긋난 예를 떠올려요.","많이 넣었을 때를 떠올려요.","먼저 볼 것을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#1','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C8',1,'mc','auto','대화 속 관용어의 뜻을 처음 알아볼 때 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u4-X10','K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C8","difficulty":1,"kind":"mc","stem":"대화 속 관용어의 뜻을 처음 알아볼 때 먼저 할 일은 어느 것인가요?","options":[{"t":"앞뒤 상황을 보고 뜻을 짐작해 본다","correct":true},{"t":"짐작하지 말고 사전부터 편다","mis":"K6-1-u4-X10"},{"t":"뜻을 모르면 그냥 넘어간다","mis":"K6-1-u4-X10"},{"t":"낱말 뜻을 그대로 더해 읽는다","mis":"K6-1-u4-X01"}],"explanation":["사전은 짐작한 뒤에 펴요.","모르면 짐작부터 해 봐요.","앞뒤 상황이 실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#2','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',1,'mc','auto','「걱정 붙들어 매다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":2,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「걱정 붙들어 매다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"걱정하지 말라고 안심시키다","correct":true},{"t":"걱정거리를 끈으로 꽁꽁 묶어 두다","mis":"K6-1-u4-X01"},{"t":"걱정을 오래 붙잡고 놓지 않다","mis":"K6-1-u4-X01"},{"t":"걱정거리를 남에게 넘기다","mis":"K6-1-u4-X01"}],"explanation":["끈으로 묶는 이야기가 아니에요.","걱정을 붙잡는 것도 아니에요.","안심하라는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#3','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C12',1,'mc','auto','다음 가운데 「입」이 들어간 관용어는 어느 것인가요?',ARRAY['K6-1-u4-X03']::text[],false,'{"seq":3,"concept":"K6-1-u4-C12","difficulty":1,"kind":"mc","stem":"다음 가운데 「입」이 들어간 관용어는 어느 것인가요?","options":[{"t":"입이 무겁다","correct":true},{"t":"입을 헹구다","mis":"K6-1-u4-X03"},{"t":"입을 벌려 하품하다","mis":"K6-1-u4-X03"},{"t":"입에 밥을 넣다","mis":"K6-1-u4-X03"}],"explanation":["입을 헹구는 것은 뜻 그대로예요.","하품도 뜻 그대로예요.","말이 신중하다는 새 뜻이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#4','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',1,'ox','auto','관용어는 뜻만 외우면 충분해요.',ARRAY['K6-1-u4-X11']::text[],false,'{"seq":4,"concept":"K6-1-u4-C9","difficulty":1,"kind":"ox","stem":"관용어는 뜻만 외우면 충분해요.","answer":"X","reason_options":[{"t":"어떤 상황에서 쓰는 말인지까지 붙여 두어야 내 말이 되기 때문에","correct":true},{"t":"뜻을 알면 쓸 상황은 저절로 떠오르기 때문에","mis":"K6-1-u4-X11"}],"mis":"K6-1-u4-X11","explanation":["뜻만 외우면 금방 잊어요.","쓸 상황을 함께 붙여요.","그래야 내 말이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#5','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C10',2,'mc','auto','다솔이가 예솔이를 두고 「귀가 밝다」고 한 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01']::text[],false,'{"seq":5,"concept":"K6-1-u4-C10","difficulty":2,"kind":"mc","stem":"다솔이가 예솔이를 두고 「귀가 밝다」고 한 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"소식이나 정보를 남보다 빨리 알아챈다","correct":true},{"t":"작은 소리도 잘 듣는 귀를 가졌다","mis":"K6-1-u4-X12"},{"t":"귀가 하얗고 깨끗하다","mis":"K6-1-u4-X12"},{"t":"들은 말을 함부로 옮긴다","mis":"K6-1-u4-X01"}],"explanation":["뒤에 이어진 말을 봐요.","귀의 생김새 이야기가 아니에요.","누가 무엇을 어디에 뒀는지 다 안다고 했어요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"체육관 열쇠를 분명히 가방에 넣었는데 없어. 점심시간이 다 가는데 어쩌지."},{"who":"다솔","text":"예솔이한테 물어보자. 그 애는 귀가 밝아서, 누가 뭘 어디에 뒀다는 말은 다 듣고 있거든."},{"who":"예솔","text":"아침에 선생님이 교무실 서랍에 넣어 두셨다고 하셨어. 걱정 붙들어 매."},{"who":"아라","text":"휴, 이제야 마음이 놓인다. 아침 내내 진땀을 뺐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#6','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',2,'match','auto','상황에 어울리는 관용어를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u4-C9","difficulty":2,"kind":"match","stem":"상황에 어울리는 관용어를 알맞게 이으세요.","pairs":[{"l":"불안해하는 동생을 안심시킬 때","r":"걱정 붙들어 매"},{"l":"학급 대표를 맡아 부담이 클 때","r":"어깨가 무겁다"},{"l":"할 일이 몰려 쉴 틈이 없을 때","r":"눈코 뜰 새 없다"}],"mis":"K6-1-u4-X08","explanation":["안심시키는 말을 찾아요.","책임이 큰 마음을 찾아요.","몹시 바쁜 마음을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#7','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C11',2,'mc','auto','학교 방송 뉴스의 「눈코 뜰 새 없이」가 전하려는 것은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X12','K6-1-u4-X13']::text[],false,'{"seq":7,"concept":"K6-1-u4-C11","difficulty":2,"kind":"mc","stem":"학교 방송 뉴스의 「눈코 뜰 새 없이」가 전하려는 것은 어느 것인가요?","options":[{"t":"준비할 일이 많아 쉴 틈 없이 바쁘게 움직인다","correct":true},{"t":"준비가 끝나 여유롭게 기다리고 있다","mis":"K6-1-u4-X08"},{"t":"눈과 코가 아픈 학생이 많다","mis":"K6-1-u4-X12"},{"t":"방송에서는 관용어를 쓰면 안 된다","mis":"K6-1-u4-X13"}],"explanation":["여유로운 것과 반대예요.","눈과 코의 이야기가 아니에요.","얼마나 바쁜지를 한마디로 전했어요."],"asset":{"type":"passage","lines":["학교 방송 뉴스 — 「체육 대회 준비로 우리 학년 전체가","눈코 뜰 새 없이 움직이고 있습니다. 지금까지 방송실에서 전해 드렸습니다.」","학급 알림장 — 「도서 반납일이 지난 책이 많습니다.","반납만 하면 되니 걱정 붙들어 매고 내일까지 가져오세요.」"],"title":"매체 속 관용어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#8','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C11',2,'ox','auto','학급 알림장처럼 글로 전하는 매체에는 관용어를 쓸 수 없어요.',ARRAY['K6-1-u4-X13']::text[],false,'{"seq":8,"concept":"K6-1-u4-C11","difficulty":2,"kind":"ox","stem":"학급 알림장처럼 글로 전하는 매체에는 관용어를 쓸 수 없어요.","answer":"X","reason_options":[{"t":"매체가 달라도 관용어는 뜻을 짧고 또렷하게 만드는 같은 일을 하기 때문에","correct":true},{"t":"관용어는 말로 할 때만 쓰는 표현이기 때문에","mis":"K6-1-u4-X13"}],"mis":"K6-1-u4-X13","explanation":["알림장에도 관용어가 놓였어요.","말로도 글로도 써요.","하는 일은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#9','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C13',2,'mc','auto','「귀가 밝다」의 뜻을 국어사전에서 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":9,"concept":"K6-1-u4-C13","difficulty":2,"kind":"mc","stem":"「귀가 밝다」의 뜻을 국어사전에서 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"중심이 되는 낱말 「귀」를 찾아 뜻풀이 아래쪽에 딸린 관용구를 본다","correct":true},{"t":"「귀가 밝다」 문장 전체를 한 번에 찾는다","mis":"K6-1-u4-X14"},{"t":"사전의 첫 쪽부터 차례로 넘겨 본다","mis":"K6-1-u4-X14"},{"t":"아무 낱말이나 먼저 눈에 띄는 것을 찾는다","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로는 찾기 어려워요.","첫 쪽부터 넘기면 오래 걸려요.","중심 낱말을 앞세워 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#10','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C10',3,'mc','auto','몸을 가리키는 말이 든 관용어가 나타내는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12']::text[],false,'{"seq":10,"concept":"K6-1-u4-C10","difficulty":3,"kind":"mc","stem":"몸을 가리키는 말이 든 관용어가 나타내는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"눈에 보이는 몸으로 눈에 보이지 않는 마음이나 태도를 나타낸다","correct":true},{"t":"몸이 아프거나 다친 상태를 알려 준다","mis":"K6-1-u4-X12"},{"t":"몸의 생김새를 자세히 그려 준다","mis":"K6-1-u4-X12"},{"t":"몸을 움직이는 운동 방법을 알려 준다","mis":"K6-1-u4-X12"}],"explanation":["몸 상태 이야기가 아니에요.","생김새도 아니에요.","마음과 태도를 몸으로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#1','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C12',2,'mc','auto','다음 가운데 「어깨」가 들어간 관용어가 아닌 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C12","difficulty":2,"kind":"mc","stem":"다음 가운데 「어깨」가 들어간 관용어가 아닌 것은 어느 것인가요?","options":[{"t":"어깨를 주무르다","correct":true},{"t":"어깨가 무겁다","mis":"K6-1-u4-X01"},{"t":"어깨를 나란히 하다","mis":"K6-1-u4-X01"},{"t":"어깨가 처지다","mis":"K6-1-u4-X01"}],"explanation":["어깨가 무겁다는 책임이 크다는 뜻이에요.","어깨를 나란히 하다는 비슷한 힘을 지닌다는 뜻이에요.","어깨를 주무르는 것은 뜻 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#2','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',2,'ox','auto','관용어의 뜻을 정확히 모르면 짐작하지 말고 넘어가야 해요.',ARRAY['K6-1-u4-X10']::text[],false,'{"seq":2,"concept":"K6-1-u4-C8","difficulty":2,"kind":"ox","stem":"관용어의 뜻을 정확히 모르면 짐작하지 말고 넘어가야 해요.","answer":"X","reason_options":[{"t":"앞뒤 상황을 보고 짐작한 뒤 사전에서 확인하면 뜻이 오래 남기 때문에","correct":true},{"t":"틀리게 짐작하면 안 되기 때문에","mis":"K6-1-u4-X10"}],"mis":"K6-1-u4-X10","explanation":["정확히 몰라도 괜찮아요.","짐작부터 시작해요.","짐작한 뒤 사전으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#3','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',3,'mc','auto','예솔이가 말한 「걱정 붙들어 매」의 뜻을 짐작하는 실마리로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X10']::text[],false,'{"seq":3,"concept":"K6-1-u4-C8","difficulty":3,"kind":"mc","stem":"예솔이가 말한 「걱정 붙들어 매」의 뜻을 짐작하는 실마리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"예솔이가 열쇠가 있는 곳을 알려 준 다음에 이 말을 했다는 점","correct":true},{"t":"「붙들어 매다」를 낱말 뜻 그대로 풀어 본 것","mis":"K6-1-u4-X01"},{"t":"대화에 나온 사람이 몇 명인지","mis":"K6-1-u4-X10"},{"t":"사전을 펴 보기 전에는 실마리가 없다는 점","mis":"K6-1-u4-X10"}],"explanation":["낱말 뜻대로는 풀리지 않아요.","사람 수는 실마리가 아니에요.","앞뒤 상황이 실마리예요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"체육관 열쇠를 분명히 가방에 넣었는데 없어. 점심시간이 다 가는데 어쩌지."},{"who":"다솔","text":"예솔이한테 물어보자. 그 애는 귀가 밝아서, 누가 뭘 어디에 뒀다는 말은 다 듣고 있거든."},{"who":"예솔","text":"아침에 선생님이 교무실 서랍에 넣어 두셨다고 하셨어. 걱정 붙들어 매."},{"who":"아라","text":"휴, 이제야 마음이 놓인다. 아침 내내 진땀을 뺐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#4','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C13',3,'error','auto','모르는 관용어를 찾는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X10','K6-1-u4-X14']::text[],false,'{"seq":4,"concept":"K6-1-u4-C13","difficulty":3,"kind":"error","stem":"모르는 관용어를 찾는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태오 — 「모르는 관용어가 나오면 짐작하지 말고 사전부터 펴야 해.」","correct":true,"mis_target":"K6-1-u4-X10"},{"t":"소윤 — 「중심 낱말을 찾고 뜻풀이 아래쪽 관용구를 봐.」","mis":"K6-1-u4-X14"},{"t":"이안 — 「짐작한 뜻과 사전의 뜻을 맞춰 봐.」","mis":"K6-1-u4-X10"}],"explanation":["소윤이는 찾는 방법을 바르게 말했어요.","이안이도 바르게 말했어요.","사전을 먼저 펴지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#5','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C9',3,'mc','auto','「걱정 붙들어 매다」를 쓰기에 가장 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":5,"concept":"K6-1-u4-C9","difficulty":3,"kind":"mc","stem":"「걱정 붙들어 매다」를 쓰기에 가장 알맞은 상황은 어느 것인가요?","options":[{"t":"잃어버린 줄 알았던 공책을 찾았다고 불안해하는 짝에게 알려 줄 때","correct":true},{"t":"짝이 크게 다쳐 함께 걱정할 때","mis":"K6-1-u4-X08"},{"t":"이삿짐을 끈으로 묶을 때","mis":"K6-1-u4-X01"},{"t":"짝이 시험을 잘 봐 축하할 때","mis":"K6-1-u4-X08"}],"explanation":["함께 걱정하는 자리와 어긋나요.","끈으로 묶는 이야기가 아니에요.","안심시키는 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#6','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C11',3,'mc','auto','학급 알림장에서 「걱정 붙들어 매고」를 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X20','K6-1-u4-X07']::text[],false,'{"seq":6,"concept":"K6-1-u4-C11","difficulty":3,"kind":"mc","stem":"학급 알림장에서 「걱정 붙들어 매고」를 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"반납만 하면 되니 부담 갖지 말라고 안심시키려고","correct":true},{"t":"책을 끈으로 묶어 가져오라고","mis":"K6-1-u4-X01"},{"t":"반납하지 않은 학생을 꾸짖으려고","mis":"K6-1-u4-X20"},{"t":"알림장에는 관용어를 꼭 넣어야 해서","mis":"K6-1-u4-X07"}],"explanation":["끈 이야기가 아니에요.","꾸짖는 말이 아니에요.","안심하고 가져오라는 뜻이에요."],"asset":{"type":"passage","lines":["학교 방송 뉴스 — 「체육 대회 준비로 우리 학년 전체가","눈코 뜰 새 없이 움직이고 있습니다. 지금까지 방송실에서 전해 드렸습니다.」","학급 알림장 — 「도서 반납일이 지난 책이 많습니다.","반납만 하면 되니 걱정 붙들어 매고 내일까지 가져오세요.」"],"title":"매체 속 관용어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#7','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C10',3,'match','auto','몸을 가리키는 말이 든 관용어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u4-C10","difficulty":3,"kind":"match","stem":"몸을 가리키는 말이 든 관용어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"입이 무겁다","r":"말이 신중해 함부로 옮기지 않는다"},{"l":"입에 침이 마르다","r":"남을 거듭 칭찬하다"},{"l":"어깨를 나란히 하다","r":"서로 비슷한 힘을 지니다"}],"mis":"K6-1-u4-X12","explanation":["입이 실제로 무거운 것이 아니에요.","침이 정말 마른 것도 아니에요.","몸으로 마음과 태도를 나타냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#8','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C12',4,'mc','auto','「귀」가 든 관용어 묶음을 만들 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X03','K6-1-u4-X01','K6-1-u4-X10']::text[],false,'{"seq":8,"concept":"K6-1-u4-C12","difficulty":4,"kind":"mc","stem":"「귀」가 든 관용어 묶음을 만들 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「귀가 밝다」와 「귀에 익다」는 넣고, 「귀를 씻다」는 뜻이 낱말 그대로라 뺀다","correct":true},{"t":"「귀」가 들었으니 셋 다 넣는다","mis":"K6-1-u4-X03"},{"t":"「귀를 씻다」만 넣고 나머지는 뺀다","mis":"K6-1-u4-X01"},{"t":"뜻을 모르는 것이 있으니 모두 뺀다","mis":"K6-1-u4-X10"}],"explanation":["낱말만 보고 넣지 않아요.","뜻 그대로인 말은 관용어가 아니에요.","낱말과 뜻을 함께 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#9','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',4,'essay','teacher','「짐작 먼저, 사전은 나중」 순서로 관용어를 익히면 좋은 까닭을 쓰고, 「귀가 밝다」로 그 방법을 차례대로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C8","difficulty":4,"kind":"essay","stem":"「짐작 먼저, 사전은 나중」 순서로 관용어를 익히면 좋은 까닭을 쓰고, 「귀가 밝다」로 그 방법을 차례대로 설명하세요.","answer_guide":{"answer":"예: 먼저 짐작해 보고 사전으로 확인하면 내가 생각한 뜻과 견주게 되어 뜻이 오래 남는다. 「귀가 밝다」는 「누가 뭘 어디에 뒀다는 말은 다 듣고 있다」는 뒷말을 보고 소식을 빨리 안다는 뜻으로 짐작한다. 그다음 사전에서 「귀」를 찾아 뜻풀이 아래 관용구를 보고, 짐작한 뜻과 맞춰 본다.","scoring_points":["짐작 먼저 하면 좋은 까닭을 썼는가","앞뒤 상황으로 짐작하는 방법을 썼는가","중심 낱말로 사전에서 확인하는 순서를 썼는가"]},"explanation":["까닭을 먼저 써요.","앞뒤 말을 실마리로 써요.","사전 찾는 순서를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#10','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C9',4,'essay','teacher','「입에 침이 마르다」의 뜻과 쓸 수 있는 상황을 쓰고, 내 경험이 드러나는 문장을 하나 지으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C9","difficulty":4,"kind":"essay","stem":"「입에 침이 마르다」의 뜻과 쓸 수 있는 상황을 쓰고, 내 경험이 드러나는 문장을 하나 지으세요.","answer_guide":{"answer":"예: 「입에 침이 마르다」는 남을 거듭 칭찬한다는 뜻이다. 누군가 한 일이 아주 좋아서 여러 번 칭찬할 때 쓴다. 지은 문장 — 「할머니께서는 내가 담근 김치가 맛있다고 입에 침이 마르게 칭찬하셨다.」","scoring_points":["뜻을 바르게 썼는가","쓸 수 있는 상황을 썼는가","내 경험이 드러나게 알맞은 문장을 지었는가"]},"explanation":["뜻을 먼저 써요.","쓸 상황을 붙여요.","내 경험으로 문장을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#1','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',1,'mc','auto','「속담」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X15','K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C14","difficulty":1,"kind":"mc","stem":"「속담」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"예로부터 전해 오며 지혜나 교훈을 담은 말","correct":true},{"t":"그 자리에서 새로 지어낸 말","mis":"K6-1-u4-X15"},{"t":"낱말 뜻을 그대로 이은 말","mis":"K6-1-u4-X01"},{"t":"요즘 새로 생긴 줄임말","mis":"K6-1-u4-X15"}],"explanation":["지어낸 말이 아니에요.","뜻 그대로 이은 말도 아니에요.","예로부터 전해 오는 교훈의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#2','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',1,'mc','auto','「첫술에 배부르랴」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":2,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「첫술에 배부르랴」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무슨 일이든 한 번에 큰 성과를 얻기는 어렵다","correct":true},{"t":"밥은 첫 숟가락이 가장 맛있다","mis":"K6-1-u4-X16"},{"t":"처음부터 많이 먹어야 배가 부르다","mis":"K6-1-u4-X16"},{"t":"한 번 하면 무슨 일이든 다 끝난다","mis":"K6-1-u4-X16"}],"explanation":["밥맛 이야기가 아니에요.","많이 먹으라는 말도 아니에요.","첫 숟가락으로는 배가 부르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#3','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',1,'mc','auto','대화에서 쓰인 속담은 어느 것인가요?',ARRAY['K6-1-u4-X15']::text[],false,'{"seq":3,"concept":"K6-1-u4-C14","difficulty":1,"kind":"mc","stem":"대화에서 쓰인 속담은 어느 것인가요?","options":[{"t":"빈 수레가 요란하다","correct":true},{"t":"세 골이나 먹었어","mis":"K6-1-u4-X15"},{"t":"오늘부터 하면 되지","mis":"K6-1-u4-X15"},{"t":"골키퍼를 제일 잘한다","mis":"K6-1-u4-X15"}],"explanation":["그 자리에서 한 말이에요.","이것도 그 자리에서 한 말이에요.","예로부터 전해 오는 말을 골라요."],"asset":{"type":"speech","turns":[{"who":"예솔","text":"한별이가 자기가 골키퍼를 제일 잘한다고 계속 말하더라. 그런데 오늘 경기에서는 세 골이나 먹었어."},{"who":"한별","text":"맞아. 빈 수레가 요란하다더니 내 이야기였네. 말 대신 연습을 했어야 했는데."},{"who":"예솔","text":"오늘부터 하면 되지. 첫술에 배부르랴."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#4','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C16',1,'ox','auto','「수레」처럼 요즘 잘 쓰지 않는 말이 든 속담은 낡아서 쓰지 않는 게 좋아요.',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":1,"kind":"ox","stem":"「수레」처럼 요즘 잘 쓰지 않는 말이 든 속담은 낡아서 쓰지 않는 게 좋아요.","answer":"X","reason_options":[{"t":"옛말은 조상의 생활이 말에 남은 흔적이라 우리 문화를 담고 있기 때문에","correct":true},{"t":"요즘 쓰지 않는 낱말이 들어 있으면 틀린 말이기 때문에","mis":"K6-1-u4-X17"}],"mis":"K6-1-u4-X17","explanation":["옛말이 있다고 못 쓰는 말이 되지 않아요.","옛 생활이 말에 남았어요.","무엇을 가리키는지 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#5','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',2,'match','auto','속담과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u4-C15","difficulty":2,"kind":"match","stem":"속담과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"빈 수레가 요란하다","r":"잘 알지 못하는 사람이 오히려 더 떠든다"},{"l":"첫술에 배부르랴","r":"한 번에 큰 성과를 얻기 어렵다"},{"l":"가랑비에 옷 젖는 줄 모른다","r":"사소한 것이 쌓여 큰 것이 되는 줄 모른다"}],"mis":"K6-1-u4-X16","explanation":["빈 수레는 덜컹거려 시끄러워요.","첫 숟가락으로는 배가 안 불러요.","가는 비에도 어느새 젖어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#6','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',2,'mc','auto','한별이가 「빈 수레가 요란하다더니 내 이야기였네.」라고 말한 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C14","difficulty":2,"kind":"mc","stem":"한별이가 「빈 수레가 요란하다더니 내 이야기였네.」라고 말한 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"말만 앞세우고 연습하지 않은 자신을 돌아본다","correct":true},{"t":"경기에서 이긴 것을 자랑한다","mis":"K6-1-u4-X20"},{"t":"예솔이를 꾸짖는다","mis":"K6-1-u4-X20"},{"t":"수레를 끌고 와서 시끄러웠다고 말한다","mis":"K6-1-u4-X01"}],"explanation":["세 골이나 먹었어요.","예솔이를 꾸짖는 말이 아니에요.","자기 이야기라고 했어요."],"asset":{"type":"speech","turns":[{"who":"예솔","text":"한별이가 자기가 골키퍼를 제일 잘한다고 계속 말하더라. 그런데 오늘 경기에서는 세 골이나 먹었어."},{"who":"한별","text":"맞아. 빈 수레가 요란하다더니 내 이야기였네. 말 대신 연습을 했어야 했는데."},{"who":"예솔","text":"오늘부터 하면 되지. 첫술에 배부르랴."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#7','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C17',2,'mc','auto','「첫술에 배부르랴」와 뜻이 겹치는 속담은 어느 것인가요?',ARRAY['K6-1-u4-X18']::text[],false,'{"seq":7,"concept":"K6-1-u4-C17","difficulty":2,"kind":"mc","stem":"「첫술에 배부르랴」와 뜻이 겹치는 속담은 어느 것인가요?","options":[{"t":"급할수록 돌아가라","correct":true},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X18"},{"t":"고양이 목에 방울 달기","mis":"K6-1-u4-X18"},{"t":"바늘 도둑이 소도둑 된다","mis":"K6-1-u4-X18"}],"explanation":["빈 수레는 떠드는 이야기예요.","방울 달기는 해내기 어려운 일이에요.","서두른다고 빨라지지 않는다는 뜻이 겹쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#8','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C18',2,'mc','auto','「빈 수레가 요란하다」를 사전에서 찾을 때 앞세울 중심 낱말은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":8,"concept":"K6-1-u4-C18","difficulty":2,"kind":"mc","stem":"「빈 수레가 요란하다」를 사전에서 찾을 때 앞세울 중심 낱말은 어느 것인가요?","options":[{"t":"수레","correct":true},{"t":"「빈 수레가 요란하다」 문장 전체","mis":"K6-1-u4-X14"},{"t":"사전의 맨 첫 낱말","mis":"K6-1-u4-X14"},{"t":"속담에 들어 있는 「가」","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로 찾지 않아요.","첫 낱말부터 넘기지 않아요.","중심이 되는 낱말을 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#9','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',2,'mc','auto','「가랑비에 옷 젖는 줄 모른다」가 그리는 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":9,"concept":"K6-1-u4-C15","difficulty":2,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」가 그리는 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"가늘게 내리는 비라 젖는 줄 모르다가 어느새 다 젖는다","correct":true},{"t":"굵은 비가 한꺼번에 쏟아져 금방 젖는다","mis":"K6-1-u4-X16"},{"t":"비가 와도 옷이 전혀 젖지 않는다","mis":"K6-1-u4-X16"},{"t":"비가 그친 뒤 옷이 빨리 마른다","mis":"K6-1-u4-X16"}],"explanation":["굵은 비가 아니에요.","젖지 않는 것도 아니에요.","조금씩 쌓여 다 젖어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#10','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C17',3,'mc','auto','「가랑비에 옷 젖는 줄 모른다」와 「바늘 도둑이 소도둑 된다」를 견준 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X16','K6-1-u4-X15']::text[],false,'{"seq":10,"concept":"K6-1-u4-C17","difficulty":3,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」와 「바늘 도둑이 소도둑 된다」를 견준 말로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 작은 것이 쌓여 커진다는 뜻이지만 뒤의 것은 나쁜 일이 커지는 쪽으로 기운다","correct":true},{"t":"뜻이 똑같아 어느 상황에서나 바꿔 써도 된다","mis":"K6-1-u4-X18"},{"t":"두 속담은 뜻이 서로 반대이다","mis":"K6-1-u4-X16"},{"t":"앞의 것만 속담이고 뒤의 것은 관용어이다","mis":"K6-1-u4-X15"}],"explanation":["기우는 방향이 달라요.","뜻이 반대는 아니에요.","둘 다 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#1','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C14',2,'mc','auto','속담이 간결하면서도 효과적인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X05','K6-1-u4-X09','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C14","difficulty":2,"kind":"mc","stem":"속담이 간결하면서도 효과적인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면 하나로 말해 오래 남고, 여러 사람이 알아 풀어 설명하지 않아도 통한다","correct":true},{"t":"어려운 낱말이 많아 귀하게 들린다","mis":"K6-1-u4-X05"},{"t":"길게 풀어 설명해 자세하다","mis":"K6-1-u4-X09"},{"t":"그 자리에서 지어내 새롭다","mis":"K6-1-u4-X15"}],"explanation":["어려워서 힘이 센 것이 아니에요.","길게 풀지 않아요.","장면과 교훈으로 짧게 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#2','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C18',2,'ox','auto','속담 사전 · 국어사전 · 인터넷 사전은 모두 중심 낱말을 앞세워 속담을 찾아요.',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":2,"concept":"K6-1-u4-C18","difficulty":2,"kind":"ox","stem":"속담 사전 · 국어사전 · 인터넷 사전은 모두 중심 낱말을 앞세워 속담을 찾아요.","answer":"O","reason_options":[{"t":"사전은 낱말을 기준으로 짜여 있기 때문에","correct":true},{"t":"속담 문장 전체를 넣어야만 찾을 수 있기 때문에","mis":"K6-1-u4-X14"}],"mis":"K6-1-u4-X14","explanation":["셋은 생김새가 달라요.","그래도 찾는 길은 같아요.","중심 낱말을 앞세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#3','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C15',3,'mc','auto','다음 상황에 알맞은 속담은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X18']::text[],false,'{"seq":3,"concept":"K6-1-u4-C15","difficulty":3,"kind":"mc","stem":"다음 상황에 알맞은 속담은 어느 것인가요?","options":[{"t":"가랑비에 옷 젖는 줄 모른다","correct":true},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X08"},{"t":"첫술에 배부르랴","mis":"K6-1-u4-X18"},{"t":"고양이 목에 방울 달기","mis":"K6-1-u4-X08"}],"explanation":["떠드는 이야기가 아니에요.","한 번에 안 된다는 뜻과는 달라요.","작은 것이 쌓여 커졌어요."],"asset":{"type":"passage","lines":["날마다 십 분씩만 책을 읽었다. 대단한 일이라고 생각하지 않았는데,","한 학기가 지나고 보니 읽은 책이 스무 권이 넘어 있었다."],"title":"어느 학생의 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#4','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C16',3,'error','auto','속담 속 옛말을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":3,"kind":"error","stem":"속담 속 옛말을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"로하 — 「서당은 요즘 없으니 이 속담은 버려야 해.」","correct":true,"mis_target":"K6-1-u4-X17"},{"t":"지안 — 「서당이 무엇인지 찾아보면 옛 생활을 알 수 있어.」","mis":"K6-1-u4-X17"},{"t":"하윤 — 「풍월이 무슨 말인지 사전에서 찾아볼래.」","mis":"K6-1-u4-X17"}],"explanation":["지안이는 옛 생활을 알아보려 했어요.","하윤이는 낯선 말을 찾아보려 했어요.","옛말은 버릴 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#5','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C17',3,'mc','auto','뜻이 비슷한 속담을 바꿔 쓸 수 있는지 정할 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X03']::text[],false,'{"seq":5,"concept":"K6-1-u4-C17","difficulty":3,"kind":"mc","stem":"뜻이 비슷한 속담을 바꿔 쓸 수 있는지 정할 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"뜻만이 아니라 어떤 상황에 쓰는 말인지, 기우는 방향까지 견준다","correct":true},{"t":"두 속담의 글자 수가 같은지 본다","mis":"K6-1-u4-X18"},{"t":"같은 낱말이 들었는지만 본다","mis":"K6-1-u4-X03"},{"t":"뜻이 조금이라도 겹치면 바꿔 쓴다","mis":"K6-1-u4-X18"}],"explanation":["글자 수와는 상관없어요.","같은 낱말은 기준이 아니에요.","쓸 상황까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#6','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C19',3,'mc','auto','「빈 수레가 요란하다」를 오늘 생활에 맞게 바꿔 지은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X19','K6-1-u4-X06']::text[],false,'{"seq":6,"concept":"K6-1-u4-C19","difficulty":3,"kind":"mc","stem":"「빈 수레가 요란하다」를 오늘 생활에 맞게 바꿔 지은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「빈 필통이 요란하다」","correct":true},{"t":"「꽉 찬 필통이 요란하다」","mis":"K6-1-u4-X19"},{"t":"「빈 필통이 조용하다」","mis":"K6-1-u4-X19"},{"t":"「빈 수레가 요란하고 시끄럽다」","mis":"K6-1-u4-X06"}],"explanation":["꽉 차면 교훈이 달라져요.","조용하면 뜻이 반대가 돼요.","낱말만 바꾸고 교훈은 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#7','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C18',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」에서 「풍월」의 뜻을 모를 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X10','K6-1-u4-X17']::text[],false,'{"seq":7,"concept":"K6-1-u4-C18","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」에서 「풍월」의 뜻을 모를 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"장면과 앞뒤 말로 짐작해 본 뒤 「풍월」을 사전에서 찾아 맞춰 본다","correct":true},{"t":"사전의 첫 쪽부터 넘기며 속담이 나올 때까지 읽는다","mis":"K6-1-u4-X14"},{"t":"짐작한 뜻을 찾아보지 않고 그대로 정답으로 삼는다","mis":"K6-1-u4-X10"},{"t":"모르는 낱말이 있으니 이 속담은 쓰지 않는다","mis":"K6-1-u4-X17"}],"explanation":["첫 쪽부터는 오래 걸려요.","짐작은 확인해야 해요.","짐작한 뒤 사전으로 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#8','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C17',4,'mc','auto','「처음에는 친구 지우개를 말없이 빌려 쓰던 것이 버릇이 되어, 나중에는 친구 물건을 허락 없이 가져가는 일이 잦아졌다.」에 가장 알맞은 속담과 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X08','K6-1-u4-X16']::text[],false,'{"seq":8,"concept":"K6-1-u4-C17","difficulty":4,"kind":"mc","stem":"「처음에는 친구 지우개를 말없이 빌려 쓰던 것이 버릇이 되어, 나중에는 친구 물건을 허락 없이 가져가는 일이 잦아졌다.」에 가장 알맞은 속담과 까닭은 어느 것인가요?","options":[{"t":"「바늘 도둑이 소도둑 된다」 — 작은 잘못이 커지는 쪽으로 기우는 말이라 이 상황에 꼭 맞는다","correct":true},{"t":"「가랑비에 옷 젖는 줄 모른다」 — 작은 것이 쌓인다는 뜻이 같으니 더 알맞다","mis":"K6-1-u4-X18"},{"t":"「첫술에 배부르랴」 — 한 번에 되지 않는 일이기 때문이다","mis":"K6-1-u4-X08"},{"t":"「빈 수레가 요란하다」 — 물건을 가져가면 시끄럽기 때문이다","mis":"K6-1-u4-X16"}],"explanation":["뜻이 겹쳐도 기우는 방향이 달라요.","한 번에 안 되는 이야기가 아니에요.","작은 잘못이 커진 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#9','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C16',4,'essay','teacher','속담 속에서 낯선 옛말을 만났을 때 어떻게 대하면 좋을지 쓰고, 속담 하나를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C16","difficulty":4,"kind":"essay","stem":"속담 속에서 낯선 옛말을 만났을 때 어떻게 대하면 좋을지 쓰고, 속담 하나를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 낯선 옛말은 버릴 말이 아니라 조상의 생활이 남은 흔적이므로 무엇을 가리키는지 찾아보면 좋다. 「빈 수레가 요란하다」의 수레는 옛날 짐을 싣고 다니던 것인데, 짐이 없으면 덜컹거려 더 시끄럽다. 이 장면을 알면 잘 모르는 사람이 더 떠든다는 뜻이 저절로 이해되고 옛 생활도 엿볼 수 있다.","scoring_points":["옛말을 버리지 않고 찾아본다는 태도를 썼는가","옛말이 옛 생활의 흔적이라는 점을 썼는가","속담 하나를 예로 들어 설명했는가"]},"explanation":["옛말을 어떻게 대할지 써요.","옛 생활과 이어 봐요.","예를 하나 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#10','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C19',4,'essay','teacher','속담 하나를 골라 오늘 생활에 맞게 바꾸어 짓고, 담긴 교훈과 쓸 수 있는 상황을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C19","difficulty":4,"kind":"essay","stem":"속담 하나를 골라 오늘 생활에 맞게 바꾸어 짓고, 담긴 교훈과 쓸 수 있는 상황을 쓰세요.","answer_guide":{"answer":"예: 「가랑비에 옷 젖는 줄 모른다」를 「한 장씩 넘긴 책이 책장을 채운다」로 바꾸었다. 작은 것이 쌓여 큰 것이 된다는 교훈은 그대로 살렸다. 날마다 조금씩 읽은 책이 어느새 많이 쌓였을 때 쓸 수 있다.","scoring_points":["속담을 골라 낱말을 바꾸어 지었는가","원래 속담의 교훈을 살렸는가","쓸 수 있는 상황을 썼는가"]},"explanation":["속담을 하나 골라요.","교훈은 그대로 살려요.","쓸 상황을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#1','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C20',1,'mc','auto','대화에서 쓰인 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C20","difficulty":1,"kind":"mc","stem":"대화에서 쓰인 관용 표현은 어느 것인가요?","options":[{"t":"목마른 사람이 우물 판다","correct":true},{"t":"답답한 내가 먼저 가 볼게","mis":"K6-1-u4-X15"},{"t":"쉬는 시간마다 혼자 앉아 있어","mis":"K6-1-u4-X15"},{"t":"누군가 먼저 가서 말을 걸면 좋을 텐데","mis":"K6-1-u4-X15"}],"explanation":["그 자리에서 한 말이에요.","이것도 그 자리에서 한 말이에요.","예로부터 전해 오는 말을 골라요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#2','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C21',1,'mc','auto','「마음이 굴뚝같다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X22']::text[],false,'{"seq":2,"concept":"K6-1-u4-C21","difficulty":1,"kind":"mc","stem":"「마음이 굴뚝같다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 몹시 하고 싶어 하다","correct":true},{"t":"마음이 굴뚝처럼 시커멓다","mis":"K6-1-u4-X01"},{"t":"마음이 답답해 연기가 난다","mis":"K6-1-u4-X01"},{"t":"하기 싫은 마음이 크다","mis":"K6-1-u4-X22"}],"explanation":["굴뚝 색깔 이야기가 아니에요.","연기 이야기도 아니에요.","몹시 하고 싶은 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#3','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C22',1,'mc','auto','「낯이 뜨겁다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X22']::text[],false,'{"seq":3,"concept":"K6-1-u4-C22","difficulty":1,"kind":"mc","stem":"「낯이 뜨겁다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"부끄러워 얼굴이 달아오르다","correct":true},{"t":"얼굴에 열이 나서 아프다","mis":"K6-1-u4-X21"},{"t":"화가 나서 소리를 지르다","mis":"K6-1-u4-X22"},{"t":"날씨가 더워 땀이 나다","mis":"K6-1-u4-X21"}],"explanation":["아파서 열이 나는 것이 아니에요.","화난 마음과는 달라요.","부끄러운 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#4','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C24',1,'ox','auto','같은 관용 표현이라도 누구에게 하느냐에 따라 뜻이 달라질 수 있어요.',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":4,"concept":"K6-1-u4-C24","difficulty":1,"kind":"ox","stem":"같은 관용 표현이라도 누구에게 하느냐에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"같은 표현도 남을 가리키면 상처가 되고 자기를 가리키면 돌아봄이 되기 때문에","correct":true},{"t":"관용 표현은 굳어진 말이라 어디서나 똑같이 전해지기 때문에","mis":"K6-1-u4-X23"}],"mis":"K6-1-u4-X23","explanation":["뜻은 하나여도","듣는 사람이 달라지면","전해지는 것이 뒤집혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#5','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C20',2,'mc','auto','초아가 「목마른 사람이 우물 판다잖아.」를 앞에 놓고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X21']::text[],false,'{"seq":5,"concept":"K6-1-u4-C20","difficulty":2,"kind":"mc","stem":"초아가 「목마른 사람이 우물 판다잖아.」를 앞에 놓고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"답답한 내가 먼저 나서는 것이 당연하다고 전하려고","correct":true},{"t":"나서지 않는 친구들을 꾸짖으려고","mis":"K6-1-u4-X20"},{"t":"속담을 많이 안다는 것을 자랑하려고","mis":"K6-1-u4-X20"},{"t":"우물을 파러 가겠다고 알리려고","mis":"K6-1-u4-X21"}],"explanation":["꾸짖는 말이 아니에요.","자랑하려는 말도 아니에요.","그 말 뒤에 「내가 먼저 가 볼게」를 붙였어요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#6','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C22',2,'mc','auto','「급할수록 돌아가라」가 담은 지혜가 드러난 소금 장수의 행동은 어느 것인가요?',ARRAY['K6-1-u4-X16','K6-1-u4-X20']::text[],false,'{"seq":6,"concept":"K6-1-u4-C22","difficulty":2,"kind":"mc","stem":"「급할수록 돌아가라」가 담은 지혜가 드러난 소금 장수의 행동은 어느 것인가요?","options":[{"t":"강을 따라 반나절을 걸어 얕은 여울목으로 건넜다","correct":true},{"t":"뱃삯을 두 배로 내고 서둘러 배를 탔다","mis":"K6-1-u4-X16"},{"t":"장에 가지 않고 집으로 되돌아갔다","mis":"K6-1-u4-X16"},{"t":"사공과 다투어 뱃삯을 깎았다","mis":"K6-1-u4-X20"}],"explanation":["서두르는 행동이에요.","포기하는 행동이에요.","돌아가는 길로 침착하게 해냈어요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#7','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C23',2,'match','auto','뜻이 비슷해 바꿔 쓸 수 있는 표현끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u4-C23","difficulty":2,"kind":"match","stem":"뜻이 비슷해 바꿔 쓸 수 있는 표현끼리 알맞게 이으세요.","pairs":[{"l":"발등에 불이 떨어지다","r":"코앞에 닥치다"},{"l":"낯이 뜨겁다","r":"고개를 들지 못하다"},{"l":"마음이 굴뚝같다","r":"목이 빠지게 기다리다"}],"mis":"K6-1-u4-X22","explanation":["급한 마음끼리 이어요.","부끄러운 마음끼리 이어요.","간절한 마음끼리 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#8','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C24',2,'mc','auto','관용 표현을 알맞게 쓴 말은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08']::text[],false,'{"seq":8,"concept":"K6-1-u4-C24","difficulty":2,"kind":"mc","stem":"관용 표현을 알맞게 쓴 말은 어느 것인가요?","options":[{"t":"「아직 서툴지만 첫술에 배부르랴. 천천히 해 볼게.」","correct":true},{"t":"상을 받은 친구에게 「개구리 올챙이 적 생각 못 하는구나.」","mis":"K6-1-u4-X23"},{"t":"아파서 결석한 친구에게 「눈코 뜰 새 없이 바빴겠구나.」","mis":"K6-1-u4-X08"},{"t":"발표를 잘한 친구에게 「빈 수레가 요란하다더니.」","mis":"K6-1-u4-X23"}],"explanation":["축하할 자리에서 깎아내려요.","아픈 친구와 바쁨은 어긋나요.","자기를 가리키는 자리라 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#9','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C25',2,'ox','auto','관용 표현을 친구들 앞에서 소리 내어 말하지 못하면 배우지 못한 거예요.',ARRAY['K6-1-u4-X24']::text[],false,'{"seq":9,"concept":"K6-1-u4-C25","difficulty":2,"kind":"ox","stem":"관용 표현을 친구들 앞에서 소리 내어 말하지 못하면 배우지 못한 거예요.","answer":"X","reason_options":[{"t":"쓰고 싶은 상황을 떠올리고 적어 보는 것부터 할 수 있는 만큼 나아가면 되기 때문에","correct":true},{"t":"관용 표현은 말로 해야만 배운 것이기 때문에","mis":"K6-1-u4-X24"}],"mis":"K6-1-u4-X24","explanation":["부담스러울 수 있어요.","떠올리기부터 시작해요.","적어 보기, 말해 보기로 나아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#10','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C26',3,'mc','auto','관용 표현을 쓸 상황을 짤 때 건너뛰지 말아야 할 마지막 칸은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X25']::text[],false,'{"seq":10,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"관용 표현을 쓸 상황을 짤 때 건너뛰지 말아야 할 마지막 칸은 어느 것인가요?","options":[{"t":"표현의 뜻이 상황과 어긋나지 않는지 살피기","correct":true},{"t":"관용 표현을 몇 개 넣었는지 세기","mis":"K6-1-u4-X07"},{"t":"가장 어려운 표현으로 바꾸기","mis":"K6-1-u4-X25"},{"t":"대사를 되도록 길게 늘이기","mis":"K6-1-u4-X25"}],"explanation":["개수를 세는 칸이 아니에요.","어려운 표현이 좋은 것도 아니에요.","뜻과 상황이 맞는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#1','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C21',2,'mc','auto','새롬이가 「정말 하고 싶었다」 대신 「마음이 굴뚝같았는데」라고 말해서 더 전해진 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20','K6-1-u4-X09']::text[],false,'{"seq":1,"concept":"K6-1-u4-C21","difficulty":2,"kind":"mc","stem":"새롬이가 「정말 하고 싶었다」 대신 「마음이 굴뚝같았는데」라고 말해서 더 전해진 것은 어느 것인가요?","options":[{"t":"말을 걸고 싶은 마음이 얼마나 컸는지","correct":true},{"t":"굴뚝이 있는 집에 산다는 것","mis":"K6-1-u4-X21"},{"t":"사실은 말을 걸기 싫었다는 것","mis":"K6-1-u4-X20"},{"t":"그냥 말한 것과 아무 차이가 없다","mis":"K6-1-u4-X09"}],"explanation":["굴뚝 이야기가 아니에요.","싫었다는 것이 아니에요.","마음의 크기가 함께 전해졌어요."],"asset":{"type":"speech","turns":[{"who":"새롬","text":"그때 네가 먼저 와 줘서 고마웠어. 사실 나도 말을 걸고 싶은 마음이 굴뚝같았는데, 첫마디가 안 나오더라."},{"who":"초아","text":"나도 사실은 떨렸어. 그런데 누구 한 사람은 먼저 움직여야 하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#2','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C22',2,'ox','auto','「소금 장수는 발등에 불이 떨어진 심정이었다」는 소금 장수의 발등에 실제로 불이 붙었다는 뜻이에요.',ARRAY['K6-1-u4-X21']::text[],false,'{"seq":2,"concept":"K6-1-u4-C22","difficulty":2,"kind":"ox","stem":"「소금 장수는 발등에 불이 떨어진 심정이었다」는 소금 장수의 발등에 실제로 불이 붙었다는 뜻이에요.","answer":"X","reason_options":[{"t":"장이 오늘뿐이라 몹시 급한 마음을 나타낸 표현이기 때문에","correct":true},{"t":"이야기에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-1-u4-X21"}],"mis":"K6-1-u4-X21","explanation":["「심정」이라고 했어요.","실제 불 이야기가 아니에요.","몹시 급한 마음이에요."],"asset":{"type":"passage","lines":["옛날, 소금을 지고 장을 다니는 장수가 있었다. 강 건너 장에 가려고","나루터에 닿았는데, 사공이 팔짱을 낀 채 말했다.","「오늘은 물이 불었으니 뱃삯을 두 배로 내시오.」","장이 서는 날은 오늘 하루뿐이었다. 소금 장수는 발등에 불이 떨어진","심정이었지만 지게를 내려놓고 생각했다. 「급할수록 돌아가라고 했지.」"],"title":"옛이야기 「소금 장수와 나루터」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#3','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C22',3,'mc','auto','사공이 「낯이 뜨거워 고개를 들지 못했다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20']::text[],false,'{"seq":3,"concept":"K6-1-u4-C22","difficulty":3,"kind":"mc","stem":"사공이 「낯이 뜨거워 고개를 들지 못했다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"욕심을 부려 뱃삯을 올린 일이 부끄럽다","correct":true},{"t":"햇볕에 얼굴이 탔다","mis":"K6-1-u4-X21"},{"t":"소금 장수에게 화가 났다","mis":"K6-1-u4-X20"},{"t":"배를 지키느라 목이 아팠다","mis":"K6-1-u4-X21"}],"explanation":["햇볕 이야기가 아니에요.","화난 마음이 아니에요.","빈 배로 하루를 보낸 뒤의 부끄러움이에요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#4','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C24',3,'error','auto','「빈 수레가 요란하다」를 쓴 친구들이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":4,"concept":"K6-1-u4-C24","difficulty":3,"kind":"error","stem":"「빈 수레가 요란하다」를 쓴 친구들이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"지호 — 노래 대회에서 상을 받은 짝에게 「빈 수레가 요란하다더니.」라고 말했다","correct":true,"mis_target":"K6-1-u4-X23"},{"t":"라희 — 연습을 미룬 자신을 돌아보며 「내가 빈 수레가 요란했구나.」라고 썼다","mis":"K6-1-u4-X23"},{"t":"도하 — 준비 없이 큰소리치던 자신을 떠올리며 일기에 이 속담을 썼다","mis":"K6-1-u4-X23"}],"explanation":["라희는 자신을 돌아봤어요.","도하도 자신을 돌아봤어요.","상 받은 짝에게는 깎아내리는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#5','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C20',3,'mc','auto','소금 장수가 「급할수록 돌아가라고 했지.」라고 혼잣말한 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X16']::text[],false,'{"seq":5,"concept":"K6-1-u4-C20","difficulty":3,"kind":"mc","stem":"소금 장수가 「급할수록 돌아가라고 했지.」라고 혼잣말한 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"서두르기보다 다른 길을 찾아 침착하게 가려고 스스로 마음을 다잡으려고","correct":true},{"t":"사공에게 겁을 주려고","mis":"K6-1-u4-X20"},{"t":"장에 가는 것을 그만두려고","mis":"K6-1-u4-X16"},{"t":"속담을 외운 것을 뽐내려고","mis":"K6-1-u4-X20"}],"explanation":["사공에게 한 말이 아니에요.","그만두지 않았어요.","스스로 마음을 다잡았어요."],"asset":{"type":"passage","lines":["옛날, 소금을 지고 장을 다니는 장수가 있었다. 강 건너 장에 가려고","나루터에 닿았는데, 사공이 팔짱을 낀 채 말했다.","「오늘은 물이 불었으니 뱃삯을 두 배로 내시오.」","장이 서는 날은 오늘 하루뿐이었다. 소금 장수는 발등에 불이 떨어진","심정이었지만 지게를 내려놓고 생각했다. 「급할수록 돌아가라고 했지.」"],"title":"옛이야기 「소금 장수와 나루터」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#6','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C23',3,'mc','auto','「발등에 불이 떨어지다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":6,"concept":"K6-1-u4-C23","difficulty":3,"kind":"mc","stem":"「발등에 불이 떨어지다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?","options":[{"t":"코앞에 닥치다","correct":true},{"t":"낯이 뜨겁다","mis":"K6-1-u4-X22"},{"t":"어깨너머로 배우다","mis":"K6-1-u4-X22"},{"t":"입이 무겁다","mis":"K6-1-u4-X22"}],"explanation":["낯이 뜨겁다는 부끄러움이에요.","어깨너머로 배우다는 보고 배우는 거예요.","급한 마음끼리 바꿔 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#7','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C26',3,'mc','auto','짧은 대화를 지은 뒤 관용 표현을 빼고 다시 읽어 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X09','K6-1-u4-X07','K6-1-u4-X25']::text[],false,'{"seq":7,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"짧은 대화를 지은 뒤 관용 표현을 빼고 다시 읽어 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 표현이 대화에 무엇을 더했는지 알 수 있어서","correct":true},{"t":"관용 표현이 없는 대화가 언제나 더 좋아서","mis":"K6-1-u4-X09"},{"t":"관용 표현의 개수를 늘리려고","mis":"K6-1-u4-X07"},{"t":"읽는 시간을 줄이려고","mis":"K6-1-u4-X25"}],"explanation":["빼는 것이 늘 좋은 것은 아니에요.","개수를 늘리려는 것이 아니에요.","표현이 더한 것을 견줘 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#8','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C24',4,'mc','auto','짝이 넘어져 무릎을 다치고 울고 있어요. 이 자리에서 가장 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08','K6-1-u4-X07']::text[],false,'{"seq":8,"concept":"K6-1-u4-C24","difficulty":4,"kind":"mc","stem":"짝이 넘어져 무릎을 다치고 울고 있어요. 이 자리에서 가장 알맞은 말은 어느 것인가요?","options":[{"t":"관용 표현을 넣지 않고 「많이 아팠지? 보건실에 같이 가자.」라고 말한다","correct":true},{"t":"「원숭이도 나무에서 떨어진다더니.」라고 웃으며 말한다","mis":"K6-1-u4-X23"},{"t":"「첫술에 배부르랴.」라고 말한다","mis":"K6-1-u4-X08"},{"t":"관용 표현을 셋 넣어 길게 위로한다","mis":"K6-1-u4-X07"}],"explanation":["아픈 친구를 웃으며 놀리면 안 돼요.","뜻이 상황과 어긋나요.","관용 표현이 언제나 알맞은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#9','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C20',4,'essay','teacher','초아가 「목마른 사람이 우물 판다잖아.」라고 말한 의도를 쓰고, 「내가 먼저 가 볼게.」라고만 말했을 때와 무엇이 다른지 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C20","difficulty":4,"kind":"essay","stem":"초아가 「목마른 사람이 우물 판다잖아.」라고 말한 의도를 쓰고, 「내가 먼저 가 볼게.」라고만 말했을 때와 무엇이 다른지 견주어 쓰세요.","answer_guide":{"answer":"예: 초아는 새롬이를 걱정하는 답답한 사람이 자기이니 자기가 먼저 나서는 것이 당연하다고 전하려고 이 속담을 썼다. 「내가 먼저 가 볼게.」라고만 하면 뜻은 통하지만 왜 나서는지와 그때의 마음은 보이지 않는다. 속담을 앞에 놓으니 나서는 까닭과 마음이 함께 전해진다.","scoring_points":["초아의 의도를 바르게 썼는가","그냥 말했을 때 빠지는 것을 썼는가","속담이 더한 까닭과 마음을 견주어 썼는가"]},"explanation":["속담 뒤에 붙은 말을 봐요.","그냥 말한 것과 견줘요.","무엇이 더 전해졌는지 써요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#10','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C26',4,'essay','teacher','관용 표현 하나를 골라 상황 짜기 네 칸(표현 · 상황 · 누가 누구에게 · 어긋나지 않는지)을 채우고, 그 표현이 한 번 들어간 짧은 대화를 지으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C26","difficulty":4,"kind":"essay","stem":"관용 표현 하나를 골라 상황 짜기 네 칸(표현 · 상황 · 누가 누구에게 · 어긋나지 않는지)을 채우고, 그 표현이 한 번 들어간 짧은 대화를 지으세요.","answer_guide":{"answer":"예: 표현 — 발등에 불이 떨어지다. 상황 — 숙제 마감이 내일 아침인데 아직 시작하지 않았다. 누가 누구에게 — 형이 동생에게. 살피기 — 급한 마음을 나타내는 말이라 상황과 어긋나지 않는다. 대화 — 형: 「숙제 다 했어?」 동생: 「아직 하나도 안 했어.」 형: 「발등에 불이 떨어졌네. 지금 바로 시작하자.」 동생: 「응, 도와줘.」","scoring_points":["네 칸을 모두 채웠는가","표현의 뜻과 상황이 어긋나지 않는가","표현이 한 번 들어간 대화를 지었는가"]},"explanation":["표현과 상황을 정해요.","누가 누구에게 말할지 정해요.","마지막 칸을 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#1','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C27',1,'mc','auto','「견학 기록문」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29','K6-1-u4-X26']::text[],false,'{"seq":1,"concept":"K6-1-u4-C27","difficulty":1,"kind":"mc","stem":"「견학 기록문」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글","correct":true},{"t":"하루 일을 돌아보며 마음만 적은 글","mis":"K6-1-u4-X30"},{"t":"어떤 곳을 알리려고 사실만 적은 안내문","mis":"K6-1-u4-X29"},{"t":"지어낸 인물이 나오는 이야기","mis":"K6-1-u4-X26"}],"explanation":["마음만 있으면 일기예요.","사실만 있으면 안내문이에요.","새로 안 사실과 마음이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#2','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',1,'match','auto','견학 기록문의 세 가지와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u4-C28","difficulty":1,"kind":"match","stem":"견학 기록문의 세 가지와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"여정","r":"어디를 거쳐 어떻게 다녔는지, 다닌 길"},{"l":"견문","r":"보고 들은 것, 새롭게 안 사실"},{"l":"감상","r":"생각하거나 느낀 것"}],"mis":"K6-1-u4-X27","explanation":["다닌 길은 여정이에요.","보고 들은 것은 견문이에요.","느낀 것은 감상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#3','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C29',1,'mc','auto','견학 기록문의 처음 부분에 쓰는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":3,"concept":"K6-1-u4-C29","difficulty":1,"kind":"mc","stem":"견학 기록문의 처음 부분에 쓰는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학한 까닭 · 함께 간 사람 · 견학 장소","correct":true},{"t":"견학한 내용 정리와 깨달은 점","mis":"K6-1-u4-X28"},{"t":"전시실에서 본 것과 그때의 마음","mis":"K6-1-u4-X28"},{"t":"다음에 가고 싶은 다른 곳의 목록","mis":"K6-1-u4-X28"}],"explanation":["정리와 깨달음은 끝이에요.","본 것과 마음은 가운데예요.","처음에는 개요를 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#4','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C30',1,'ox','auto','견학 기록문에는 새로 안 사실과 그때의 마음이 함께 들어가야 해요.',ARRAY['K6-1-u4-X29']::text[],false,'{"seq":4,"concept":"K6-1-u4-C30","difficulty":1,"kind":"ox","stem":"견학 기록문에는 새로 안 사실과 그때의 마음이 함께 들어가야 해요.","answer":"O","reason_options":[{"t":"사실만 남으면 안내문이 되고 마음만 남으면 일기가 되기 때문에","correct":true},{"t":"새로 안 사실만 적어도 충분하기 때문에","mis":"K6-1-u4-X29"}],"mis":"K6-1-u4-X29","explanation":["사실만으로는 부족해요.","마음만으로도 부족해요.","둘이 함께 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#5','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C31',2,'mc','auto','「갯벌 생태관을 다녀와서」라는 제목만 보고 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X26']::text[],false,'{"seq":5,"concept":"K6-1-u4-C31","difficulty":2,"kind":"mc","stem":"「갯벌 생태관을 다녀와서」라는 제목만 보고 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌을 다루는 전시관에 다녀온 뒤 쓴 글이고, 갯벌에 대해 새로 안 것이 담겼을 것이다","correct":true},{"t":"갯벌을 지키자고 주장하는 글일 것이다","mis":"K6-1-u4-X31"},{"t":"갯벌에 사는 인물이 나오는 옛이야기일 것이다","mis":"K6-1-u4-X26"},{"t":"생태관에 가는 길만 적은 글일 것이다","mis":"K6-1-u4-X31"}],"explanation":["「다녀와서」는 주장하는 말이 아니에요.","옛이야기가 아니에요.","다녀온 곳과 새로 안 것을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#6','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','첫째 문단에서 여정에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"첫째 문단에서 여정에 해당하는 것은 어느 것인가요?","options":[{"t":"「버스로 사십 분을 달려 바닷가 마을에 닿았다.」","correct":true},{"t":"「목이 빠지게 기다리던 날이었다.」","mis":"K6-1-u4-X27"},{"t":"「학교에서 갯벌 이야기를 들었다.」","mis":"K6-1-u4-X27"},{"t":"「실제 갯벌을 보고 싶었다.」","mis":"K6-1-u4-X27"}],"explanation":["기다린 마음은 감상 쪽이에요.","들은 까닭은 여정이 아니에요.","어떻게 다녔는지가 여정이에요."],"asset":{"type":"passage","lines":["지난 토요일, 가족과 함께 우리 고장의 갯벌 생태관에 다녀왔다.","학교에서 갯벌 이야기를 들은 뒤로 실제 갯벌을 보고 싶었는데,","마침 주말에 문을 연다고 해서 목이 빠지게 기다리던 날이었다.","버스로 사십 분을 달려 바닷가 마을에 닿았다."],"title":"「갯벌 생태관을 다녀와서」 — 첫째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#7','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','셋째 · 넷째 문단에서 견문에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":7,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"셋째 · 넷째 문단에서 견문에 해당하는 것은 어느 것인가요?","options":[{"t":"「짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있다.」","correct":true},{"t":"「마지막으로 관찰 데크에 올랐다.」","mis":"K6-1-u4-X27"},{"t":"「다음 전시실로 들어갔다.」","mis":"K6-1-u4-X27"},{"t":"「쉬어 가는 곳이었다는 것을 처음 알아 놀랐다.」","mis":"K6-1-u4-X27"}],"explanation":["관찰 데크에 오른 것은 여정이에요.","전시실로 간 것도 여정이에요.","새로 안 사실이 견문이에요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#8','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C27',2,'ox','auto','견학 기록문을 쓸 때 견학한 곳에서 새로 안 사실은 그럴듯하게 꾸며 써도 돼요.',ARRAY['K6-1-u4-X26']::text[],false,'{"seq":8,"concept":"K6-1-u4-C27","difficulty":2,"kind":"ox","stem":"견학 기록문을 쓸 때 견학한 곳에서 새로 안 사실은 그럴듯하게 꾸며 써도 돼요.","answer":"X","reason_options":[{"t":"견학 기록문은 정보를 전하는 글이라 새로 안 사실은 참이어야 하기 때문에","correct":true},{"t":"읽는 사람이 재미있기만 하면 되기 때문에","mis":"K6-1-u4-X26"}],"mis":"K6-1-u4-X26","explanation":["견학 기록문은 사실을 실어 날라요.","꾸민 사실은 거짓을 전해요.","새로 안 사실은 참이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#9','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C29',2,'mc','auto','견학 기록문의 끝 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":9,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"견학 기록문의 끝 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「이번 견학으로 갯벌이 수많은 생물이 기대어 사는 곳임을 알게 되었다.」","correct":true},{"t":"「지난 토요일, 가족과 함께 갯벌 생태관에 다녀왔다.」","mis":"K6-1-u4-X28"},{"t":"「다음 전시실에는 칠게와 짱뚱어가 있었다.」","mis":"K6-1-u4-X28"},{"t":"「버스로 바닷가 마을에 닿았다.」","mis":"K6-1-u4-X28"}],"explanation":["간 때와 사람은 처음이에요.","전시실에서 본 것은 가운데예요.","정리하고 깨달은 점이 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#10','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C30',3,'mc','auto','견학 기록문에서 감상이 모두 빠지면 어떤 글에 가까워질까요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29']::text[],false,'{"seq":10,"concept":"K6-1-u4-C30","difficulty":3,"kind":"mc","stem":"견학 기록문에서 감상이 모두 빠지면 어떤 글에 가까워질까요?","options":[{"t":"그곳을 알리는 안내문","correct":true},{"t":"하루를 돌아보는 일기","mis":"K6-1-u4-X30"},{"t":"마음을 전하는 편지","mis":"K6-1-u4-X29"},{"t":"그래도 견학 기록문","mis":"K6-1-u4-X29"}],"explanation":["일기는 마음만 남은 글이에요.","편지도 마음을 전해요.","사실만 남으면 안내문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#1','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C31',2,'mc','auto','견학 기록문에서 문단의 중심 내용을 찾을 때 먼저 볼 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X07']::text[],false,'{"seq":1,"concept":"K6-1-u4-C31","difficulty":2,"kind":"mc","stem":"견학 기록문에서 문단의 중심 내용을 찾을 때 먼저 볼 것은 어느 것인가요?","options":[{"t":"그 문단이 처음 · 가운데 · 끝 가운데 어느 자리에 있는지","correct":true},{"t":"문단에 낱말이 몇 개 있는지","mis":"K6-1-u4-X31"},{"t":"관용 표현이 몇 개 들었는지","mis":"K6-1-u4-X07"},{"t":"가장 긴 문장이 무엇인지","mis":"K6-1-u4-X31"}],"explanation":["낱말 수는 몫을 알려 주지 않아요.","관용 표현 개수도 아니에요.","자리에 따라 맡은 몫이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#2','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',2,'ox','auto','견학 기록문에서 여정 · 견문 · 감상은 차례대로 한 번씩만 나와요.',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":2,"concept":"K6-1-u4-C28","difficulty":2,"kind":"ox","stem":"견학 기록문에서 여정 · 견문 · 감상은 차례대로 한 번씩만 나와요.","answer":"X","reason_options":[{"t":"다닌 길을 따라 셋이 번갈아 엮이기 때문에","correct":true},{"t":"여정을 다 적은 뒤 견문을, 마지막에 감상을 몰아 써야 하기 때문에","mis":"K6-1-u4-X27"}],"mis":"K6-1-u4-X27","explanation":["길을 적고","본 것을 적고 마음을 적고","다음 곳에서 다시 되풀이해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#3','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',3,'mc','auto','이 글이 견학 기록문이 되려면 무엇을 더해야 할까요?',ARRAY['K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":3,"concept":"K6-1-u4-C30","difficulty":3,"kind":"mc","stem":"이 글이 견학 기록문이 되려면 무엇을 더해야 할까요?","options":[{"t":"그곳에서 보고 들어 새로 안 사실","correct":true},{"t":"「재미있었다」를 여러 번 더 쓴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 많이 넣는다","mis":"K6-1-u4-X07"},{"t":"지금도 견학 기록문이니 그대로 둔다","mis":"K6-1-u4-X30"}],"explanation":["느낌을 늘려도 그대로예요.","관용 표현 개수가 문제가 아니에요.","견문이 빠져 일기에 가까워요."],"asset":{"type":"passage","lines":["오늘 갯벌 생태관에 갔다.","재미있었다. 신기했다. 또 오고 싶다."],"title":"어느 학생의 견학 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#4','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C27',3,'error','auto','견학 기록문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X29']::text[],false,'{"seq":4,"concept":"K6-1-u4-C27","difficulty":3,"kind":"error","stem":"견학 기록문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"세아 — 「견학한 곳에서 새로 안 사실은 재미있게 지어내도 괜찮아.」","correct":true,"mis_target":"K6-1-u4-X26"},{"t":"준서 — 「견학한 곳은 우리 고장 어디라도 될 수 있어.」","mis":"K6-1-u4-X26"},{"t":"유나 — 「새로 안 사실을 중심에 놓고 내 마음도 적어.」","mis":"K6-1-u4-X29"}],"explanation":["준서는 바르게 말했어요.","유나도 바르게 말했어요.","새로 안 사실은 참이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#5','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C29',3,'mc','auto','첫째 문단에 들어 있지 않은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":5,"concept":"K6-1-u4-C29","difficulty":3,"kind":"mc","stem":"첫째 문단에 들어 있지 않은 것은 어느 것인가요?","options":[{"t":"갯벌 흙 속 생물이 물을 거른다는 사실","correct":true},{"t":"간 때 — 지난 토요일","mis":"K6-1-u4-X28"},{"t":"함께 간 사람 — 가족","mis":"K6-1-u4-X28"},{"t":"간 까닭 — 실제 갯벌을 보고 싶어서","mis":"K6-1-u4-X28"}],"explanation":["간 때가 들어 있어요.","함께 간 사람도 들어 있어요.","새로 안 사실은 가운데에 나와요."],"asset":{"type":"passage","lines":["지난 토요일, 가족과 함께 우리 고장의 갯벌 생태관에 다녀왔다.","학교에서 갯벌 이야기를 들은 뒤로 실제 갯벌을 보고 싶었는데,","마침 주말에 문을 연다고 해서 목이 빠지게 기다리던 날이었다.","버스로 사십 분을 달려 바닷가 마을에 닿았다."],"title":"「갯벌 생태관을 다녀와서」 — 첫째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#6','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',3,'mc','auto','둘째 문단의 「입이 딱 벌어졌다」는 여정 · 견문 · 감상 가운데 무엇인가요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":3,"kind":"mc","stem":"둘째 문단의 「입이 딱 벌어졌다」는 여정 · 견문 · 감상 가운데 무엇인가요?","options":[{"t":"감상","correct":true},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"처음 부분의 까닭","mis":"K6-1-u4-X28"}],"explanation":["새로 안 사실이 아니에요.","다닌 길도 아니에요.","놀란 마음을 나타냈어요."],"asset":{"type":"passage","lines":["가장 먼저 들어간 곳은 갯벌을 설명하는 전시실이었다.","갯벌은 밀물 때 바닷물에 잠기고 썰물 때 드러나는 땅이라고 한다.","갯벌 흙 속에는 눈에 보이지 않을 만큼 작은 생물이 헤아릴 수 없이 많고,","이 생물들이 바닷물로 흘러든 더러운 물질을 걸러 준다고 했다.","바닷물을 걸러 주는 일을 흙이 한다는 말에 입이 딱 벌어졌다."],"title":"「갯벌 생태관을 다녀와서」 — 둘째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#7','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C31',3,'mc','auto','셋째 · 넷째 문단의 중심 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X31']::text[],false,'{"seq":7,"concept":"K6-1-u4-C31","difficulty":3,"kind":"mc","stem":"셋째 · 넷째 문단의 중심 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌 생물과 도요새를 보며 갯벌이 생물이 기대어 쉬는 곳임을 알았다","correct":true},{"t":"가족과 함께 갯벌 생태관에 다녀왔다","mis":"K6-1-u4-X31"},{"t":"갯벌의 소중함을 알고 눈여겨보기로 했다","mis":"K6-1-u4-X31"},{"t":"버스를 타고 바닷가 마을에 갔다","mis":"K6-1-u4-X31"}],"explanation":["다녀온 것은 첫째 문단이에요.","다짐은 끝 문단이에요.","가운데 문단은 본 것과 안 것이에요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#8','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',4,'mc','auto','두 친구가 쓴 글을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30']::text[],false,'{"seq":8,"concept":"K6-1-u4-C30","difficulty":4,"kind":"mc","stem":"두 친구가 쓴 글을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"㉮는 감상이 빠져 안내문에, ㉯는 견문이 빠져 일기에 가깝고, 둘을 엮어야 견학 기록문이 된다","correct":true},{"t":"㉮만 견학 기록문이다","mis":"K6-1-u4-X29"},{"t":"㉯만 견학 기록문이다","mis":"K6-1-u4-X30"},{"t":"둘 다 견학 기록문이다","mis":"K6-1-u4-X29"}],"explanation":["㉮에는 마음이 없어요.","㉯에는 새로 안 사실이 없어요.","두 가지가 함께 있어야 해요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 땅이다. 짱뚱어는 살갗으로 숨을 쉰다.","　 도요새는 봄과 가을에 갯벌에 들른다.","㉯ 갯벌에 갔다. 재미있었다. 신기했다. 또 오고 싶다."],"title":"두 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#9','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',4,'essay','teacher','이 부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C28","difficulty":4,"kind":"essay","stem":"이 부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 여정 — 「마지막으로 오른 관찰 데크」처럼 다음 곳으로 옮겨 간 길이 드러난다. 견문 — 「짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있다」는 그곳에서 새로 안 사실이다. 감상 — 「쉬어 가는 곳이었다는 것을 처음 알았다」에는 몰랐던 것을 깨달은 글쓴이의 마음이 담겼다.","scoring_points":["여정을 바르게 찾았는가","견문을 바르게 찾았는가","감상을 찾고 까닭을 썼는가"]},"explanation":["다닌 길을 찾아요.","새로 안 사실을 찾아요.","마음이 드러난 곳을 찾아요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#10','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',4,'essay','teacher','견학 기록문이 안내문과 일기와 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C30","difficulty":4,"kind":"essay","stem":"견학 기록문이 안내문과 일기와 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 안내문은 그곳에 대한 사실만 알려 주고, 일기는 그날 느낀 마음을 중심으로 적는다. 견학 기록문은 그 사이에 서는 글로, 견학하고 새롭게 안 사실을 중심에 놓으면서 그것을 알고 내 마음이 어떻게 움직였는지도 함께 적는다. 그래서 견문과 감상이 함께 있어야 한다.","scoring_points":["안내문의 특징을 썼는가","일기의 특징을 썼는가","견학 기록문은 견문과 감상을 함께 담는다고 썼는가"]},"explanation":["안내문을 떠올려요.","일기를 떠올려요.","그 사이의 글을 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#1','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C32',1,'mc','auto','견학 기록문을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X32','K6-1-u4-X38']::text[],false,'{"seq":1,"concept":"K6-1-u4-C32","difficulty":1,"kind":"mc","stem":"견학 기록문을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"보고 들은 것과 그때의 마음을 오래 남길 수 있다","correct":true},{"t":"글씨를 빨리 쓰는 연습이 된다","mis":"K6-1-u4-X32"},{"t":"외운 낱말의 개수를 늘릴 수 있다","mis":"K6-1-u4-X32"},{"t":"다른 사람 글보다 길게 쓸 수 있다","mis":"K6-1-u4-X38"}],"explanation":["글씨 연습이 목적이 아니에요.","낱말 외우기도 아니에요.","흐려지는 것을 붙잡아 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#2','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C33',1,'mc','auto','쓸 견학을 고를 때 가장 중요한 일은 어느 것인가요?',ARRAY['K6-1-u4-X33']::text[],false,'{"seq":2,"concept":"K6-1-u4-C33","difficulty":1,"kind":"mc","stem":"쓸 견학을 고를 때 가장 중요한 일은 어느 것인가요?","options":[{"t":"왜 기억에 남는지 한 줄로 적어 보기","correct":true},{"t":"가장 먼 곳을 고르기","mis":"K6-1-u4-X33"},{"t":"사진을 가장 많이 찍은 곳 고르기","mis":"K6-1-u4-X33"},{"t":"친구가 다녀온 곳을 따라 고르기","mis":"K6-1-u4-X33"}],"explanation":["먼 곳이 좋은 것은 아니에요.","사진 수로 정하지 않아요.","기억에 남은 까닭이 감상이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#3','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C34',1,'mc','auto','목적 · 주제 · 읽을 사람 가운데 글의 모양을 가장 많이 바꾸는 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X34']::text[],false,'{"seq":3,"concept":"K6-1-u4-C34","difficulty":1,"kind":"mc","stem":"목적 · 주제 · 읽을 사람 가운데 글의 모양을 가장 많이 바꾸는 것은 어느 것인가요?","options":[{"t":"읽을 사람","correct":true},{"t":"글씨 크기","mis":"K6-1-u4-X38"},{"t":"종이 색깔","mis":"K6-1-u4-X38"},{"t":"제목의 글자 수","mis":"K6-1-u4-X34"}],"explanation":["글씨 크기는 셋에 들지 않아요.","종이 색도 아니에요.","누가 읽느냐에 따라 낱말과 설명이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#4','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C36',1,'ox','auto','관용 표현은 견문 자리보다 감상 자리에 얹는 것이 잘 어울려요.',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":4,"concept":"K6-1-u4-C36","difficulty":1,"kind":"ox","stem":"관용 표현은 견문 자리보다 감상 자리에 얹는 것이 잘 어울려요.","answer":"O","reason_options":[{"t":"견문은 사실이고 감상은 마음이라 사실 자리에 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"관용 표현은 어디에 넣어도 똑같기 때문에","mis":"K6-1-u4-X36"}],"mis":"K6-1-u4-X36","explanation":["견문은 사실이에요.","감상은 마음이에요.","관용 표현은 마음 쪽에 놓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#5','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C34',2,'mc','auto','읽을 사람이 저학년 동생이라면 무엇을 바꾸면 좋을까요?',ARRAY['K6-1-u4-X34','K6-1-u4-X30']::text[],false,'{"seq":5,"concept":"K6-1-u4-C34","difficulty":2,"kind":"mc","stem":"읽을 사람이 저학년 동생이라면 무엇을 바꾸면 좋을까요?","options":[{"t":"어려운 낱말은 풀어 쓰고 낯선 것은 한 줄 더 설명한다","correct":true},{"t":"문단을 모두 없애고 한 덩어리로 길게 쓴다","mis":"K6-1-u4-X34"},{"t":"새로 안 사실은 빼고 느낀 점만 남긴다","mis":"K6-1-u4-X30"},{"t":"어른이 읽을 때와 똑같이 쓴다","mis":"K6-1-u4-X34"}],"explanation":["문단을 없애면 더 읽기 어려워요.","견문을 빼면 일기가 돼요.","동생이 멈출 곳을 풀어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#6','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C35',2,'match','auto','「소방서를 다녀와서」에 쓸 내용과 들어갈 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u4-C35","difficulty":2,"kind":"match","stem":"「소방서를 다녀와서」에 쓸 내용과 들어갈 자리를 알맞게 이으세요.","pairs":[{"l":"소방관이 하는 일을 알아보려고 반 친구들과 소방서에 갔다","r":"처음"},{"l":"방화복을 들어 보니 생각보다 훨씬 무거웠다","r":"가운데"},{"l":"소방관의 하루가 어떤 하루인지 알게 되었다","r":"끝"}],"mis":"K6-1-u4-X28","explanation":["까닭과 함께 간 사람은 처음이에요.","본 것과 느낀 것은 가운데예요.","정리와 깨달음은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#7','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C35',2,'mc','auto','조직표의 가운데를 짤 때 알맞은 요령은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"조직표의 가운데를 짤 때 알맞은 요령은 어느 것인가요?","options":[{"t":"본 것 하나에 느낀 것 하나를 짝지어 간다","correct":true},{"t":"본 것만 모두 늘어놓고 느낌은 끝에 몰아 쓴다","mis":"K6-1-u4-X35"},{"t":"느낀 것만 적는다","mis":"K6-1-u4-X30"},{"t":"문단마다 관용 표현을 하나씩 넣는다","mis":"K6-1-u4-X07"}],"explanation":["사실만 늘어놓은 글이 돼요.","느낌만 있으면 일기가 돼요.","본 것과 느낀 것을 짝지어요."],"asset":{"type":"passage","lines":["처음 — 까닭(소방관이 하는 일 알아보기) · 반 친구들과 · 우리 고장 소방서","가운데 첫째 — 차고의 소방차 / 소화전에 호스를 잇는다는 것을 앎","　→ 소방차 한 대로 다 되는 줄 알았던 생각이 바뀜","가운데 둘째 — 방화복을 들어 봄 / 무게가 상당함 → 입고 뛴다는 말에 놀람","가운데 셋째 — 신고 받는 곳 / 위치부터 말해야 함 → 나도 그래야겠다고 생각함","끝 — 소방관의 하루는 기다림과 준비로 채워짐 → 길을 비켜 주겠다는 다짐"],"title":"「소방서를 다녀와서」 조직표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#8','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C36',2,'mc','auto','관용 표현을 알맞은 자리에 놓은 문장은 어느 것인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":8,"concept":"K6-1-u4-C36","difficulty":2,"kind":"mc","stem":"관용 표현을 알맞은 자리에 놓은 문장은 어느 것인가요?","options":[{"t":"「이것을 입고 뛴다니 손이 열 개라도 모자라겠다.」","correct":true},{"t":"「소화전에 호스를 잇는데 손이 열 개라도 모자란다.」","mis":"K6-1-u4-X36"},{"t":"「신고할 때 위치를 먼저 말하는 것은 눈코 뜰 새 없다.」","mis":"K6-1-u4-X36"},{"t":"「물탱크의 물은 진땀을 빼며 금방 바닥난다.」","mis":"K6-1-u4-X36"}],"explanation":["사실 자리에 얹었어요.","이것도 사실 자리예요.","놀란 마음 자리에 놓였어요."],"asset":{"type":"passage","lines":["먼저 차고에서 소방차를 보았다. 나는 소방차에 실린 물만으로","불을 끄는 줄 알았는데, 물탱크의 물은 금방 바닥나기 때문에","길가의 소화전에 호스를 이어 물을 끌어 쓴다고 한다.","다음으로 방화복을 들어 보았다. 한 손으로는 들리지 않을 만큼 무거웠다.","이것을 다 입고 계단을 뛰어오른다는 말에","손이 열 개라도 모자라겠다는 생각이 들었다."],"title":"「소방서를 다녀와서」 — 가운데 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#9','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C38',2,'mc','auto','견학 기록문을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07']::text[],false,'{"seq":9,"concept":"K6-1-u4-C38","difficulty":2,"kind":"mc","stem":"견학 기록문을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여정 · 견문 · 감상이 전해지는가","correct":true},{"t":"글씨를 예쁘게 썼는가","mis":"K6-1-u4-X38"},{"t":"다른 사람 글보다 긴가","mis":"K6-1-u4-X38"},{"t":"관용 표현을 많이 넣었는가","mis":"K6-1-u4-X07"}],"explanation":["글씨 모양은 갈래를 정하지 않아요.","길이도 아니에요.","갈래가 갖출 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#10','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C37',3,'mc','auto','「관용 표현을 세 개 넣으랬으니 문단마다 하나씩 넣자.」라는 생각에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u4-X37','K6-1-u4-X07','K6-1-u4-X09']::text[],false,'{"seq":10,"concept":"K6-1-u4-C37","difficulty":3,"kind":"mc","stem":"「관용 표현을 세 개 넣으랬으니 문단마다 하나씩 넣자.」라는 생각에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"마음이 없는 자리에 얹힌 표현은 겉도니, 가장 크게 마음이 움직인 자리에 하나만 놓아도 된다","correct":true},{"t":"세 개를 다 채워야 좋은 글이 된다","mis":"K6-1-u4-X37"},{"t":"더 많이 넣을수록 좋은 글이 된다","mis":"K6-1-u4-X07"},{"t":"관용 표현은 하나도 쓰면 안 된다","mis":"K6-1-u4-X09"}],"explanation":["칸을 채우는 글이 아니에요.","개수가 문제가 아니에요.","제자리에 하나면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#1','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',2,'mc','auto','생각그물로 견학 기록문의 재료를 모을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X29','K6-1-u4-X30']::text[],false,'{"seq":1,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"생각그물로 견학 기록문의 재료를 모을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"순서는 신경 쓰지 않고 다섯 갈래로 떠오르는 대로 모은다","correct":true},{"t":"처음부터 처음 · 가운데 · 끝 차례대로만 적는다","mis":"K6-1-u4-X35"},{"t":"견문 갈래만 가득 채운다","mis":"K6-1-u4-X29"},{"t":"감상 갈래만 가득 채운다","mis":"K6-1-u4-X30"}],"explanation":["순서는 조직표에서 잡아요.","견문만 모으면 감상이 없어요.","다섯 갈래를 고루 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#2','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C37',2,'ox','auto','견학 기록문에서 담을 것이 없는 자리는 비워 두어도 돼요.',ARRAY['K6-1-u4-X37']::text[],false,'{"seq":2,"concept":"K6-1-u4-C37","difficulty":2,"kind":"ox","stem":"견학 기록문에서 담을 것이 없는 자리는 비워 두어도 돼요.","answer":"O","reason_options":[{"t":"가장 중요한 것은 진솔함이고 칸은 채울 것이 아니라 담을 그릇이기 때문에","correct":true},{"t":"정해진 칸을 다 채워야 견학 기록문이 되기 때문에","mis":"K6-1-u4-X37"}],"mis":"K6-1-u4-X37","explanation":["억지로 채우면 겉돌아요.","진솔함이 가장 중요해요.","담을 것이 없으면 비워도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#3','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C33',3,'mc','auto','쓸 견학을 고를 때 「기억에 남은 까닭」을 적어 두는 것이 중요한 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X28','K6-1-u4-X33']::text[],false,'{"seq":3,"concept":"K6-1-u4-C33","difficulty":3,"kind":"mc","stem":"쓸 견학을 고를 때 「기억에 남은 까닭」을 적어 두는 것이 중요한 까닭은 어느 것인가요?","options":[{"t":"그 까닭이 곧 글의 감상이 되기 때문에","correct":true},{"t":"까닭이 길수록 글이 길어지기 때문에","mis":"K6-1-u4-X38"},{"t":"처음 부분에는 까닭만 쓰면 되기 때문에","mis":"K6-1-u4-X28"},{"t":"읽을 사람이 까닭을 외워야 하기 때문에","mis":"K6-1-u4-X33"}],"explanation":["길이를 늘리려는 것이 아니에요.","처음에는 까닭 말고도 써요.","까닭이 감상으로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#4','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C36',3,'error','auto','「소방서를 다녀와서」에 관용 표현을 넣어 보았어요. 알맞지 않게 넣은 친구는 누구인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":4,"concept":"K6-1-u4-C36","difficulty":3,"kind":"error","stem":"「소방서를 다녀와서」에 관용 표현을 넣어 보았어요. 알맞지 않게 넣은 친구는 누구인가요?","options":[{"t":"은호 — 「물탱크의 물은 발등에 불이 떨어지게 금방 바닥난다.」","correct":true,"mis_target":"K6-1-u4-X36"},{"t":"서진 — 「돌아오는 길에 마주친 소방차가 오래도록 눈에 선했다.」","mis":"K6-1-u4-X36"},{"t":"나윤 — 「이것을 입고 뛴다니 손이 열 개라도 모자라겠다는 생각이 들었다.」","mis":"K6-1-u4-X36"}],"explanation":["서진이는 마음 자리에 놓았어요.","나윤이도 마음 자리에 놓았어요.","사실 자리에 얹으면 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#5','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C38',3,'mc','auto','읽을 사람이 가족이라면 견학 기록문을 어떻게 나누면 좋을까요?',ARRAY['K6-1-u4-X39']::text[],false,'{"seq":5,"concept":"K6-1-u4-C38","difficulty":3,"kind":"mc","stem":"읽을 사람이 가족이라면 견학 기록문을 어떻게 나누면 좋을까요?","options":[{"t":"가족이 함께 보는 곳에 붙이거나 가족에게 직접 읽어 준다","correct":true},{"t":"공책에 써서 서랍에 넣어 둔다","mis":"K6-1-u4-X39"},{"t":"가장 많이 인쇄해 여러 곳에 붙인다","mis":"K6-1-u4-X39"},{"t":"가족이 보지 않는 반 게시판에만 올린다","mis":"K6-1-u4-X39"}],"explanation":["서랍 속 글은 읽을 수 없어요.","많이 붙인다고 읽는 것이 아니에요.","읽을 사람이 정말 읽을 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#6','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',3,'mc','auto','조직표의 「소방차 한 대로 다 되는 줄 알았던 생각이 바뀜」은 무엇인가요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C35","difficulty":3,"kind":"mc","stem":"조직표의 「소방차 한 대로 다 되는 줄 알았던 생각이 바뀜」은 무엇인가요?","options":[{"t":"견문에 짝지은 감상","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"처음 부분의 견학한 까닭","mis":"K6-1-u4-X28"},{"t":"끝 부분의 정리","mis":"K6-1-u4-X28"}],"explanation":["다닌 길이 아니에요.","견학한 까닭도 아니에요.","새로 안 사실 뒤에 붙인 마음이에요."],"asset":{"type":"passage","lines":["처음 — 까닭(소방관이 하는 일 알아보기) · 반 친구들과 · 우리 고장 소방서","가운데 첫째 — 차고의 소방차 / 소화전에 호스를 잇는다는 것을 앎","　→ 소방차 한 대로 다 되는 줄 알았던 생각이 바뀜","가운데 둘째 — 방화복을 들어 봄 / 무게가 상당함 → 입고 뛴다는 말에 놀람","가운데 셋째 — 신고 받는 곳 / 위치부터 말해야 함 → 나도 그래야겠다고 생각함","끝 — 소방관의 하루는 기다림과 준비로 채워짐 → 길을 비켜 주겠다는 다짐"],"title":"「소방서를 다녀와서」 조직표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#7','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C32',3,'mc','auto','견학 기록문이 읽는 사람에게 주는 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X32']::text[],false,'{"seq":7,"concept":"K6-1-u4-C32","difficulty":3,"kind":"mc","stem":"견학 기록문이 읽는 사람에게 주는 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 보지 못한 사람에게 그곳을 알리고, 가려는 사람이 무엇을 볼지 미리 알게 한다","correct":true},{"t":"읽는 사람의 글씨가 좋아진다","mis":"K6-1-u4-X32"},{"t":"쓴 사람이 외운 낱말 수가 늘어난다","mis":"K6-1-u4-X32"},{"t":"읽는 사람은 견학을 갈 필요가 없어진다","mis":"K6-1-u4-X32"}],"explanation":["글씨와는 상관없어요.","낱말 수도 아니에요.","그곳의 모습이 읽는 사람에게 건너가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#8','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C34',4,'mc','auto','이 부분을 저학년 동생에게 읽어 줄 글로 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X07','K6-1-u4-X34']::text[],false,'{"seq":8,"concept":"K6-1-u4-C34","difficulty":4,"kind":"mc","stem":"이 부분을 저학년 동생에게 읽어 줄 글로 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「물탱크」 「소화전」 「방화복」을 동생이 알 수 있게 풀어 쓰고 한 줄씩 더 설명한다","correct":true},{"t":"새로 안 사실을 빼고 느낌만 남긴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 더 넣어 재미있게 만든다","mis":"K6-1-u4-X07"},{"t":"누가 읽든 같으니 그대로 둔다","mis":"K6-1-u4-X34"}],"explanation":["견문을 빼면 안 돼요.","관용 표현 개수가 문제가 아니에요.","읽을 사람에 맞게 풀어 줘요."],"asset":{"type":"passage","lines":["먼저 차고에서 소방차를 보았다. 나는 소방차에 실린 물만으로","불을 끄는 줄 알았는데, 물탱크의 물은 금방 바닥나기 때문에","길가의 소화전에 호스를 이어 물을 끌어 쓴다고 한다.","다음으로 방화복을 들어 보았다. 한 손으로는 들리지 않을 만큼 무거웠다.","이것을 다 입고 계단을 뛰어오른다는 말에","손이 열 개라도 모자라겠다는 생각이 들었다."],"title":"「소방서를 다녀와서」 — 가운데 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#9','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',4,'essay','teacher','내가 다녀온 견학 하나로 조직표를 짜 보세요. 처음 · 가운데 둘 · 끝으로 나누고, 가운데에는 본 것 하나에 느낀 것 하나를 짝지으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C35","difficulty":4,"kind":"essay","stem":"내가 다녀온 견학 하나로 조직표를 짜 보세요. 처음 · 가운데 둘 · 끝으로 나누고, 가운데에는 본 것 하나에 느낀 것 하나를 짝지으세요.","answer_guide":{"answer":"예: 처음 — 별을 가까이 보고 싶어서 가족과 고장의 천문대에 갔다. 가운데 첫째 — 망원경 방에서 달을 보았다 / 달 표면에 크고 작은 구덩이가 많았다 → 매끈할 줄 알았는데 놀랐다. 가운데 둘째 — 별자리 방에서 설명을 들었다 / 별은 스스로 빛을 낸다 → 밤하늘이 다르게 보였다. 끝 — 하늘에 대해 새로 안 것이 많았다 → 다음에는 별자리 지도를 들고 밤하늘을 보겠다.","scoring_points":["처음에 까닭 · 함께 간 사람 · 장소를 썼는가","가운데마다 본 것과 느낀 것을 짝지었는가","끝에 정리와 깨달은 점을 썼는가"]},"explanation":["처음에 개요를 써요.","가운데는 본 것과 느낀 것을 짝지어요.","끝에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#10','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C37',4,'essay','teacher','「여정 · 견문 · 감상도, 관용 표현도 채워야 할 칸이 아니라 담을 그릇이다」라는 말을 설명하고, 관용 표현을 어디에 몇 개 놓을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C37","difficulty":4,"kind":"essay","stem":"「여정 · 견문 · 감상도, 관용 표현도 채워야 할 칸이 아니라 담을 그릇이다」라는 말을 설명하고, 관용 표현을 어디에 몇 개 놓을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 견학 기록문에서 가장 중요한 것은 진솔함이라, 마음이 없는 자리에 억지로 표현을 채우면 글이 겉돈다. 그래서 담을 것이 있을 때 담고, 없으면 비워 두어도 된다. 나는 관용 표현을 문단마다 넣지 않고, 가장 크게 놀라거나 마음이 움직인 감상 자리에 하나만 놓겠다.","scoring_points":["칸 채우기가 아니라는 뜻을 설명했는가","진솔함이 중요하다는 점을 썼는가","관용 표현을 놓을 자리와 개수를 내 생각으로 썼는가"]},"explanation":["칸과 그릇을 견줘요.","진솔함을 떠올려요.","자리와 개수를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#1','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',1,'mc','auto','다음 가운데 동물이 들어간 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X03']::text[],false,'{"seq":1,"concept":"K6-1-u4-C39","difficulty":1,"kind":"mc","stem":"다음 가운데 동물이 들어간 관용 표현은 어느 것인가요?","options":[{"t":"원숭이도 나무에서 떨어진다","correct":true},{"t":"강아지에게 물을 주었다","mis":"K6-1-u4-X03"},{"t":"새가 나뭇가지에 앉았다","mis":"K6-1-u4-X03"},{"t":"고양이가 낮잠을 잤다","mis":"K6-1-u4-X03"}],"explanation":["강아지 이야기가 뜻 그대로예요.","새 이야기도 뜻 그대로예요.","잘하는 사람도 실수한다는 새 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#2','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C40',1,'mc','auto','관용 표현 사전 한 장에 담을 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X41']::text[],false,'{"seq":2,"concept":"K6-1-u4-C40","difficulty":1,"kind":"mc","stem":"관용 표현 사전 한 장에 담을 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"표현 · 뜻 · 쓸 수 있는 상황","correct":true},{"t":"표현이 만들어진 정확한 때","mis":"K6-1-u4-X41"},{"t":"그 표현을 아는 친구의 수","mis":"K6-1-u4-X41"},{"t":"그 표현을 쓴 횟수","mis":"K6-1-u4-X41"}],"explanation":["만들어진 때는 꺼내 쓰는 데 쓸모없어요.","친구 수도 마찬가지예요.","세 칸이 있어야 꺼내 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#3','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',1,'mc','auto','학급 전체 앞에서 발표할 때 지킬 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":3,"concept":"K6-1-u4-C42","difficulty":1,"kind":"mc","stem":"학급 전체 앞에서 발표할 때 지킬 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"존댓말로, 모두 들을 수 있는 크기로 말한다","correct":true},{"t":"둘레에 들리지 않게 작은 소리로 말한다","mis":"K6-1-u4-X42"},{"t":"생각날 때마다 끼어들어 말한다","mis":"K6-1-u4-X43"},{"t":"친구와 쉬는 시간에 하듯 반말로 말한다","mis":"K6-1-u4-X42"}],"explanation":["작은 소리는 짝과 이야기할 때예요.","끼어들면 안 돼요.","여럿이 듣는 자리에 맞게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#4','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C41',1,'ox','auto','관용 표현 사전에는 아무도 모르는 어려운 표현을 많이 모을수록 좋아요.',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":4,"concept":"K6-1-u4-C41","difficulty":1,"kind":"ox","stem":"관용 표현 사전에는 아무도 모르는 어려운 표현을 많이 모을수록 좋아요.","answer":"X","reason_options":[{"t":"개수도 어려움도 아닌 내가 쓸 자리가 떠오르는 표현을 골라야 하기 때문에","correct":true},{"t":"어려운 표현이 많아야 좋은 사전이기 때문에","mis":"K6-1-u4-X40"}],"mis":"K6-1-u4-X40","explanation":["만든 나조차 안 쓰는 사전이 돼요.","개수가 기준이 아니에요.","쓸 자리가 떠오르는 표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#5','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'match','auto','몸을 가리키는 말이 든 표현과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u4-C39","difficulty":2,"kind":"match","stem":"몸을 가리키는 말이 든 표현과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"어깨너머로 배우다","r":"옆에서 보고 들으며 배우다"},{"l":"목에 힘을 주다","r":"잘난 체하며 거만하게 굴다"},{"l":"등을 떠밀다","r":"하기 싫어하는 사람을 억지로 나서게 하다"}],"mis":"K6-1-u4-X12","explanation":["어깨 위로 넘어다보는 장면이에요.","목을 꼿꼿이 세운 장면이에요.","등을 밀어 내보내는 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#6','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'mc','auto','「고양이 목에 방울 달기」를 쓰기에 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"「고양이 목에 방울 달기」를 쓰기에 알맞은 상황은 어느 것인가요?","options":[{"t":"학급 회의에서 모두 좋다고 했지만 맡겠다고 나서는 사람이 없을 때","correct":true},{"t":"늘 잘하던 친구가 한 번 틀렸을 때","mis":"K6-1-u4-X08"},{"t":"옆에서 지켜보다 어느새 할 줄 알게 되었을 때","mis":"K6-1-u4-X08"},{"t":"고양이에게 목걸이를 사 줄 때","mis":"K6-1-u4-X01"}],"explanation":["실수 이야기는 원숭이 속담이에요.","보고 익힌 것은 서당 개 속담이에요.","말은 좋은데 해내기 어려운 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#7','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'mc','auto','관용 표현을 낱말로 묶을 때와 마음으로 묶을 때를 알맞게 견준 것은 어느 것인가요?',ARRAY['K6-1-u4-X44']::text[],false,'{"seq":7,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"관용 표현을 낱말로 묶을 때와 마음으로 묶을 때를 알맞게 견준 것은 어느 것인가요?","options":[{"t":"낱말로 묶으면 찾기가 쉽고, 마음으로 묶으면 쓰기가 쉽다","correct":true},{"t":"낱말로 묶으면 쓰기가 쉽고, 마음으로 묶으면 찾기가 쉽다","mis":"K6-1-u4-X44"},{"t":"둘 다 쓸모가 없으니 흩어 두는 게 낫다","mis":"K6-1-u4-X44"},{"t":"둘은 똑같아서 어느 쪽이든 차이가 없다","mis":"K6-1-u4-X44"}],"explanation":["두 말이 뒤바뀌었어요.","묶어 두면 빨리 떠올라요.","둘은 좋은 점이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#8','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','「도서관 서고를 다녀와서」 앞부분에서 여정에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":8,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"「도서관 서고를 다녀와서」 앞부분에서 여정에 해당하는 것은 어느 것인가요?","options":[{"t":"「사서 선생님을 따라 처음 일반 서고에 들어갔다.」","correct":true},{"t":"「책의 주제에 따라 숫자를 정해 꽂는다.」","mis":"K6-1-u4-X27"},{"t":"「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」","mis":"K6-1-u4-X27"},{"t":"「모든 책에는 숫자가 붙어 있었다.」","mis":"K6-1-u4-X27"}],"explanation":["숫자로 꽂는 것은 새로 안 사실이에요.","깨달은 마음은 감상이에요.","어디로 들어갔는지가 여정이에요."],"asset":{"type":"passage","lines":["지난 화요일, 우리 반은 고장의 도서관에 갔다.","사서 선생님을 따라 처음 들어간 곳은 일반 서고였다.","모든 책에는 숫자가 붙어 있었다. 책의 주제에 따라 숫자를 정해 두고","그 차례대로 꽂는다고 한다. 내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다."],"title":"「도서관 서고를 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#9','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',2,'mc','auto','쉬는 시간에 친구와 이야기할 때 지킬 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":9,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"쉬는 시간에 친구와 이야기할 때 지킬 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"둘레에 방해가 되지 않게 작은 소리로, 말차례를 지키며 반응을 보인다","correct":true},{"t":"발표할 때처럼 모두 들리게 큰 소리로 말한다","mis":"K6-1-u4-X42"},{"t":"친구 말이 끝나기 전에 끼어든다","mis":"K6-1-u4-X43"},{"t":"고개를 돌리고 대꾸하지 않는다","mis":"K6-1-u4-X43"}],"explanation":["큰 소리는 둘레에 방해가 돼요.","말차례를 지켜요.","고개를 끄덕이며 반응해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#10','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',3,'mc','auto','상황에 따라 언어 예절을 정하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43']::text[],false,'{"seq":10,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"상황에 따라 언어 예절을 정하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 편하게 들을 수 있는가","correct":true},{"t":"외운 예절 목록에 있는가","mis":"K6-1-u4-X43"},{"t":"내가 편하게 말할 수 있는가","mis":"K6-1-u4-X43"},{"t":"목소리가 충분히 큰가","mis":"K6-1-u4-X43"}],"explanation":["목록에 없는 상황도 있어요.","말하는 사람이 기준이 아니에요.","듣는 사람을 두고 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#1','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C9',2,'mc','auto','「손때가 묻은 책」의 「손때가 묻다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X12']::text[],false,'{"seq":1,"concept":"K6-1-u4-C9","difficulty":2,"kind":"mc","stem":"「손때가 묻은 책」의 「손때가 묻다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"오래 쓰고 매만져 정이 들다","correct":true},{"t":"손을 씻지 않아 책이 더러워졌다","mis":"K6-1-u4-X01"},{"t":"새로 사서 아주 깨끗하다","mis":"K6-1-u4-X01"},{"t":"손으로 만지면 안 되는 책이다","mis":"K6-1-u4-X12"}],"explanation":["더러워진 이야기가 아니에요.","새 책과 반대예요.","오래 아껴 써 온 마음이에요."],"asset":{"type":"passage","lines":["다음으로 간 보존 서고는 공기가 서늘했다.","종이는 습기와 더위에 약해서 온도와 습도를 늘 일정하게 지킨다고 했다.","오래된 책은 따로 두고, 넘길 때에도 두 손으로 조심해 다룬다고 한다.","표지가 닳고 손때가 묻은 책들이 나란히 서 있는 모습을 한참 바라보았다.","이번 견학으로 도서관이 책을 지키는 곳이라는 것을 알게 되었다."],"title":"「도서관 서고를 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#2','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C40',2,'ox','auto','관용 표현 사전의 쓸 상황은 내가 겪은 일이나 겪을 법한 일로 적어요.',ARRAY['K6-1-u4-X11']::text[],false,'{"seq":2,"concept":"K6-1-u4-C40","difficulty":2,"kind":"ox","stem":"관용 표현 사전의 쓸 상황은 내가 겪은 일이나 겪을 법한 일로 적어요.","answer":"O","reason_options":[{"t":"내 상황이 적힌 사전이라야 필요할 때 떠오르기 때문에","correct":true},{"t":"쓸 상황은 사전에 적힌 예문을 그대로 옮겨야 하기 때문에","mis":"K6-1-u4-X11"}],"mis":"K6-1-u4-X11","explanation":["뜻만 적으면 한 번 보고 덮어요.","내 상황이라야 떠올라요.","셋째 칸이 가장 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#3','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C9',3,'mc','auto','「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X21']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":3,"kind":"mc","stem":"「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"헝클어져 있던 일의 갈피가 잡혀 까닭을 깨달았다","correct":true},{"t":"흩어진 실을 한 가닥으로 묶었다","mis":"K6-1-u4-X01"},{"t":"도서관에서 길을 잃고 헤맸다","mis":"K6-1-u4-X21"},{"t":"머리카락을 가지런히 묶었다","mis":"K6-1-u4-X01"}],"explanation":["실을 묶은 이야기가 아니에요.","길을 잃은 것도 아니에요.","왜 헤맸는지 깨달았어요."],"asset":{"type":"passage","lines":["지난 화요일, 우리 반은 고장의 도서관에 갔다.","사서 선생님을 따라 처음 들어간 곳은 일반 서고였다.","모든 책에는 숫자가 붙어 있었다. 책의 주제에 따라 숫자를 정해 두고","그 차례대로 꽂는다고 한다. 내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다."],"title":"「도서관 서고를 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#4','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',3,'error','auto','친구의 발표를 듣는 모습이에요. 예절에 알맞지 않은 친구는 누구인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":4,"concept":"K6-1-u4-C42","difficulty":3,"kind":"error","stem":"친구의 발표를 듣는 모습이에요. 예절에 알맞지 않은 친구는 누구인가요?","options":[{"t":"하린 — 발표하는 친구 쪽을 보지 않고 짝과 작은 소리로 이야기했다","correct":true,"mis_target":"K6-1-u4-X42"},{"t":"시안 — 바른 자세로 발표하는 친구를 보며 끝까지 들었다","mis":"K6-1-u4-X42"},{"t":"연우 — 발표가 끝난 뒤 존댓말로 궁금한 것을 물었다","mis":"K6-1-u4-X42"}],"explanation":["시안이는 끝까지 경청했어요.","연우는 끝난 뒤 존댓말로 물었어요.","발표 중에는 짝과 이야기하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#5','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C41',3,'mc','auto','관용 표현 사전에 넣을 표현을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":5,"concept":"K6-1-u4-C41","difficulty":3,"kind":"mc","stem":"관용 표현 사전에 넣을 표현을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이번 달에 한 번은 쓸 자리가 떠오르는 표현 다섯 개를 고른다","correct":true},{"t":"아무도 모르는 어려운 표현을 스무 개 고른다","mis":"K6-1-u4-X40"},{"t":"가장 긴 표현부터 고른다","mis":"K6-1-u4-X40"},{"t":"사전 앞쪽에 나오는 표현을 차례대로 고른다","mis":"K6-1-u4-X40"}],"explanation":["어려운 표현은 쓰지 않게 돼요.","길이는 기준이 아니에요.","쓸 자리가 떠오르는지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#6','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C39',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」를 쓰기에 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C39","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」를 쓰기에 알맞은 상황은 어느 것인가요?","options":[{"t":"옆에서 지켜보기만 했는데 어느새 할 줄 알게 되었을 때","correct":true},{"t":"늘 잘하던 친구가 한 번 실수했을 때","mis":"K6-1-u4-X08"},{"t":"모두 찬성했지만 아무도 나서지 않는 일을 두고","mis":"K6-1-u4-X08"},{"t":"강아지를 오래 길렀을 때","mis":"K6-1-u4-X01"}],"explanation":["실수는 원숭이 속담이에요.","나서지 않는 일은 방울 달기예요.","오래 보고 들어 저절로 익혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#7','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',3,'mc','auto','공식적인 말하기에서 목소리 크기 · 표정 · 자세까지 살피는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43','K6-1-u4-X42']::text[],false,'{"seq":7,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"공식적인 말하기에서 목소리 크기 · 표정 · 자세까지 살피는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"말의 내용뿐 아니라 이것들도 듣는 사람이 편하게 듣는 데 영향을 주기 때문에","correct":true},{"t":"외워야 할 예절 목록에 적혀 있기 때문에","mis":"K6-1-u4-X43"},{"t":"말의 내용은 중요하지 않기 때문에","mis":"K6-1-u4-X43"},{"t":"비공식적인 자리와 예절이 같기 때문에","mis":"K6-1-u4-X42"}],"explanation":["목록이라서가 아니에요.","내용도 중요해요.","듣는 사람이 편한지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#8','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C40',4,'mc','auto','누리가 만든 사전 한 장을 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X41','K6-1-u4-X11','K6-1-u4-X40']::text[],false,'{"seq":8,"concept":"K6-1-u4-C40","difficulty":4,"kind":"mc","stem":"누리가 만든 사전 한 장을 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"뜻은 「여러 번 들어 익숙하다」처럼 내 말로 줄이고, 쓸 상황에 내가 겪은 일을 적고, 친구 수는 뺀다","correct":true},{"t":"아는 친구의 수를 더 정확히 세어 적는다","mis":"K6-1-u4-X41"},{"t":"사전 뜻풀이를 더 길게 옮겨 적는다","mis":"K6-1-u4-X11"},{"t":"다른 표현을 세 개 더 채워 넣는다","mis":"K6-1-u4-X40"}],"explanation":["친구 수는 쓸모가 없어요.","길게 옮기면 내 말이 아니에요.","세 칸을 제대로 채워요."],"asset":{"type":"passage","lines":["표현 — 귀에 익다","뜻 — (사전 뜻풀이를 한 글자도 빼지 않고 길게 옮겨 적음)","쓸 수 있는 상황 — (비어 있음)","덧붙임 — 이 표현을 아는 우리 반 친구의 수"],"title":"누리가 만든 관용 표현 사전 한 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#9','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C39',4,'essay','teacher','관용 표현 사전의 주제를 하나 정하고(낱말로 묶기 또는 마음으로 묶기), 그 주제에 맞는 표현 두 개를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C39","difficulty":4,"kind":"essay","stem":"관용 표현 사전의 주제를 하나 정하고(낱말로 묶기 또는 마음으로 묶기), 그 주제에 맞는 표현 두 개를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰세요.","answer_guide":{"answer":"예: 주제 — 마음으로 묶기, 「간절함」. 표현 하나 — 목이 빠지게 기다리다 / 몹시 애타게 기다리다 / 방학에 할머니 댁에 갈 날을 기다릴 때. 표현 둘 — 마음이 굴뚝같다 / 무엇을 몹시 하고 싶어 하다 / 감기로 축구 시합에 못 나갔지만 뛰고 싶을 때.","scoring_points":["묶는 방법과 주제를 정했는가","주제에 맞는 표현 두 개를 골랐는가","표현마다 뜻과 내 쓸 상황을 썼는가"]},"explanation":["묶는 방법을 정해요.","주제에 맞는 표현을 골라요.","세 칸을 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#10','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',4,'essay','teacher','쉬는 시간에 친구와 이야기할 때와 학급 전체 앞에서 발표할 때 지킬 예절이 어떻게 다른지 쓰고, 왜 달라지는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C42","difficulty":4,"kind":"essay","stem":"쉬는 시간에 친구와 이야기할 때와 학급 전체 앞에서 발표할 때 지킬 예절이 어떻게 다른지 쓰고, 왜 달라지는지 설명하세요.","answer_guide":{"answer":"예: 쉬는 시간에는 둘레에 방해가 되지 않게 작은 소리로 말하고, 말차례를 지키며 고개를 끄덕이는 등 반응을 보인다. 발표할 때에는 존댓말로, 모두 들을 수 있는 크기로, 바른 자세로 듣는 사람을 보며 말한다. 듣는 사람의 수와 자리가 달라 듣는 사람이 편하게 들을 수 있는 방법도 달라지기 때문이다.","scoring_points":["비공식적인 말하기의 예절을 썼는가","공식적인 말하기의 예절을 썼는가","듣는 사람을 기준으로 달라지는 까닭을 썼는가"]},"explanation":["쉬는 시간을 떠올려요.","발표하는 자리를 떠올려요.","듣는 사람을 두고 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#1','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C1',1,'mc','auto','오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말을 무엇이라고 하나요?',ARRAY['K6-1-u4-X05']::text[],false,'{"seq":1,"concept":"K6-1-u4-C1","difficulty":1,"kind":"mc","stem":"오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말을 무엇이라고 하나요?","options":[{"t":"관용 표현","correct":true},{"t":"줄임말","mis":"K6-1-u4-X05"},{"t":"흉내 내는 말","mis":"K6-1-u4-X05"},{"t":"높임말","mis":"K6-1-u4-X05"}],"explanation":["줄임말은 짧게 줄인 말이에요.","흉내 내는 말은 소리나 모양을 흉내 내요.","굳어져 새 뜻을 지닌 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#2','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C3',1,'mc','auto','「진땀을 빼다」는 관용어와 속담 가운데 무엇인가요?',ARRAY['K6-1-u4-X04','K6-1-u4-X01']::text[],false,'{"seq":2,"concept":"K6-1-u4-C3","difficulty":1,"kind":"mc","stem":"「진땀을 빼다」는 관용어와 속담 가운데 무엇인가요?","options":[{"t":"관용어","correct":true},{"t":"속담","mis":"K6-1-u4-X04"},{"t":"관용 표현이 아니다","mis":"K6-1-u4-X01"},{"t":"표어","mis":"K6-1-u4-X04"}],"explanation":["교훈을 담은 말이 아니에요.","뜻 그대로가 아니에요.","낱말이 합쳐져 새 뜻을 이룬 관용어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#3','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C9',1,'mc','auto','「진땀을 빼다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「진땀을 빼다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 일을 겪으며 몹시 애를 쓰다","correct":true},{"t":"흐르는 땀을 수건으로 닦다","mis":"K6-1-u4-X01"},{"t":"땀이 전혀 나지 않다","mis":"K6-1-u4-X01"},{"t":"더워서 겉옷을 벗다","mis":"K6-1-u4-X01"}],"explanation":["땀 닦는 이야기가 아니에요.","땀이 안 나는 것도 아니에요.","몹시 애쓴다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#4','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C15',1,'mc','auto','「빈 수레가 요란하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16','K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「빈 수레가 요란하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘 알지 못하는 사람이 오히려 더 떠든다","correct":true},{"t":"빈 수레는 가벼워 끌기 쉽다","mis":"K6-1-u4-X16"},{"t":"짐을 많이 실어야 수레가 잘 간다","mis":"K6-1-u4-X16"},{"t":"수레는 시끄러우니 쓰지 말아야 한다","mis":"K6-1-u4-X17"}],"explanation":["끌기 쉽다는 이야기가 아니에요.","짐 싣는 법도 아니에요.","빈 수레가 덜컹거려 시끄러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#5','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',1,'mc','auto','관용 표현을 쓰기 전에 뜻과 함께 살필 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X40']::text[],false,'{"seq":5,"concept":"K6-1-u4-C24","difficulty":1,"kind":"mc","stem":"관용 표현을 쓰기 전에 뜻과 함께 살필 것은 어느 것인가요?","options":[{"t":"듣는 사람과 지금 이 자리","correct":true},{"t":"표현의 글자 수","mis":"K6-1-u4-X07"},{"t":"표현을 몇 개 넣는지","mis":"K6-1-u4-X07"},{"t":"표현이 얼마나 어려운지","mis":"K6-1-u4-X40"}],"explanation":["글자 수는 상관없어요.","개수도 상관없어요.","누구에게, 어떤 자리인지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#6','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C27',1,'mc','auto','견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글은 무엇인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29','K6-1-u4-X26']::text[],false,'{"seq":6,"concept":"K6-1-u4-C27","difficulty":1,"kind":"mc","stem":"견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글은 무엇인가요?","options":[{"t":"견학 기록문","correct":true},{"t":"일기","mis":"K6-1-u4-X30"},{"t":"안내문","mis":"K6-1-u4-X29"},{"t":"지어낸 이야기","mis":"K6-1-u4-X26"}],"explanation":["일기는 마음 중심이에요.","안내문은 사실만 있어요.","새로 안 사실과 마음이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#7','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C34',1,'mc','auto','견학 기록문을 쓰기 전에 정해 둘 세 가지는 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07','K6-1-u4-X34']::text[],false,'{"seq":7,"concept":"K6-1-u4-C34","difficulty":1,"kind":"mc","stem":"견학 기록문을 쓰기 전에 정해 둘 세 가지는 어느 것인가요?","options":[{"t":"목적 · 주제 · 읽을 사람","correct":true},{"t":"글씨체 · 종이 · 펜","mis":"K6-1-u4-X38"},{"t":"길이 · 문단 수 · 관용 표현 개수","mis":"K6-1-u4-X07"},{"t":"제목 · 사진 · 날씨","mis":"K6-1-u4-X34"}],"explanation":["도구는 정할 것이 아니에요.","개수는 기준이 아니에요.","왜, 무엇을, 누구에게 쓸지 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#8','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C40',1,'mc','auto','관용 표현 사전 한 장에 쓸 상황을 적는 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X37','K6-1-u4-X41']::text[],false,'{"seq":8,"concept":"K6-1-u4-C40","difficulty":1,"kind":"mc","stem":"관용 표현 사전 한 장에 쓸 상황을 적는 까닭은 어느 것인가요?","options":[{"t":"필요할 때 떠올라 꺼내 쓸 수 있어서","correct":true},{"t":"쪽수를 채우려고","mis":"K6-1-u4-X37"},{"t":"표현이 생긴 때를 알리려고","mis":"K6-1-u4-X41"},{"t":"아는 친구 수를 세려고","mis":"K6-1-u4-X41"}],"explanation":["쪽수 채우기가 아니에요.","생긴 때는 쓸모없어요.","내 상황이 적혀야 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#9','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C9',2,'mc','auto','하늬가 말한 「코앞에 닥쳤는데」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08','K6-1-u4-X12']::text[],false,'{"seq":9,"concept":"K6-1-u4-C9","difficulty":2,"kind":"mc","stem":"하늬가 말한 「코앞에 닥쳤는데」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"대회가 아주 가까이 다가왔다","correct":true},{"t":"코 바로 앞에 무엇이 놓였다","mis":"K6-1-u4-X01"},{"t":"대회가 아주 멀리 남았다","mis":"K6-1-u4-X08"},{"t":"코가 막혀 노래하기 어렵다","mis":"K6-1-u4-X12"}],"explanation":["코 앞에 물건이 놓인 것이 아니에요.","멀리 남은 것과 반대예요.","날이 바짝 다가왔다는 뜻이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#10','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C23',2,'mc','auto','하늬의 「목이 빠지게 기다릴게」와 가리키는 마음이 가장 가까운 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":10,"concept":"K6-1-u4-C23","difficulty":2,"kind":"mc","stem":"하늬의 「목이 빠지게 기다릴게」와 가리키는 마음이 가장 가까운 표현은 어느 것인가요?","options":[{"t":"마음이 굴뚝같다","correct":true},{"t":"낯이 뜨겁다","mis":"K6-1-u4-X22"},{"t":"발등에 불이 떨어지다","mis":"K6-1-u4-X22"},{"t":"입이 무겁다","mis":"K6-1-u4-X22"}],"explanation":["낯이 뜨겁다는 부끄러움이에요.","발등에 불은 급함이에요.","간절한 마음끼리 가까워요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#11','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C29',2,'mc','auto','로아 글의 첫 두 줄에 들어 있는 처음 부분의 내용은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":11,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아 글의 첫 두 줄에 들어 있는 처음 부분의 내용은 어느 것인가요?","options":[{"t":"언제 · 누구와 · 왜 · 어디에 갔는지","correct":true},{"t":"견학을 정리하고 깨달은 점","mis":"K6-1-u4-X28"},{"t":"물을 소독하는 방법","mis":"K6-1-u4-X28"},{"t":"다음에 가고 싶은 곳","mis":"K6-1-u4-X28"}],"explanation":["깨달은 점은 끝이에요.","소독은 가운데의 견문이에요.","처음에는 개요를 알려요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#12','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C28',2,'mc','auto','로아 글 뒷부분에서 여정이 드러난 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":12,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"로아 글 뒷부분에서 여정이 드러난 것은 어느 것인가요?","options":[{"t":"「다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.」","correct":true},{"t":"「소독을 해서 해로운 균을 없앤다고 했다.」","mis":"K6-1-u4-X27"},{"t":"「물을 틀어 놓은 채로 양치하지 않아야겠다.」","mis":"K6-1-u4-X27"},{"t":"「여러 단계를 거친다는 것을 알았다.」","mis":"K6-1-u4-X27"}],"explanation":["소독은 새로 안 사실이에요.","다짐은 감상과 깨달음이에요.","어디로 옮겨 갔는지가 여정이에요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#13','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C36',2,'mc','auto','다음 가운데 관용 표현이 감상 자리에 알맞게 놓인 문장은 어느 것인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":13,"concept":"K6-1-u4-C36","difficulty":2,"kind":"mc","stem":"다음 가운데 관용 표현이 감상 자리에 알맞게 놓인 문장은 어느 것인가요?","options":[{"t":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」","correct":true},{"t":"「약품은 눈코 뜰 새 없이 알갱이를 뭉치게 한다.」","mis":"K6-1-u4-X36"},{"t":"「소독은 진땀을 빼며 해로운 균을 없앤다.」","mis":"K6-1-u4-X36"},{"t":"「모래층은 손이 열 개라도 모자라게 물을 거른다.」","mis":"K6-1-u4-X36"}],"explanation":["사실 자리에 얹었어요.","이것도 사실 자리예요.","놀란 마음 자리에 놓였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#14','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C29',2,'mc','auto','로아의 조직표에서 처음 칸에 더해야 할 것은 어느 것인가요?',ARRAY['K6-1-u4-X28','K6-1-u4-X07']::text[],false,'{"seq":14,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아의 조직표에서 처음 칸에 더해야 할 것은 어느 것인가요?","options":[{"t":"견학한 까닭(수돗물이 어떻게 만들어지는지 알아보려고)","correct":true},{"t":"견학을 정리한 깨달은 점","mis":"K6-1-u4-X28"},{"t":"소독하는 방법","mis":"K6-1-u4-X28"},{"t":"넣을 관용 표현","mis":"K6-1-u4-X07"}],"explanation":["깨달은 점은 끝 칸이에요.","소독은 가운데 칸이에요.","처음에는 까닭도 들어가요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#15','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C17',2,'mc','auto','「급할수록 돌아가라」와 「첫술에 배부르랴」를 바꿔 쓸 수 있는지 정할 때 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X16']::text[],false,'{"seq":15,"concept":"K6-1-u4-C17","difficulty":2,"kind":"mc","stem":"「급할수록 돌아가라」와 「첫술에 배부르랴」를 바꿔 쓸 수 있는지 정할 때 알맞은 것은 어느 것인가요?","options":[{"t":"서두른다고 빨라지지 않는다는 뜻이 겹치지만, 쓸 상황까지 견주어 정한다","correct":true},{"t":"뜻이 겹치니 언제나 바꿔 쓴다","mis":"K6-1-u4-X18"},{"t":"글자 수가 달라 바꿀 수 없다","mis":"K6-1-u4-X18"},{"t":"두 속담은 뜻이 반대이다","mis":"K6-1-u4-X16"}],"explanation":["늘 바꿀 수 있는 것은 아니에요.","글자 수는 상관없어요.","쓸 상황까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#16','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C42',2,'mc','auto','시온이의 발표에서 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"시온이의 발표에서 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"모두 들을 수 있는 크기로, 듣는 사람을 보며, 존댓말로 말한다","correct":true},{"t":"지금보다 더 작은 목소리로 말한다","mis":"K6-1-u4-X42"},{"t":"반말을 그대로 쓴다","mis":"K6-1-u4-X42"},{"t":"쉬는 시간에 짝과 이야기하듯 편하게 말한다","mis":"K6-1-u4-X42"}],"explanation":["작은 목소리는 여럿에게 안 들려요.","여럿 앞에서는 존댓말을 써요.","공식적인 자리에 맞게 말해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#17','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C1',3,'error','auto','「입을 모으다」를 설명했어요. 알맞지 않게 설명한 친구는 누구인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":17,"concept":"K6-1-u4-C1","difficulty":3,"kind":"error","stem":"「입을 모으다」를 설명했어요. 알맞지 않게 설명한 친구는 누구인가요?","options":[{"t":"하랑 — 「입술을 동그랗게 모은다는 뜻이야.」","correct":true,"mis_target":"K6-1-u4-X01"},{"t":"다은 — 「여럿이 같은 말을 한다는 뜻이야.」","mis":"K6-1-u4-X01"},{"t":"주원 — 「낱말 뜻의 합과는 다른 뜻을 지녔어.」","mis":"K6-1-u4-X01"}],"explanation":["다은이는 뜻을 바르게 말했어요.","주원이는 성질을 바르게 말했어요.","글자 그대로 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#18','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C17',3,'error','auto','비슷한 속담을 견주어 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X18']::text[],false,'{"seq":18,"concept":"K6-1-u4-C17","difficulty":3,"kind":"error","stem":"비슷한 속담을 견주어 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은재 — 「가랑비 속담과 바늘 도둑 속담은 기우는 방향까지 똑같아.」","correct":true,"mis_target":"K6-1-u4-X18"},{"t":"민결 — 「둘 다 작은 것이 쌓인다는 뜻이 겹쳐.」","mis":"K6-1-u4-X18"},{"t":"서율 — 「바늘 도둑은 나쁜 일이 커지는 쪽이야.」","mis":"K6-1-u4-X18"}],"explanation":["민결이는 겹치는 뜻을 바르게 말했어요.","서율이는 기우는 방향을 바르게 말했어요.","기우는 방향은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#19','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',3,'error','auto','친구들이 관용 표현을 쓴 말이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X23']::text[],false,'{"seq":19,"concept":"K6-1-u4-C24","difficulty":3,"kind":"error","stem":"친구들이 관용 표현을 쓴 말이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"라온 — 아파서 결석한 짝에게 「눈코 뜰 새 없이 바빴겠구나.」라고 했다","correct":true,"mis_target":"K6-1-u4-X08"},{"t":"예린 — 늘 잘하던 친구가 실수하자 「원숭이도 나무에서 떨어진다잖아.」라고 위로했다","mis":"K6-1-u4-X23"},{"t":"도윤 — 연습을 미룬 자신에게 「내가 빈 수레가 요란했구나.」라고 썼다","mis":"K6-1-u4-X23"}],"explanation":["예린이는 위로하는 자리에 맞게 썼어요.","도윤이는 자신을 돌아봤어요.","아픈 친구에게 바빴냐고 하면 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#20','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C30',3,'error','auto','견학 기록문을 고쳐 쓰자는 의견이에요. 알맞지 않은 의견을 낸 친구는 누구인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30','K6-1-u4-X35']::text[],false,'{"seq":20,"concept":"K6-1-u4-C30","difficulty":3,"kind":"error","stem":"견학 기록문을 고쳐 쓰자는 의견이에요. 알맞지 않은 의견을 낸 친구는 누구인가요?","options":[{"t":"하율 — 「사실만 늘어놓으면 깔끔하니 마음은 다 지우자.」","correct":true,"mis_target":"K6-1-u4-X29"},{"t":"지유 — 「느낌만 있으니 새로 안 사실을 더하자.」","mis":"K6-1-u4-X30"},{"t":"건우 — 「본 것 하나에 느낀 것 하나를 붙이자.」","mis":"K6-1-u4-X35"}],"explanation":["지유는 견문을 더하자고 했어요.","건우는 짝짓자고 했어요.","마음을 다 지우면 안내문이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#21','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C34',3,'mc','auto','같은 정수장 견학을 할머니께 보낼 글로 쓴다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X34','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":21,"concept":"K6-1-u4-C34","difficulty":3,"kind":"mc","stem":"같은 정수장 견학을 할머니께 보낼 글로 쓴다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니가 궁금해하실 만한 것을 골라 읽기 편하게 쓰고, 큰 글씨나 직접 읽어 드리는 방법도 생각한다","correct":true},{"t":"누구에게 보내든 똑같이 쓴다","mis":"K6-1-u4-X34"},{"t":"새로 안 사실을 빼고 느낌만 쓴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 가득 넣는다","mis":"K6-1-u4-X07"}],"explanation":["읽을 사람이 달라지면 글도 달라져요.","견문을 빼면 안 돼요.","읽을 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#22','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C41',3,'error','auto','관용 표현 사전을 만들 계획이에요. 알맞지 않은 계획을 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":22,"concept":"K6-1-u4-C41","difficulty":3,"kind":"error","stem":"관용 표현 사전을 만들 계획이에요. 알맞지 않은 계획을 말한 친구는 누구인가요?","options":[{"t":"태린 — 「아무도 모르는 어려운 표현으로 스무 개를 채울래.」","correct":true,"mis_target":"K6-1-u4-X40"},{"t":"소이 — 「이번 달에 한 번은 쓸 표현 다섯 개를 고를래.」","mis":"K6-1-u4-X40"},{"t":"하진 — 「쓸 상황이 안 떠오르는 표현은 다음으로 미룰래.」","mis":"K6-1-u4-X40"}],"explanation":["소이는 쓸 표현을 골랐어요.","하진이도 바르게 계획했어요.","어려운 표현을 채우면 쓰지 않게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#23','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C20',4,'mc','auto','합창 대회 대화에서 세 친구가 관용 표현을 쓴 방식을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X01','K6-1-u4-X20']::text[],false,'{"seq":23,"concept":"K6-1-u4-C20","difficulty":4,"kind":"mc","stem":"합창 대회 대화에서 세 친구가 관용 표현을 쓴 방식을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"저마다 상황과 듣는 사람에 맞는 표현을 골라 감싸 주고, 다짐하고, 응원하는 마음을 짧고 또렷하게 전했다","correct":true},{"t":"관용 표현을 많이 넣었으니 좋은 대화다","mis":"K6-1-u4-X07"},{"t":"모두 낱말 뜻 그대로 썼다","mis":"K6-1-u4-X01"},{"t":"가온이는 이든이를 놀리려고 속담을 썼다","mis":"K6-1-u4-X20"}],"explanation":["개수 때문에 좋은 것이 아니에요.","낱말 뜻 그대로가 아니에요.","가온이는 감싸 주려 했어요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#24','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',4,'essay','teacher','대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말을 관용 표현 하나를 넣어 쓰고, 그 표현이 이 자리와 듣는 사람에게 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C24","difficulty":4,"kind":"essay","stem":"대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말을 관용 표현 하나를 넣어 쓰고, 그 표현이 이 자리와 듣는 사람에게 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「원숭이도 나무에서 떨어진다잖아. 그동안 밤마다 연습한 거 다 알아. 다음엔 더 잘될 거야.」 이든이는 실수해서 속상할 것이므로 위로하는 말이 필요하다. 「원숭이도 나무에서 떨어진다」는 잘하는 사람도 실수할 때가 있다는 뜻이라 이든이를 감싸 주는 자리에 맞는다. 「빈 수레가 요란하다」처럼 깎아내리는 표현은 이 자리에 맞지 않는다.","scoring_points":["관용 표현 하나를 넣어 하늬의 말을 썼는가","표현의 뜻이 상황과 맞는 까닭을 썼는가","듣는 사람의 마음을 생각한 까닭을 썼는가"]},"explanation":["이든이의 마음을 떠올려요.","위로하는 표현을 골라요.","까닭을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#25','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C6',4,'essay','teacher','「관용 표현은 제자리에 놓일 때만 힘을 낸다」는 말을 개수 · 듣는 사람 · 글의 자리 세 가지와 이어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C6","difficulty":4,"kind":"essay","stem":"「관용 표현은 제자리에 놓일 때만 힘을 낸다」는 말을 개수 · 듣는 사람 · 글의 자리 세 가지와 이어 설명하세요.","answer_guide":{"answer":"예: 첫째, 관용 표현은 많이 넣는다고 좋아지지 않고 상황에 맞는 하나가 힘이 크다. 둘째, 같은 표현도 누구에게 하느냐에 따라 위로가 되기도 하고 상처가 되기도 하므로 듣는 사람과 자리를 살펴야 한다. 셋째, 견학 기록문에서는 사실을 전하는 견문 자리가 아니라 마음이 드러나는 감상 자리에 놓아야 한다.","scoring_points":["개수의 문제를 썼는가","듣는 사람과 자리의 문제를 썼는가","글에서 놓일 자리(감상)를 썼는가"]},"explanation":["개수를 떠올려요.","듣는 사람을 떠올려요.","견학 기록문의 자리를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#1','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C2',1,'ox','auto','「창문을 닦다」는 관용 표현이에요.',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":1,"kind":"ox","stem":"「창문을 닦다」는 관용 표현이에요.","answer":"X","reason_options":[{"t":"낱말 뜻을 그대로 더해도 말이 통하기 때문에","correct":true},{"t":"두 낱말이 합쳐진 말은 모두 관용 표현이기 때문에","mis":"K6-1-u4-X02"}],"mis":"K6-1-u4-X02","explanation":["창문을 정말 닦는 말이에요.","뜻이 달라지지 않아요.","뜻 그대로면 관용 표현이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#2','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C4',1,'mc','auto','관용 표현에 우리 문화가 담겨 있다는 것을 보여 주는 것은 어느 것인가요?',ARRAY['K6-1-u4-X17','K6-1-u4-X01','K6-1-u4-X05']::text[],false,'{"seq":2,"concept":"K6-1-u4-C4","difficulty":1,"kind":"mc","stem":"관용 표현에 우리 문화가 담겨 있다는 것을 보여 주는 것은 어느 것인가요?","options":[{"t":"속담 속 수레 · 서당처럼 옛 생활 모습이 남아 있다","correct":true},{"t":"요즘 새로 만든 말이 많다","mis":"K6-1-u4-X17"},{"t":"낱말 뜻 그대로라 누구나 안다","mis":"K6-1-u4-X01"},{"t":"외국에서 들어온 말이 대부분이다","mis":"K6-1-u4-X05"}],"explanation":["오래 전해 온 말이에요.","낱말 뜻 그대로가 아니에요.","옛 생활이 말 속에 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#3','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C9',1,'mc','auto','「눈코 뜰 새 없다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X12','K6-1-u4-X08']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「눈코 뜰 새 없다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몹시 바쁘다","correct":true},{"t":"잠이 와서 눈이 감긴다","mis":"K6-1-u4-X01"},{"t":"감기로 코가 막혔다","mis":"K6-1-u4-X12"},{"t":"아무 일도 없어 한가하다","mis":"K6-1-u4-X08"}],"explanation":["졸린 이야기가 아니에요.","코가 막힌 것도 아니에요.","쉴 틈 없이 바쁘다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#4','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C15',1,'mc','auto','「가랑비에 옷 젖는 줄 모른다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":4,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"사소한 것이 쌓여 큰 것이 되는 줄 모른다","correct":true},{"t":"비 오는 날에는 우산을 꼭 챙겨라","mis":"K6-1-u4-X16"},{"t":"젖은 옷은 금방 마른다","mis":"K6-1-u4-X16"},{"t":"큰비가 와야 옷이 젖는다","mis":"K6-1-u4-X16"}],"explanation":["우산 이야기가 아니에요.","옷 마르는 이야기도 아니에요.","작은 것이 쌓여 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#5','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C24',1,'ox','auto','상을 받은 친구에게 「빈 수레가 요란하다더니.」라고 말하는 것은 알맞아요.',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":5,"concept":"K6-1-u4-C24","difficulty":1,"kind":"ox","stem":"상을 받은 친구에게 「빈 수레가 요란하다더니.」라고 말하는 것은 알맞아요.","answer":"X","reason_options":[{"t":"축하하려던 말이 깎아내리는 말이 되기 때문에","correct":true},{"t":"속담을 쓰면 말이 생생해지기 때문에","mis":"K6-1-u4-X23"}],"mis":"K6-1-u4-X23","explanation":["뜻은 하나지만","남을 가리키면 상처가 돼요.","듣는 사람과 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#6','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',1,'mc','auto','「그곳에서 보고 들은 것, 새롭게 안 사실」을 무엇이라고 하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X31']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":1,"kind":"mc","stem":"「그곳에서 보고 들은 것, 새롭게 안 사실」을 무엇이라고 하나요?","options":[{"t":"견문","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"감상","mis":"K6-1-u4-X27"},{"t":"제목","mis":"K6-1-u4-X31"}],"explanation":["여정은 다닌 길이에요.","감상은 느낀 것이에요.","보고 들은 것은 견문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#7','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C35',1,'mc','auto','견학 기록문의 가운데가 사실만 늘어놓은 글이 되지 않게 하는 방법은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X29','K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C35","difficulty":1,"kind":"mc","stem":"견학 기록문의 가운데가 사실만 늘어놓은 글이 되지 않게 하는 방법은 어느 것인가요?","options":[{"t":"본 것 하나에 느낀 것 하나를 붙여 간다","correct":true},{"t":"느낌은 모두 끝에 몰아 쓴다","mis":"K6-1-u4-X35"},{"t":"사실 문장을 더 늘린다","mis":"K6-1-u4-X29"},{"t":"문단마다 관용 표현을 넣는다","mis":"K6-1-u4-X07"}],"explanation":["몰아 쓰면 가운데는 사실만 남아요.","사실을 늘리면 더 안내문 같아요.","본 것과 느낀 것을 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#8','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C42',1,'mc','auto','다음 가운데 공식적인 말하기 상황은 어느 것인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":8,"concept":"K6-1-u4-C42","difficulty":1,"kind":"mc","stem":"다음 가운데 공식적인 말하기 상황은 어느 것인가요?","options":[{"t":"학급 전체 앞에서 조사한 내용을 발표할 때","correct":true},{"t":"쉬는 시간에 짝과 이야기할 때","mis":"K6-1-u4-X42"},{"t":"집에서 동생과 놀 때","mis":"K6-1-u4-X42"},{"t":"점심을 먹으며 친구와 이야기할 때","mis":"K6-1-u4-X42"}],"explanation":["짝과의 이야기는 비공식적이에요.","동생과도 비공식적이에요.","여럿 앞에서 발표하는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#9','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C20',2,'mc','auto','가온이가 「원숭이도 나무에서 떨어진다고」를 쓴 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X21']::text[],false,'{"seq":9,"concept":"K6-1-u4-C20","difficulty":2,"kind":"mc","stem":"가온이가 「원숭이도 나무에서 떨어진다고」를 쓴 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"늘 잘하던 이든이도 늦을 수 있다고 감싸 주려고","correct":true},{"t":"이든이를 놀리려고","mis":"K6-1-u4-X20"},{"t":"원숭이 이야기를 들려주려고","mis":"K6-1-u4-X21"},{"t":"이든이에게 반주를 그만두라고 하려고","mis":"K6-1-u4-X20"}],"explanation":["놀리는 말이 아니에요.","원숭이 이야기가 아니에요.","실수해도 괜찮다고 감싸 줬어요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#10','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C24',2,'mc','auto','대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08']::text[],false,'{"seq":10,"concept":"K6-1-u4-C24","difficulty":2,"kind":"mc","stem":"대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「원숭이도 나무에서 떨어진다잖아. 다음엔 더 잘될 거야.」","correct":true},{"t":"「빈 수레가 요란하다더니.」","mis":"K6-1-u4-X23"},{"t":"「개구리 올챙이 적 생각 못 하는구나.」","mis":"K6-1-u4-X23"},{"t":"「고양이 목에 방울 달기네.」","mis":"K6-1-u4-X08"}],"explanation":["깎아내리는 말이 돼요.","이것도 상처가 돼요.","실수한 친구를 위로하는 자리예요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#11','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',2,'mc','auto','로아 글 앞부분에서 견문에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":11,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"로아 글 앞부분에서 견문에 해당하는 것은 어느 것인가요?","options":[{"t":"「약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.」","correct":true},{"t":"「학교에서 버스를 타고 강가로 갔다.」","mis":"K6-1-u4-X27"},{"t":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」","mis":"K6-1-u4-X27"},{"t":"「먼저 강물을 끌어오는 곳을 보았다.」","mis":"K6-1-u4-X27"}],"explanation":["버스를 탄 것은 여정이에요.","놀란 마음은 감상이에요.","새로 안 사실이 견문이에요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#12','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C29',2,'mc','auto','「앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다.」는 글의 어느 부분에 어울리나요?',ARRAY['K6-1-u4-X28','K6-1-u4-X31']::text[],false,'{"seq":12,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"「앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다.」는 글의 어느 부분에 어울리나요?","options":[{"t":"끝 — 깨달은 점과 다짐","correct":true},{"t":"처음 — 견학한 까닭","mis":"K6-1-u4-X28"},{"t":"가운데 — 새로 안 사실","mis":"K6-1-u4-X28"},{"t":"제목","mis":"K6-1-u4-X31"}],"explanation":["까닭이 아니에요.","새로 안 사실이 아니에요.","정리와 다짐은 끝이에요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#13','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C37',2,'mc','auto','로아가 「관용 표현을 세 개는 넣어야 해.」라며 문단마다 넣으려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X37','K6-1-u4-X09']::text[],false,'{"seq":13,"concept":"K6-1-u4-C37","difficulty":2,"kind":"mc","stem":"로아가 「관용 표현을 세 개는 넣어야 해.」라며 문단마다 넣으려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「마음이 가장 크게 움직인 자리에 하나면 충분해.」","correct":true},{"t":"「셋이 모자라면 다섯 개 넣어.」","mis":"K6-1-u4-X07"},{"t":"「칸을 채우는 게 제일 중요해.」","mis":"K6-1-u4-X37"},{"t":"「관용 표현은 하나도 쓰지 마.」","mis":"K6-1-u4-X09"}],"explanation":["많이 넣는다고 좋아지지 않아요.","칸 채우기가 아니에요.","제자리에 하나면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#14','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C35',2,'mc','auto','로아의 조직표 가운데 칸들의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X27','K6-1-u4-X29']::text[],false,'{"seq":14,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"로아의 조직표 가운데 칸들의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"본 것에 짝지은 느낀 것이 없어 사실만 늘어놓은 글이 되기 쉽다","correct":true},{"t":"견문이 너무 많아 일기가 된다","mis":"K6-1-u4-X30"},{"t":"차례가 없어 여정이 보이지 않는다","mis":"K6-1-u4-X27"},{"t":"고칠 곳이 없다","mis":"K6-1-u4-X29"}],"explanation":["견문이 많으면 일기가 아니라 안내문 쪽이에요.","차례는 있어요.","느낀 것이 빠졌어요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#15','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C19',2,'mc','auto','속담을 바꾸어 지을 때 꼭 함께 적을 것은 어느 것인가요?',ARRAY['K6-1-u4-X19','K6-1-u4-X41']::text[],false,'{"seq":15,"concept":"K6-1-u4-C19","difficulty":2,"kind":"mc","stem":"속담을 바꾸어 지을 때 꼭 함께 적을 것은 어느 것인가요?","options":[{"t":"어떤 상황에서 쓸 말인지","correct":true},{"t":"바꾼 낱말의 글자 수","mis":"K6-1-u4-X19"},{"t":"원래 속담이 생긴 때","mis":"K6-1-u4-X41"},{"t":"바꾼 속담을 아는 친구의 수","mis":"K6-1-u4-X41"}],"explanation":["글자 수는 상관없어요.","생긴 때는 쓸모없어요.","쓸 상황을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#16','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C42',2,'mc','auto','다인이의 행동을 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X43','K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"다인이의 행동을 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"공식적인 자리에서 발표를 끝까지 경청하지 않았다","correct":true},{"t":"작은 소리였으니 괜찮다","mis":"K6-1-u4-X43"},{"t":"쉬는 시간 이야기라 괜찮다","mis":"K6-1-u4-X42"},{"t":"다인이는 예절을 잘 지켰다","mis":"K6-1-u4-X43"}],"explanation":["작은 소리여도 경청하지 않았어요.","발표 도중이었어요.","끝까지 들어야 해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#17','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C5',3,'mc','auto','「손이 열 개라도 모자라다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":17,"concept":"K6-1-u4-C5","difficulty":3,"kind":"mc","stem":"「손이 열 개라도 모자라다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「잔치 준비로 손이 열 개라도 모자랐다.」","correct":true},{"t":"「잔치 준비로 손이 아홉 개라도 모자랐다.」","mis":"K6-1-u4-X06"},{"t":"「잔치 준비로 손가락이 열 개라도 모자랐다.」","mis":"K6-1-u4-X06"},{"t":"「잔치 준비로 두 손이 열 개라도 넉넉했다.」","mis":"K6-1-u4-X06"}],"explanation":["수를 바꾸면 안 돼요.","낱말을 바꿔도 안 돼요.","굳어진 모양 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#18','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C16',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」에서 「서당」이 옛날 아이들이 글을 배우던 곳임을 알고 나서 할 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X17','K6-1-u4-X01']::text[],false,'{"seq":18,"concept":"K6-1-u4-C16","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」에서 「서당」이 옛날 아이들이 글을 배우던 곳임을 알고 나서 할 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"옛 배움터가 말 속에 남아 옛 생활을 엿볼 수 있다","correct":true},{"t":"서당이 없어졌으니 틀린 속담이다","mis":"K6-1-u4-X17"},{"t":"개가 실제로 글을 읽었다는 뜻이다","mis":"K6-1-u4-X01"},{"t":"요즘 말로만 바꿔 써야 한다","mis":"K6-1-u4-X17"}],"explanation":["없어졌다고 틀린 말이 아니에요.","개가 글을 읽은 것이 아니에요.","옛 생활이 남은 흔적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#19','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C20',3,'mc','auto','초아와 같은 의도로 「목마른 사람이 우물 판다」를 쓴 말은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X01']::text[],false,'{"seq":19,"concept":"K6-1-u4-C20","difficulty":3,"kind":"mc","stem":"초아와 같은 의도로 「목마른 사람이 우물 판다」를 쓴 말은 어느 것인가요?","options":[{"t":"「목마른 사람이 우물 판다잖아. 궁금한 내가 먼저 선생님께 여쭤볼게.」","correct":true},{"t":"「너희는 왜 아무도 안 나서니? 목마른 사람이 우물 판다잖아.」","mis":"K6-1-u4-X20"},{"t":"「나는 이런 속담도 알아. 목마른 사람이 우물 판다.」","mis":"K6-1-u4-X20"},{"t":"「목마른 사람이 우물 판다니까 우물을 파러 가자.」","mis":"K6-1-u4-X01"}],"explanation":["남을 꾸짖는 말이 됐어요.","자랑하는 말이 됐어요.","아쉬운 내가 먼저 나선다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#20','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C31',3,'mc','auto','「도서관 서고를 다녀와서」라는 제목만 보고 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X26']::text[],false,'{"seq":20,"concept":"K6-1-u4-C31","difficulty":3,"kind":"mc","stem":"「도서관 서고를 다녀와서」라는 제목만 보고 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"도서관에서 책을 보관하는 곳에 다녀와 새로 안 것을 쓴 글일 것이다","correct":true},{"t":"도서관 이용 규칙을 지키자고 주장하는 글일 것이다","mis":"K6-1-u4-X31"},{"t":"책 속 인물이 나오는 이야기일 것이다","mis":"K6-1-u4-X26"},{"t":"서고에 가는 길만 적은 글일 것이다","mis":"K6-1-u4-X31"}],"explanation":["주장하는 글이 아니에요.","이야기가 아니에요.","다녀온 곳과 새로 안 것을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#21','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C38',3,'error','auto','고쳐 쓸 때 한 일이에요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X36']::text[],false,'{"seq":21,"concept":"K6-1-u4-C38","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 한 일이에요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"시하 — 짝 글보다 짧아서 아무 문장이나 더 늘렸다","correct":true,"mis_target":"K6-1-u4-X38"},{"t":"로운 — 여정 · 견문 · 감상이 다 전해지는지 다시 읽었다","mis":"K6-1-u4-X38"},{"t":"채이 — 관용 표현이 상황에 맞게 놓였는지 살폈다","mis":"K6-1-u4-X36"}],"explanation":["로운이는 갈래가 갖출 것을 살폈어요.","채이도 바르게 살폈어요.","길이는 고쳐 쓸 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#22','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C40',3,'mc','auto','「목에 힘을 주다」 사전 한 장에서 「쓸 수 있는 상황」 칸을 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u4-X11','K6-1-u4-X41','K6-1-u4-X01']::text[],false,'{"seq":22,"concept":"K6-1-u4-C40","difficulty":3,"kind":"mc","stem":"「목에 힘을 주다」 사전 한 장에서 「쓸 수 있는 상황」 칸을 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"상을 받고 나서 친구들 앞에서 거만하게 구는 사람을 두고","correct":true},{"t":"잘난 체하며 거만하게 굴다(뜻을 한 번 더 씀)","mis":"K6-1-u4-X11"},{"t":"이 표현이 처음 생긴 때","mis":"K6-1-u4-X41"},{"t":"목 운동을 하는 방법","mis":"K6-1-u4-X01"}],"explanation":["뜻은 둘째 칸이에요.","생긴 때는 쓸모없어요.","내가 쓸 상황을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#23','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C30',4,'mc','auto','로아 글을 고치려는 의견 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":23,"concept":"K6-1-u4-C30","difficulty":4,"kind":"mc","stem":"로아 글을 고치려는 의견 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사실 문장은 그대로 두고, 모래와 자갈 층과 소독 문장 뒤에 그때의 마음을 한 문장씩 붙인다","correct":true},{"t":"감상 문장을 모두 지워 깔끔한 안내문으로 만든다","mis":"K6-1-u4-X29"},{"t":"견문을 모두 지우고 느낌만 남긴다","mis":"K6-1-u4-X30"},{"t":"문장마다 관용 표현을 하나씩 넣는다","mis":"K6-1-u4-X07"}],"explanation":["감상을 지우면 안내문이 돼요.","견문을 지우면 일기가 돼요.","본 것에 느낀 것을 짝지어요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#24','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',4,'essay','teacher','로아 글 앞부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C28","difficulty":4,"kind":"essay","stem":"로아 글 앞부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 여정 — 「학교에서 버스를 타고 강가로 갔다」는 어떻게 다녔는지 보여 준다. 견문 — 「약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다」는 정수장에서 새로 안 사실이다. 감상 — 「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다」는 놀란 마음을 나타낸다.","scoring_points":["여정을 찾고 까닭을 썼는가","견문을 찾고 까닭을 썼는가","감상을 찾고 까닭을 썼는가"]},"explanation":["다닌 길을 찾아요.","새로 안 사실을 찾아요.","마음이 드러난 곳을 찾아요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#25','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C30',4,'essay','teacher','견학 기록문이 안내문이나 일기와 다른 점을 쓰고, 좋은 견학 기록문이 갖추어야 할 것을 세 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C30","difficulty":4,"kind":"essay","stem":"견학 기록문이 안내문이나 일기와 다른 점을 쓰고, 좋은 견학 기록문이 갖추어야 할 것을 세 가지 쓰세요.","answer_guide":{"answer":"예: 안내문은 사실만, 일기는 마음만 중심으로 쓰지만 견학 기록문은 새롭게 안 사실을 중심에 놓고 그때의 마음도 함께 적는다. 좋은 견학 기록문은 첫째, 여정 · 견문 · 감상이 드러나고, 둘째, 처음 · 가운데 · 끝의 짜임이 있으며, 셋째, 새로 안 사실이 참이고 마음이 진솔하게 담겨 있어야 한다.","scoring_points":["안내문 · 일기와 다른 점을 썼는가","여정 · 견문 · 감상이나 짜임을 썼는가","사실이 참이고 마음이 진솔해야 함을 썼는가"]},"explanation":["두 글과 견줘요.","갖출 것을 떠올려요.","세 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#1','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C2',1,'mc','auto','다음 가운데 낱말 뜻의 합과 다른 새 뜻을 지닌 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 낱말 뜻의 합과 다른 새 뜻을 지닌 관용 표현은 어느 것인가요?","options":[{"t":"입이 무겁다","correct":true},{"t":"문을 닫다","mis":"K6-1-u4-X02"},{"t":"손을 씻다","mis":"K6-1-u4-X02"},{"t":"책을 읽다","mis":"K6-1-u4-X02"}],"explanation":["문을 닫는 것은 뜻 그대로예요.","손을 씻는 것도 뜻 그대로예요.","말이 신중하다는 새 뜻이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#2','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C5',1,'ox','auto','관용 표현은 굳어진 모양 그대로 익혀야 해요.',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":2,"concept":"K6-1-u4-C5","difficulty":1,"kind":"ox","stem":"관용 표현은 굳어진 모양 그대로 익혀야 해요.","answer":"O","reason_options":[{"t":"낱말을 바꾸거나 늘이면 뜻을 잃기 때문에","correct":true},{"t":"모양은 마음대로 바꿔도 뜻이 같기 때문에","mis":"K6-1-u4-X06"}],"mis":"K6-1-u4-X06","explanation":["통째로 굳은 말이에요.","바꾸면 뜻이 사라져요.","모양 그대로 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#3','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C12',1,'mc','auto','「입이 무겁다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01']::text[],false,'{"seq":3,"concept":"K6-1-u4-C12","difficulty":1,"kind":"mc","stem":"「입이 무겁다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"말이 신중해 함부로 옮기지 않는다","correct":true},{"t":"입을 다쳐 말하기 힘들다","mis":"K6-1-u4-X12"},{"t":"음식을 많이 먹는다","mis":"K6-1-u4-X01"},{"t":"입술이 두툼하다","mis":"K6-1-u4-X12"}],"explanation":["다친 이야기가 아니에요.","먹는 이야기도 아니에요.","말을 함부로 옮기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#4','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C16',1,'ox','auto','속담 속 낯선 옛말을 찾아보면 옛 생활을 알 수 있어요.',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":1,"kind":"ox","stem":"속담 속 낯선 옛말을 찾아보면 옛 생활을 알 수 있어요.","answer":"O","reason_options":[{"t":"옛말에 조상의 생활과 생각이 남아 있기 때문에","correct":true},{"t":"옛말은 낡아서 알 필요가 없기 때문에","mis":"K6-1-u4-X17"}],"mis":"K6-1-u4-X17","explanation":["옛말은 버릴 말이 아니에요.","옛 생활이 남은 흔적이에요.","찾아보면 우리 문화가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#5','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C21',1,'mc','auto','「마음이 굴뚝같았다」를 고르면 「정말 하고 싶었다」보다 더 전해지는 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20','K6-1-u4-X09']::text[],false,'{"seq":5,"concept":"K6-1-u4-C21","difficulty":1,"kind":"mc","stem":"「마음이 굴뚝같았다」를 고르면 「정말 하고 싶었다」보다 더 전해지는 것은 어느 것인가요?","options":[{"t":"하고 싶은 마음의 크기","correct":true},{"t":"굴뚝이 얼마나 높은지","mis":"K6-1-u4-X21"},{"t":"하기 싫은 마음","mis":"K6-1-u4-X20"},{"t":"아무것도 더 전해지지 않는다","mis":"K6-1-u4-X09"}],"explanation":["굴뚝 이야기가 아니에요.","싫은 마음이 아니에요.","마음의 크기가 함께 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#6','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C28',1,'mc','auto','「어디를 거쳐 어떻게 다녔는지, 다닌 길」을 무엇이라고 하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":1,"kind":"mc","stem":"「어디를 거쳐 어떻게 다녔는지, 다닌 길」을 무엇이라고 하나요?","options":[{"t":"여정","correct":true},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"감상","mis":"K6-1-u4-X27"},{"t":"끝 부분","mis":"K6-1-u4-X28"}],"explanation":["견문은 보고 들은 것이에요.","감상은 느낀 것이에요.","다닌 길은 여정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#7','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',1,'ox','auto','관용 표현은 사실을 전하는 견문 자리에 얹는 것이 좋아요.',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":7,"concept":"K6-1-u4-C36","difficulty":1,"kind":"ox","stem":"관용 표현은 사실을 전하는 견문 자리에 얹는 것이 좋아요.","answer":"X","reason_options":[{"t":"견문은 사실이라 관용 표현을 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"사실 자리에 얹어야 글이 재미있어지기 때문에","mis":"K6-1-u4-X36"}],"mis":"K6-1-u4-X36","explanation":["견문은 사실이에요.","관용 표현은 마음을 나타내요.","감상 자리에 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#8','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',1,'ox','auto','공식적인 말하기와 비공식적인 말하기에서 지킬 예절은 똑같아요.',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":8,"concept":"K6-1-u4-C42","difficulty":1,"kind":"ox","stem":"공식적인 말하기와 비공식적인 말하기에서 지킬 예절은 똑같아요.","answer":"X","reason_options":[{"t":"듣는 사람과 자리가 달라 편하게 들을 수 있는 방법도 달라지기 때문에","correct":true},{"t":"예절은 어디서나 한 가지 목록이기 때문에","mis":"K6-1-u4-X42"}],"mis":"K6-1-u4-X42","explanation":["같은 교실이라도","듣는 사람과 자리가 달라지면","예절도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#9','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C10',2,'mc','auto','이든이가 말한 「어깨가 무거워서」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X20']::text[],false,'{"seq":9,"concept":"K6-1-u4-C10","difficulty":2,"kind":"mc","stem":"이든이가 말한 「어깨가 무거워서」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"반주를 맡은 책임이 커서 마음이 무거웠다","correct":true},{"t":"악보 가방이 무거웠다","mis":"K6-1-u4-X12"},{"t":"피아노를 옮겨 어깨가 아팠다","mis":"K6-1-u4-X12"},{"t":"반주가 하기 싫었다","mis":"K6-1-u4-X20"}],"explanation":["가방 이야기가 아니에요.","어깨가 아픈 것도 아니에요.","책임이 큰 마음이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#10','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C11',2,'mc','auto','학급 안내문에 「대회가 코앞에 닥쳤으니 모두 연습해 주세요.」라고 쓴 것을 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X13','K6-1-u4-X01']::text[],false,'{"seq":10,"concept":"K6-1-u4-C11","difficulty":2,"kind":"mc","stem":"학급 안내문에 「대회가 코앞에 닥쳤으니 모두 연습해 주세요.」라고 쓴 것을 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"글로 전하는 매체에서도 관용어가 급함을 짧고 또렷하게 전한다","correct":true},{"t":"안내문에는 관용어를 쓰면 안 된다","mis":"K6-1-u4-X13"},{"t":"글로 쓰면 말로 할 때와 뜻이 달라진다","mis":"K6-1-u4-X13"},{"t":"코앞에 물건을 두라는 뜻이다","mis":"K6-1-u4-X01"}],"explanation":["안내문에도 쓸 수 있어요.","뜻은 그대로예요.","매체가 달라도 하는 일은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#11','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C28',2,'mc','auto','「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」는 무엇에 해당하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":11,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」는 무엇에 해당하나요?","options":[{"t":"감상","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"견학한 까닭","mis":"K6-1-u4-X28"}],"explanation":["다닌 길이 아니에요.","새로 안 사실이 아니에요.","놀란 마음이에요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#12','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C35',2,'mc','auto','로아 글 뒷부분의 모래와 자갈 층 문장 뒤에 무엇을 붙이면 본 것과 느낀 것이 짝지어질까요?',ARRAY['K6-1-u4-X35','K6-1-u4-X07']::text[],false,'{"seq":12,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"로아 글 뒷부분의 모래와 자갈 층 문장 뒤에 무엇을 붙이면 본 것과 느낀 것이 짝지어질까요?","options":[{"t":"「모래와 자갈만으로 물이 걸러진다니 신기했다.」처럼 그때의 마음 한 문장","correct":true},{"t":"모래가 몇 층인지 같은 사실 문장 하나 더","mis":"K6-1-u4-X35"},{"t":"관용 표현 세 개","mis":"K6-1-u4-X07"},{"t":"아무것도 붙이지 않고 다음 문장으로","mis":"K6-1-u4-X35"}],"explanation":["사실을 더하면 사실만 늘어요.","개수는 문제가 아니에요.","본 것 뒤에 마음을 붙여요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#13','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C38',2,'mc','auto','로아가 글을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07']::text[],false,'{"seq":13,"concept":"K6-1-u4-C38","difficulty":2,"kind":"mc","stem":"로아가 글을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학한 까닭이 드러나는가","correct":true},{"t":"글씨를 예쁘게 썼는가","mis":"K6-1-u4-X38"},{"t":"짝의 글보다 긴가","mis":"K6-1-u4-X38"},{"t":"관용 표현을 많이 넣었는가","mis":"K6-1-u4-X07"}],"explanation":["글씨는 갈래를 정하지 않아요.","길이도 아니에요.","견학 기록문이 갖출 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#14','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C29',2,'mc','auto','로아의 조직표 끝 칸을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X28']::text[],false,'{"seq":14,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아의 조직표 끝 칸을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"물이 여러 단계를 거친다는 것을 정리하고, 물을 아껴 쓰겠다는 깨달은 점을 쓴다","correct":true},{"t":"「정말 정말 재미있었다」로 늘린다","mis":"K6-1-u4-X30"},{"t":"새로 본 시설을 끝에 더한다","mis":"K6-1-u4-X28"},{"t":"끝 칸을 처음 칸과 바꾼다","mis":"K6-1-u4-X28"}],"explanation":["느낌만 늘리면 일기 같아요.","새 견문은 가운데예요.","끝에는 정리와 깨달음을 써요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#15','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C13',2,'mc','auto','「귀에 익다」의 뜻을 몰라 찾을 때 알맞은 순서는 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X11','K6-1-u4-X10']::text[],false,'{"seq":15,"concept":"K6-1-u4-C13","difficulty":2,"kind":"mc","stem":"「귀에 익다」의 뜻을 몰라 찾을 때 알맞은 순서는 어느 것인가요?","options":[{"t":"앞뒤 상황으로 짐작 → 「귀」를 사전에서 찾아 뜻풀이 아래 관용구 → 짐작과 맞춰 보기","correct":true},{"t":"사전의 첫 쪽부터 넘기기 → 나올 때까지 읽기","mis":"K6-1-u4-X14"},{"t":"뜻은 모른 채 「귀에 익다」를 통째로 외우기","mis":"K6-1-u4-X11"},{"t":"짐작한 뜻을 찾아보지 않고 정답으로 삼기","mis":"K6-1-u4-X10"}],"explanation":["첫 쪽부터는 오래 걸려요.","뜻을 모른 채 외우면 쓰지 못해요.","짐작한 뒤 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#16','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',2,'ox','auto','태하가 발표가 끝난 뒤 존댓말로 질문한 것은 공식적인 말하기 예절에 맞아요.',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"ox","stem":"태하가 발표가 끝난 뒤 존댓말로 질문한 것은 공식적인 말하기 예절에 맞아요.","answer":"O","reason_options":[{"t":"발표를 끝까지 듣고 여럿이 듣는 자리에 맞게 존댓말을 썼기 때문에","correct":true},{"t":"질문은 언제나 반말로 해야 하기 때문에","mis":"K6-1-u4-X42"}],"mis":"K6-1-u4-X42","explanation":["끝까지 들었어요.","끝난 뒤 물었어요.","자리에 맞게 존댓말을 썼어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#17','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C7',3,'mc','auto','「입에 침이 마르다」를 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08']::text[],false,'{"seq":17,"concept":"K6-1-u4-C7","difficulty":3,"kind":"mc","stem":"「입에 침이 마르다」를 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"「할머니께서는 손주 자랑에 입에 침이 마르셨다.」","correct":true},{"t":"「물을 오래 안 마셔 입에 침이 말랐다.」","mis":"K6-1-u4-X01"},{"t":"「짝이 미워서 입에 침이 마르게 흉을 보았다.」","mis":"K6-1-u4-X08"},{"t":"「비밀을 지키느라 입에 침이 말랐다.」","mis":"K6-1-u4-X08"}],"explanation":["실제로 침이 마른 이야기예요.","거듭 칭찬하는 뜻과 어긋나요.","거듭 칭찬하는 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#18','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C14',3,'mc','auto','「작은 잘못을 그냥 넘기다 보면 큰 잘못이 된다」는 교훈을 담은 속담은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":18,"concept":"K6-1-u4-C14","difficulty":3,"kind":"mc","stem":"「작은 잘못을 그냥 넘기다 보면 큰 잘못이 된다」는 교훈을 담은 속담은 어느 것인가요?","options":[{"t":"바늘 도둑이 소도둑 된다","correct":true},{"t":"첫술에 배부르랴","mis":"K6-1-u4-X16"},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X16"},{"t":"서당 개 삼 년이면 풍월을 읊는다","mis":"K6-1-u4-X16"}],"explanation":["한 번에 안 된다는 교훈이에요.","떠드는 이야기예요.","보고 익히는 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#19','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C25',3,'mc','auto','관용 표현으로 대화하기가 부담스러운 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X24']::text[],false,'{"seq":19,"concept":"K6-1-u4-C25","difficulty":3,"kind":"mc","stem":"관용 표현으로 대화하기가 부담스러운 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「쓰고 싶은 상황을 떠올려 공책에 적어 보는 것부터 해 보자.」","correct":true},{"t":"「앞에 나와 크게 말할 때까지 연습해.」","mis":"K6-1-u4-X24"},{"t":"「말로 못 하면 배우지 못한 거야.」","mis":"K6-1-u4-X24"},{"t":"「그럼 관용 표현은 배우지 마.」","mis":"K6-1-u4-X24"}],"explanation":["처음부터 크게 말하지 않아도 돼요.","말 못 해도 배운 거예요.","할 수 있는 만큼부터 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#20','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',3,'mc','auto','「종이는 습기와 더위에 약해서 온도와 습도를 일정하게 지킨다」는 문장에 관용 표현을 얹지 않는 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X36','K6-1-u4-X09']::text[],false,'{"seq":20,"concept":"K6-1-u4-C36","difficulty":3,"kind":"mc","stem":"「종이는 습기와 더위에 약해서 온도와 습도를 일정하게 지킨다」는 문장에 관용 표현을 얹지 않는 까닭은 어느 것인가요?","options":[{"t":"사실을 전하는 견문 자리라 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"관용 표현은 글 끝에만 쓸 수 있기 때문에","mis":"K6-1-u4-X36"},{"t":"서고와 관련된 관용 표현이 없기 때문에","mis":"K6-1-u4-X36"},{"t":"관용 표현은 견학 기록문에 쓰면 안 되기 때문에","mis":"K6-1-u4-X09"}],"explanation":["끝에만 쓰는 것이 아니에요.","관련 표현이 있고 없고가 아니에요.","견문은 사실을 전해요."],"asset":{"type":"passage","lines":["다음으로 간 보존 서고는 공기가 서늘했다.","종이는 습기와 더위에 약해서 온도와 습도를 늘 일정하게 지킨다고 했다.","오래된 책은 따로 두고, 넘길 때에도 두 손으로 조심해 다룬다고 한다.","표지가 닳고 손때가 묻은 책들이 나란히 서 있는 모습을 한참 바라보았다.","이번 견학으로 도서관이 책을 지키는 곳이라는 것을 알게 되었다."],"title":"「도서관 서고를 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#21','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C35',3,'mc','auto','생각그물과 조직표를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X35']::text[],false,'{"seq":21,"concept":"K6-1-u4-C35","difficulty":3,"kind":"mc","stem":"생각그물과 조직표를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"생각그물로 떠오르는 대로 모은 뒤 조직표에서 처음 · 가운데 · 끝으로 순서를 잡는다","correct":true},{"t":"조직표로 순서를 먼저 정하고 생각그물은 쓰지 않는다","mis":"K6-1-u4-X35"},{"t":"생각그물만 그리고 바로 글을 끝낸다","mis":"K6-1-u4-X35"},{"t":"둘 다 쓰지 않고 떠오르는 대로 쓴다","mis":"K6-1-u4-X35"}],"explanation":["재료부터 모아요.","순서도 잡아야 해요.","모으고, 나누고, 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#22','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',3,'mc','auto','같은 교실에서 학급 회의 때 의견을 말할 때와 짝과 회의 준비를 이야기할 때 예절이 다른 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":22,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"같은 교실에서 학급 회의 때 의견을 말할 때와 짝과 회의 준비를 이야기할 때 예절이 다른 까닭은 어느 것인가요?","options":[{"t":"같은 교실이어도 듣는 사람과 자리가 달라 편하게 듣는 방법이 달라지기 때문에","correct":true},{"t":"교실이 같으니 예절도 같다","mis":"K6-1-u4-X42"},{"t":"회의 때만 예절이 있다","mis":"K6-1-u4-X43"},{"t":"짝과 이야기할 때는 예절이 필요 없다","mis":"K6-1-u4-X43"}],"explanation":["교실이 같아도 자리가 달라요.","어느 자리에나 예절이 있어요.","듣는 사람을 두고 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#23','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C29',4,'mc','auto','로아의 조직표 전체를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X35','K6-1-u4-X28']::text[],false,'{"seq":23,"concept":"K6-1-u4-C29","difficulty":4,"kind":"mc","stem":"로아의 조직표 전체를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"처음에 견학한 까닭을 더하고, 가운데마다 느낀 것을 하나씩 짝짓고, 끝에 정리와 깨달은 점을 쓴다","correct":true},{"t":"끝의 「정말 재미있었다」를 세 번 쓴다","mis":"K6-1-u4-X30"},{"t":"가운데 칸을 하나로 합치고 느낌은 뺀다","mis":"K6-1-u4-X35"},{"t":"처음을 지우고 가운데부터 시작한다","mis":"K6-1-u4-X28"}],"explanation":["느낌만 늘리면 일기 같아요.","느낌을 빼면 사실만 남아요.","세 부분을 모두 고쳐요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#24','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',4,'essay','teacher','로아 글 뒷부분에 관용 표현을 하나 넣는다면 어느 문장 뒤에 어떤 표현을 넣을지 쓰고, 그 자리를 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C36","difficulty":4,"kind":"essay","stem":"로아 글 뒷부분에 관용 표현을 하나 넣는다면 어느 문장 뒤에 어떤 표현을 넣을지 쓰고, 그 자리를 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.」 뒤에 「그동안 물을 펑펑 쓴 것을 생각하니 낯이 뜨거웠다.」를 넣겠다. 이 문장은 깨달은 마음이 드러나는 감상 자리라서 관용 표현이 잘 어울린다. 소독이나 모래층처럼 사실을 전하는 견문 자리에 넣으면 무엇이 사실인지 흐려진다.","scoring_points":["넣을 자리와 관용 표현을 썼는가","그 자리가 감상 자리라는 까닭을 썼는가","견문 자리에 넣지 않는 까닭을 썼는가"]},"explanation":["마음이 드러난 문장을 찾아요.","어울리는 표현을 골라요.","견문 자리와 견줘요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#25','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C21',4,'essay','teacher','「관용 표현을 고르는 일은 전하고 싶은 마음을 고르는 일이다」라는 말을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C21","difficulty":4,"kind":"essay","stem":"「관용 표현을 고르는 일은 전하고 싶은 마음을 고르는 일이다」라는 말을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 「정말 하고 싶었다」라고 말하면 뜻은 통하지만, 「마음이 굴뚝같았다」라고 하면 얼마나 하고 싶었는지 그 마음의 크기까지 전해진다. 또 「내가 먼저 가 볼게」 대신 「목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게」라고 하면 나서는 까닭과 마음이 함께 전해진다. 그래서 관용 표현을 고르는 것은 어떤 마음을 전할지 고르는 일이다.","scoring_points":["그냥 말한 것과 관용 표현을 견준 예를 들었는가","관용 표현으로 더 전해지는 마음을 썼는가","마음을 고르는 일이라는 뜻을 정리했는가"]},"explanation":["그냥 말한 것과 견줘요.","더 전해지는 것을 찾아요.","마음을 고르는 일로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#1','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C3',1,'mc','auto','예로부터 전해 오며 지혜나 교훈을 담은 말을 무엇이라고 하나요?',ARRAY['K6-1-u4-X04','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C3","difficulty":1,"kind":"mc","stem":"예로부터 전해 오며 지혜나 교훈을 담은 말을 무엇이라고 하나요?","options":[{"t":"속담","correct":true},{"t":"관용어","mis":"K6-1-u4-X04"},{"t":"줄임말","mis":"K6-1-u4-X15"},{"t":"표어","mis":"K6-1-u4-X15"}],"explanation":["관용어는 교훈을 꼭 담지는 않아요.","줄임말은 전해 오는 말이 아니에요.","교훈을 담고 전해 오면 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#2','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C6',1,'mc','auto','관용 표현을 쓸 때 가장 먼저 살필 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X40']::text[],false,'{"seq":2,"concept":"K6-1-u4-C6","difficulty":1,"kind":"mc","stem":"관용 표현을 쓸 때 가장 먼저 살필 것은 어느 것인가요?","options":[{"t":"지금 이 상황에 어울리는가","correct":true},{"t":"몇 개나 넣었는가","mis":"K6-1-u4-X07"},{"t":"얼마나 어려운 표현인가","mis":"K6-1-u4-X40"},{"t":"몇 글자인가","mis":"K6-1-u4-X07"}],"explanation":["개수가 먼저가 아니에요.","어려운 표현이 좋은 것도 아니에요.","상황에 어울리는지가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#3','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C8',1,'ox','auto','모르는 관용어는 앞뒤 상황을 보고 먼저 짐작해 봐요.',ARRAY['K6-1-u4-X10']::text[],false,'{"seq":3,"concept":"K6-1-u4-C8","difficulty":1,"kind":"ox","stem":"모르는 관용어는 앞뒤 상황을 보고 먼저 짐작해 봐요.","answer":"O","reason_options":[{"t":"짐작한 뒤 사전에서 확인하면 뜻이 오래 남기 때문에","correct":true},{"t":"짐작하면 틀리니 사전부터 펴야 하기 때문에","mis":"K6-1-u4-X10"}],"mis":"K6-1-u4-X10","explanation":["정확히 몰라도 괜찮아요.","앞뒤 상황이 실마리예요.","짐작한 뒤 사전으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#4','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C18',1,'mc','auto','속담을 사전에서 찾을 때 앞세울 것은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":4,"concept":"K6-1-u4-C18","difficulty":1,"kind":"mc","stem":"속담을 사전에서 찾을 때 앞세울 것은 어느 것인가요?","options":[{"t":"속담에서 중심이 되는 낱말","correct":true},{"t":"속담 전체 문장","mis":"K6-1-u4-X14"},{"t":"사전의 맨 첫 쪽","mis":"K6-1-u4-X14"},{"t":"속담이 생긴 때","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로 찾지 않아요.","첫 쪽부터 넘기지 않아요.","중심 낱말을 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#5','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C23',1,'mc','auto','「낯이 뜨겁다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":5,"concept":"K6-1-u4-C23","difficulty":1,"kind":"mc","stem":"「낯이 뜨겁다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?","options":[{"t":"고개를 들지 못하다","correct":true},{"t":"코앞에 닥치다","mis":"K6-1-u4-X22"},{"t":"목이 빠지게 기다리다","mis":"K6-1-u4-X22"},{"t":"어깨가 무겁다","mis":"K6-1-u4-X22"}],"explanation":["코앞에 닥치다는 급함이에요.","목이 빠지게 기다리다는 간절함이에요.","부끄러운 마음끼리 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#6','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C29',1,'ox','auto','견학 기록문의 끝 부분에는 견학한 내용을 정리하고 깨달은 점을 써요.',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C29","difficulty":1,"kind":"ox","stem":"견학 기록문의 끝 부분에는 견학한 내용을 정리하고 깨달은 점을 써요.","answer":"O","reason_options":[{"t":"끝은 견학을 정리하고 마무리하는 자리이기 때문에","correct":true},{"t":"끝에는 견학한 까닭과 장소를 처음 밝혀야 하기 때문에","mis":"K6-1-u4-X28"}],"mis":"K6-1-u4-X28","explanation":["까닭과 장소는 처음이에요.","본 것은 가운데예요.","끝에서 정리하고 깨달은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#7','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C38',1,'mc','auto','쓴 견학 기록문을 나눌 방법을 고르는 기준은 어느 것인가요?',ARRAY['K6-1-u4-X39','K6-1-u4-X38']::text[],false,'{"seq":7,"concept":"K6-1-u4-C38","difficulty":1,"kind":"mc","stem":"쓴 견학 기록문을 나눌 방법을 고르는 기준은 어느 것인가요?","options":[{"t":"내가 정한 읽을 사람이 정말 읽을 수 있는가","correct":true},{"t":"가장 많이 인쇄할 수 있는가","mis":"K6-1-u4-X39"},{"t":"가장 빨리 끝나는가","mis":"K6-1-u4-X39"},{"t":"가장 예뻐 보이는가","mis":"K6-1-u4-X38"}],"explanation":["많이 인쇄한다고 읽는 것이 아니에요.","빨리 끝나는 것이 기준이 아니에요.","읽을 사람에게 닿는지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#8','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',1,'mc','auto','「어깨너머로 배우다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01','K6-1-u4-X22']::text[],false,'{"seq":8,"concept":"K6-1-u4-C39","difficulty":1,"kind":"mc","stem":"「어깨너머로 배우다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"옆에서 보고 들으며 배우다","correct":true},{"t":"어깨를 다쳐 쉬면서 배우다","mis":"K6-1-u4-X12"},{"t":"친구 어깨 위에 올라가 보다","mis":"K6-1-u4-X01"},{"t":"하기 싫은 사람을 억지로 나서게 하다","mis":"K6-1-u4-X22"}],"explanation":["다친 이야기가 아니에요.","어깨 위에 오른 것도 아니에요.","옆에서 보고 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#9','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C15',2,'mc','auto','이든이가 「첫술에 배부르랴」를 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X16']::text[],false,'{"seq":9,"concept":"K6-1-u4-C15","difficulty":2,"kind":"mc","stem":"이든이가 「첫술에 배부르랴」를 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번에 잘되지 않아도 조금씩 나아질 것이라는 마음을 전하려고","correct":true},{"t":"밥을 먹고 연습하겠다고 하려고","mis":"K6-1-u4-X01"},{"t":"이번 대회는 포기하겠다고 하려고","mis":"K6-1-u4-X16"},{"t":"처음부터 완벽해야 한다고 하려고","mis":"K6-1-u4-X16"}],"explanation":["밥 이야기가 아니에요.","포기하는 말이 아니에요.","한 번에 되지 않아도 괜찮다는 말이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#10','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C22',2,'ox','auto','「소금 장수와 나루터」에서 「급할수록 돌아가라」는 이야기가 담은 지혜를 한마디로 전해요.',ARRAY['K6-1-u4-X21']::text[],false,'{"seq":10,"concept":"K6-1-u4-C22","difficulty":2,"kind":"ox","stem":"「소금 장수와 나루터」에서 「급할수록 돌아가라」는 이야기가 담은 지혜를 한마디로 전해요.","answer":"O","reason_options":[{"t":"서두르는 대신 돌아가 얕은 여울목으로 건넌 소금 장수의 행동과 이어지기 때문에","correct":true},{"t":"실제로 먼 길을 돌아가라는 뜻만 있기 때문에","mis":"K6-1-u4-X21"}],"mis":"K6-1-u4-X21","explanation":["소금 장수는 서두르지 않았어요.","다른 길을 찾았어요.","돌아가는 지혜가 담겼어요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#11','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C27',2,'mc','auto','로아의 글이 견학 기록문으로서 믿을 만한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X07','K6-1-u4-X30']::text[],false,'{"seq":11,"concept":"K6-1-u4-C27","difficulty":2,"kind":"mc","stem":"로아의 글이 견학 기록문으로서 믿을 만한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"새로 안 사실(알갱이를 뭉쳐 가라앉힘)이 실제로 참인 내용이기 때문에","correct":true},{"t":"재미있게 지어낸 사실이 많기 때문에","mis":"K6-1-u4-X26"},{"t":"관용 표현을 많이 넣었기 때문에","mis":"K6-1-u4-X07"},{"t":"느낌만 솔직하게 적었기 때문에","mis":"K6-1-u4-X30"}],"explanation":["지어낸 사실은 믿을 수 없어요.","관용 표현 개수와는 상관없어요.","새로 안 사실이 참이어야 해요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#12','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C30',2,'ox','auto','로아 글에서 「입이 딱 벌어졌다」 같은 감상을 모두 지우면 안내문에 가까워져요.',ARRAY['K6-1-u4-X29']::text[],false,'{"seq":12,"concept":"K6-1-u4-C30","difficulty":2,"kind":"ox","stem":"로아 글에서 「입이 딱 벌어졌다」 같은 감상을 모두 지우면 안내문에 가까워져요.","answer":"O","reason_options":[{"t":"감상이 빠지면 사실만 남기 때문에","correct":true},{"t":"감상이 없어도 견학 기록문이 되기 때문에","mis":"K6-1-u4-X29"}],"mis":"K6-1-u4-X29","explanation":["감상은 마음이에요.","마음이 빠지면 사실만 남아요.","사실만 남으면 안내문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#13','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C34',2,'mc','auto','로아가 이 글을 저학년 동생에게 읽어 준다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X34','K6-1-u4-X07']::text[],false,'{"seq":13,"concept":"K6-1-u4-C34","difficulty":2,"kind":"mc","stem":"로아가 이 글을 저학년 동생에게 읽어 준다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「소독」 「약품」처럼 어려운 낱말을 쉽게 풀어 말한다","correct":true},{"t":"새로 안 사실을 모두 뺀다","mis":"K6-1-u4-X30"},{"t":"쓴 그대로 읽는다","mis":"K6-1-u4-X34"},{"t":"관용 표현을 더 넣는다","mis":"K6-1-u4-X07"}],"explanation":["견문을 빼면 안 돼요.","읽을 사람을 생각해요.","동생이 알 수 있게 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#14','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C33',2,'ox','auto','로아가 조직표를 짜기 전에 왜 정수장이 기억에 남았는지 한 줄로 적어 두면 감상을 쓰기 쉬워요.',ARRAY['K6-1-u4-X33']::text[],false,'{"seq":14,"concept":"K6-1-u4-C33","difficulty":2,"kind":"ox","stem":"로아가 조직표를 짜기 전에 왜 정수장이 기억에 남았는지 한 줄로 적어 두면 감상을 쓰기 쉬워요.","answer":"O","reason_options":[{"t":"기억에 남은 까닭이 곧 글의 감상이 되기 때문에","correct":true},{"t":"까닭은 글에 쓰지 않는 것이기 때문에","mis":"K6-1-u4-X33"}],"mis":"K6-1-u4-X33","explanation":["까닭을 먼저 적어요.","그 까닭이 마음이에요.","감상으로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#15','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',2,'mc','auto','「놀람 · 부끄러움 · 간절함」처럼 묶은 관용 표현 사전을 알맞게 설명한 것은 어느 것인가요?',ARRAY['K6-1-u4-X44']::text[],false,'{"seq":15,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"「놀람 · 부끄러움 · 간절함」처럼 묶은 관용 표현 사전을 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"마음으로 묶은 사전이라 쓸 때 꺼내기 쉽다","correct":true},{"t":"낱말로 묶은 사전이라 찾기 쉽다","mis":"K6-1-u4-X44"},{"t":"아무렇게나 묶은 사전이다","mis":"K6-1-u4-X44"},{"t":"묶지 않아 흩어진 사전이다","mis":"K6-1-u4-X44"}],"explanation":["같은 낱말로 묶은 것이 아니에요.","같은 마음끼리 묶었어요.","마음으로 묶으면 쓰기가 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#16','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',2,'mc','auto','시온이의 발표를 고칠 때 세울 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"시온이의 발표를 고칠 때 세울 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 친구들이 편하게 들을 수 있는가","correct":true},{"t":"예절 목록을 몇 개 지켰는가","mis":"K6-1-u4-X43"},{"t":"시온이가 편하게 말할 수 있는가","mis":"K6-1-u4-X43"},{"t":"발표가 얼마나 짧은가","mis":"K6-1-u4-X43"}],"explanation":["목록 개수가 기준이 아니에요.","말하는 사람이 기준이 아니에요.","듣는 사람을 두고 정해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#17','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C6',3,'mc','auto','텃밭 일기 한 편에 관용 표현 네 개를 모두 넣으려는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":17,"concept":"K6-1-u4-C6","difficulty":3,"kind":"mc","stem":"텃밭 일기 한 편에 관용 표현 네 개를 모두 넣으려는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상황에 꼭 맞는 하나를 골라 제자리에 놓자","correct":true},{"t":"넷 다 넣으면 더 생생해지니 그대로 넣자","mis":"K6-1-u4-X07"},{"t":"더 찾아서 다섯 개로 늘리자","mis":"K6-1-u4-X07"},{"t":"넷 모두 낱말 뜻대로 풀어 쓰자","mis":"K6-1-u4-X06"}],"explanation":["많이 넣으면 뜻이 흐려져요.","개수를 늘릴 일이 아니에요.","제자리에 하나가 힘이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#18','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C18',3,'mc','auto','인터넷 사전으로 속담을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X10']::text[],false,'{"seq":18,"concept":"K6-1-u4-C18","difficulty":3,"kind":"mc","stem":"인터넷 사전으로 속담을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"중심 낱말을 검색한 뒤 관용구와 속담을 갈라 보는 기능을 쓴다","correct":true},{"t":"속담 사전의 첫 쪽부터 넘긴다","mis":"K6-1-u4-X14"},{"t":"짐작한 뜻을 검색해 바로 정답으로 삼는다","mis":"K6-1-u4-X10"},{"t":"속담과 상관없는 낱말을 아무거나 넣는다","mis":"K6-1-u4-X14"}],"explanation":["인터넷 사전은 넘기지 않아요.","짐작은 확인해야 해요.","중심 낱말을 앞세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#19','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C26',3,'mc','auto','「발등에 불이 떨어지다」로 짧은 대화를 지을 때 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X25']::text[],false,'{"seq":19,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"「발등에 불이 떨어지다」로 짧은 대화를 지을 때 알맞은 상황은 어느 것인가요?","options":[{"t":"숙제 마감이 내일 아침인데 아직 시작하지 않은 동생에게 형이 말하는 장면","correct":true},{"t":"불꽃놀이를 구경하는 장면","mis":"K6-1-u4-X01"},{"t":"시간이 많이 남아 느긋한 장면","mis":"K6-1-u4-X25"},{"t":"상을 받아 기뻐하는 장면","mis":"K6-1-u4-X25"}],"explanation":["실제 불 이야기가 아니에요.","느긋한 것과 반대예요.","몹시 급한 상황에 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#20','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C27',3,'mc','auto','견학한 곳을 이름 없는 곳으로 지어 쓸 때 꼭 지켜야 할 것은 어느 것인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X29']::text[],false,'{"seq":20,"concept":"K6-1-u4-C27","difficulty":3,"kind":"mc","stem":"견학한 곳을 이름 없는 곳으로 지어 쓸 때 꼭 지켜야 할 것은 어느 것인가요?","options":[{"t":"그 안에서 새로 안 사실은 실제로 참이어야 한다","correct":true},{"t":"새로 안 사실도 마음껏 지어도 된다","mis":"K6-1-u4-X26"},{"t":"견학한 곳은 반드시 유명한 곳이어야 한다","mis":"K6-1-u4-X26"},{"t":"감상은 빼야 한다","mis":"K6-1-u4-X29"}],"explanation":["사실을 지으면 거짓을 전해요.","이름 없는 곳도 괜찮아요.","무대는 지어도 사실은 참이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#21','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C32',3,'mc','auto','견학 기록문을 쓰는 까닭을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u4-X32','K6-1-u4-X37']::text[],false,'{"seq":21,"concept":"K6-1-u4-C32","difficulty":3,"kind":"mc","stem":"견학 기록문을 쓰는 까닭을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"쓰는 사람에게도 남고, 읽는 사람에게도 건너간다","correct":true},{"t":"글씨 연습과 낱말 외우기에 좋다","mis":"K6-1-u4-X32"},{"t":"정해진 칸을 채우는 연습이 된다","mis":"K6-1-u4-X37"},{"t":"견학 숙제를 빨리 끝낼 수 있다","mis":"K6-1-u4-X32"}],"explanation":["글씨 연습이 목적이 아니에요.","칸 채우기가 아니에요.","남기고, 전하고, 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#22','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',3,'mc','auto','동물이 든 표현과 몸이 든 표현으로 나눈 사전의 좋은 점은 어느 것인가요?',ARRAY['K6-1-u4-X11','K6-1-u4-X44','K6-1-u4-X40']::text[],false,'{"seq":22,"concept":"K6-1-u4-C39","difficulty":3,"kind":"mc","stem":"동물이 든 표현과 몸이 든 표현으로 나눈 사전의 좋은 점은 어느 것인가요?","options":[{"t":"같은 낱말로 묶어 필요할 때 빨리 찾을 수 있다","correct":true},{"t":"쓸 상황을 적지 않아도 된다","mis":"K6-1-u4-X11"},{"t":"마음으로 묶은 것과 똑같다","mis":"K6-1-u4-X44"},{"t":"표현 개수가 저절로 많아진다","mis":"K6-1-u4-X40"}],"explanation":["쓸 상황은 늘 적어요.","마음으로 묶은 것과는 달라요.","낱말로 묶으면 찾기가 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#23','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',4,'mc','auto','시온이네 반 발표 장면 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":23,"concept":"K6-1-u4-C42","difficulty":4,"kind":"mc","stem":"시온이네 반 발표 장면 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"시온이는 목소리 크기 · 자세 · 존댓말을, 다인이는 경청을 고쳐야 하고, 태하는 공식적인 자리에 맞게 말했다","correct":true},{"t":"세 사람 모두 예절을 잘 지켰다","mis":"K6-1-u4-X42"},{"t":"태하가 끼어들어 잘못했다","mis":"K6-1-u4-X43"},{"t":"다인이는 작은 소리라 괜찮고 시온이만 고치면 된다","mis":"K6-1-u4-X43"}],"explanation":["잘못한 사람이 있어요.","태하는 끝난 뒤 물었어요.","다인이도 경청하지 않았어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#24','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',4,'essay','teacher','시온이의 발표를 공식적인 말하기 예절에 맞게 고쳐 쓰고, 「듣는 사람이 편하게 들을 수 있는가」라는 기준으로 고친 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C42","difficulty":4,"kind":"essay","stem":"시온이의 발표를 공식적인 말하기 예절에 맞게 고쳐 쓰고, 「듣는 사람이 편하게 들을 수 있는가」라는 기준으로 고친 까닭을 설명하세요.","answer_guide":{"answer":"예: (반 친구들을 바라보며, 모두에게 들리는 목소리로) 「저희 모둠은 정수장에 대해 알아보았습니다. 정수장에서는 물을 여러 단계를 거쳐 깨끗하게 만든다고 합니다.」 여럿이 듣는 자리라 작은 목소리로는 뒤쪽 친구들이 들을 수 없고, 칠판을 보고 말하면 듣는 사람이 집중하기 어렵다. 또 공식적인 자리이므로 존댓말을 써야 듣는 사람이 편하게 들을 수 있다.","scoring_points":["존댓말로 고쳐 썼는가","목소리 크기와 자세를 고쳤는가","듣는 사람을 기준으로 까닭을 설명했는가"]},"explanation":["말을 고쳐요.","목소리와 자세도 고쳐요.","듣는 사람을 두고 설명해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#25','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C41',4,'essay','teacher','나만의 관용 표현 사전에 넣을 표현 하나를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰고, 그 표현을 고른 기준을 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C41","difficulty":4,"kind":"essay","stem":"나만의 관용 표현 사전에 넣을 표현 하나를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰고, 그 표현을 고른 기준을 설명하세요.","answer_guide":{"answer":"예: 표현 — 귀에 익다. 뜻 — 여러 번 들어 익숙하다. 쓸 수 있는 상황 — 처음 배우는 노래인데 엄마가 자주 부르셔서 이미 익숙할 때. 고른 기준 — 어렵거나 멋있어 보이는 표현보다 이번 달에 내가 실제로 쓸 자리가 떠오르는 표현이라서 골랐다.","scoring_points":["표현과 뜻을 바르게 썼는가","내가 겪은 쓸 상황을 썼는가","내가 쓸 자리가 떠오르는가라는 기준을 썼는가"]},"explanation":["표현을 하나 골라요.","세 칸을 채워요.","고른 기준을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
